import re
from fractions import Fraction

class CalcError(Exception):
    """Custom exception for arithmetic calculation errors."""
    def __init__(self, message, position):
        super().__init__(message)
        self.position = position

class Token:
    """Represents a token in the expression."""
    def __init__(self, value, start_index):
        self.value = value
        self.start_index = start_index

    def __repr__(self):
        return f"Token(value={self.value!r}, start_index={self.start_index})"

def tokenize(expr: str) -> list[Token]:
    """Parses an arithmetic expression string into a list of tokens."""
    tokens = []
    i = 0
    n = len(expr)

    # Helper function to check if a character is whitespace
    def is_whitespace(char):
        return char in ' \t'

    while i < n:
        char = expr[i]

        # 1. Skip whitespace
        if is_whitespace(char):
            i += 1
            continue

        # 2. Handle Numbers
        elif char.isdigit() or char == '.':
            start = i

            if char == '.':
                # If it starts with '.', it must be followed by a digit (e.g., '.5' is valid, but '.' alone is not).
                if i + 1 >= n or not expr[i+1].isdigit():
                    raise CalcError("Invalid number format: leading decimal point or incomplete number", i)
                i += 1

            # Consume digits and potential decimal point
            while i < n and (expr[i].isdigit() or expr[i] == '.'):
                i += 1

            value_str = expr[start:i]

            # Validate number structure based on rules
            if value_str.count('.') > 1:
                raise CalcError("Invalid number format: multiple decimal points", start)

            parts = value_str.split('.')

            # Rule: one or more digits, optionally followed by '.' and one or more digits.
            if len(parts) == 1: # Integer case
                if not parts[0].isdigit() or not parts[0]:
                     raise CalcError("Invalid number format: must contain digits", start)
            elif len(parts) == 2: # Decimal case
                if not parts[0] or not parts[1]:
                    raise CalcError("Invalid number format: missing digits around decimal point", start)

            tokens.append(Token(value_str, start))
            continue

        # 3. Handle Operators and Parentheses
        elif char in '+-*/()':
            tokens.append(Token(char, i))
            i += 1
            continue

        # 4. Error Handling (Invalid character)
        else:
            # Error position is the current index i
            raise CalcError(f"Invalid character: {char}", i)

    return tokens

class Parser:
    """Parses a list of tokens into an abstract syntax tree (conceptually) while enforcing syntax."""
    def __init__(self, tokens: list[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token | None:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def advance(self) -> Token:
        if self.pos >= len(self.tokens):
            raise CalcError("Unexpected end of expression", len(self.tokens))
        token = self.tokens[self.pos]
        self.pos += 1
        return token

    def eat(self, expected_values: list): 
        token = self.current_token()
        if not token or token.value not in expected_values:
            # If we expected a specific token and got something else, or ran out of tokens
            pos = token.start_index if token else len(self.tokens)
            raise CalcError(f"Expected one of {expected_values}, got {token.value if token else 'EOF'}", pos)
        self.advance()

    # Grammar rules implementation

    def parse_primary(self): 
        # Handles numbers and parenthesized expressions, and unary minus
        token = self.current_token()
        if not token:
            raise CalcError("Expected an expression, found end of input", len(self.tokens))

        # Handle Unary Minus
        if token.value == '-':
            # Check if '-' is unary.
            if self.pos == 0 or self.tokens[self.pos-1].value in '(*+/' or self.tokens[self.pos-1].value == '(':
                self.advance() # Consume '-' 
                # Recursively call parse_primary to handle the expression following the unary minus
                # We wrap the result in a tuple structure for uniform evaluation, treating unary negation as 0 * (-1)
                sub_result = self.parse_primary()
                return (sub_result, '-', Token('-', token.start_index))

        # Handle Parentheses
        elif token.value == '(': 
            self.advance() # Consume '(' 
            # Recursively parse the sub-expression
            result = self.parse_expression() 
            self.eat([')']) # Must be followed by ')'
            return result

        # Handle Numbers (Factor)
        elif token.value.replace('.', '', 1).isdigit() or (token.value.startswith('.') and token.value[1:].isdigit()):
            self.advance()
            # Return the value string, which will be interpreted as Fraction in the evaluator
            return token.value 

        # Error: Not a valid start of a primary expression
        else:
            if token.value in '+-*/' or token.value == ')' :
                raise CalcError(f"Unexpected token: {token.value}", token.start_index)
            raise CalcError(f"Unexpected token at start of expression: {token.value}", token.start_index)

    def parse_term(self): 
        # Handles multiplication and division (*, /)
        left = self.parse_primary()
        while self.current_token() and self.current_token().value in '*/':
            op_token = self.advance() # Consume * or / 
            right = self.parse_primary()
            # Store the operator token object itself to retain position info
            left = (left, op_token, right) 
        return left

    def parse_expression(self): 
        # Handles addition and subtraction (+, -)
        left = self.parse_term()
        while self.current_token() and self.current_token().value in '+-':
            op_token = self.advance() # Consume + or - 
            right = self.parse_term()
            # Store the operator token object itself
            left = (left, op_token, right) 
        return left

    def parse(self):
        # Main entry point for syntax validation
        if not self.tokens: 
            return None

        self.parse_expression()

        # Check for trailing garbage
        if self.current_token() is not None:
            token = self.current_token()
            if token.value in ')*]':
                 raise CalcError(f"Unexpected trailing token: {token.value}", token.start_index)
            if token.value in '+-*/':
                raise CalcError(f"Trailing operator: {token.value}", token.start_index)

        return True # Successfully parsed


def evaluate(expr: str) -> Fraction:
    """Evaluates an arithmetic expression exactly.
    Raises CalcError on syntax errors or division by zero.
    """
    # 1. Tokenization (Handles character/number errors)
    tokens = tokenize(expr)

    if not tokens and expr == '':
         return Fraction(0)

    # 2. Syntax Checking / Parsing (Builds AST structure)
    parser = Parser(tokens)
    try:
        ast = parser.parse()
    except CalcError as e:
        # Re-raise syntax errors from the parser
        raise e

    # 3. Evaluation (Traverse AST)

    def _evaluate_structure(node) -> Fraction:
        # Base Case: Node is a number string
        if isinstance(node, str):
            return Fraction(node)

        # Base Case: Node is a unary negation result from parse_primary (e.g., (sub_result, '-', token))
        if isinstance(node, tuple) and len(node) == 3 and node[1].value == '-':
             # The structure is (value_or_sub_result, '-', token)
            operand_value = _evaluate_structure(node[0])
            return -operand_value

        # Recursive Case: Node is a binary operation (left, operator_token, right)
        if isinstance(node, tuple) and len(node) == 3 and isinstance(node[1], Token):
            left_value = _evaluate_structure(node[0])
            operator_token = node[1]
            right_value = _evaluate_structure(node[2])

            op = operator_token.value

            if op == '+':
                return left_value + right_value
            elif op == '-':
                return left_value - right_value
            elif op == '*':
                return left_value * right_value
            elif op == '/':
                # Division by zero check
                if right_value == 0:
                    raise CalcError("Division by zero", operator_token.start_index)
                return left_value / right_value

        # Should not happen if parsing is correct
        raise CalcError("Internal parsing error: Unexpected node structure", -1)

    # The result of parser.parse() is the root of the AST structure
    if ast is None:
        # This case should only be reached if the input was empty, handled above.
        return Fraction(0)

    return _evaluate_structure(ast)

