class CronParseError(ValueError):
    """Custom exception for cron parsing errors."""
    pass

def parse_item(item: str, min_val: int, max_val: int, step: int = 1) -> List[int]:
    """Parses a single cron item (N, A-B, A-B/S) into a list of values."""
    if not item: # Should be caught by splitting logic, but safe guard
        raise CronParseError("Empty item in cron field.")

    if '-' in item:
        try:
            start_str, end_str = item.split('-')
            start = int(start_str)
            end = int(end_str)
        except ValueError:
            raise CronParseError(f"Invalid range format: {item}")

        if start > end:
            raise CronParseError(f"Range start ({start}) cannot be greater than end ({end}).")

        if step > 1: # Step applies to ranges as well, though standard range definition is inclusive
            # For A-B/S, the step will be handled by the full parser, here we assume simple A-B
            pass

        return list(range(start, end + 1))

    elif '/' in item:
        try:
            base_item, step_str = item.split('/')
            step = int(step_str)
            if step <= 0:
                raise CronParseError("Step value must be a positive integer.")
        except ValueError:
            raise CronParseError(f"Invalid step format: {item}")

        if base_item == "*":
            values = list(range(min_val, max_val + 1))
        else:
            # Must be A-B/S
            try:
                start_str, end_str = base_item.split('-')
                start = int(start_str)
                end = int(end_str)
            except ValueError:
                raise CronParseError(f"Invalid base range format in step expression: {item}")

            if start > end:
                raise CronParseError(f"Range start ({start}) cannot be greater than end ({end}).")

            # Generate values from A-B and then step through them
            values = list(range(start, end + 1, step))

        # Apply step (if it wasn't applied in the base item logic, this is redundant but safe for * field)
        if base_item == "*":
            return [i for i in range(min_val, max_val + 1) if (i - min_val) % step == 0]
        else:
            return values

    else:
        # Single value N
        try:
            val = int(item)
            if not (0 <= val <= max_val): # Check against the defined range
                 # This check is tricky as max_val changes per field, so we check against the field's conceptual range
                if min_val == 0 and max_val == 59 and val < 0 or val > 59:
                    raise CronParseError(f"Minute value {val} is out of range (0-59).")
                elif min_val == 0 and max_val == 23 and val < 0 or val > 23:
                    raise CronParseError(f"Hour value {val} is out of range (0-23).")
                elif min_val == 1 and max_val == 12 and val < 1 or val > 12:
                    raise CronParseError(f"Month value {val} is out of range (1-12).")
                elif min_val == 0 and max_val == 6 and val < 0 or val > 6:
                     raise CronParseError(f"Day of Week value {val} is out of range (0-6).")
                elif min_val == 1 and max_val == 31 and val < 1 or val > 31:
                    raise CronParseError(f"Day of Month value {val} is out of range (1-31).")

            return [val]
        except ValueError:
            raise CronParseError(f"Invalid integer value: {item}")


def parse_field(field_str: str, min_val: int, max_val: int) -> Set[int]:
    """Parses a full field string (comma-separated items) into a set of valid values."""
    if not field_str.strip():
        # This case should ideally be caught earlier if the input is empty, but defensive coding.
        raise CronParseError("Field string cannot be empty.")

    items = [item.strip() for item in field_str.split(',')] 
    if not any(items) or not all(items):
        # Check for empty items after splitting
        if any(not item for item in items):
             raise CronParseError("Found an empty item within a field definition.")
        if not items: # Should not happen if field_str was not empty
            raise CronParseError("Field definition resulted in no items.")

    expanded_values = set()

    for item in items:
        # Determine step for this item. If it has '/', the step is explicit.
        step = 1
        if '/' in item:
            try:
                step = int(item.split('/')[-1])
                if step <= 0:
                    raise CronParseError("Step must be a positive integer.")
            except ValueError:
                raise CronParseError(f"Invalid step value in item: {item}")

        try:
            if '/' in item:
                # If it has a step, we need a specialized call for step calculation
                if item.startswith('*'):
                    # */S
                    values = [i for i in range(min_val, max_val + 1) if (i - min_val) % step == 0]
                elif '-' in item: # A-B/S
                    base_range_str = item.split('/')[0]
                    start_str, end_str = base_range_str.split('-')
                    start = int(start_str)
                    end = int(end_str)
                    if start > end:
                        raise CronParseError(f"Range start ({start}) cannot be greater than end ({end}).")
                    values = list(range(start, end + 1, step))
                else: # N/S
                    val = int(item.split('/')[0])
                    if not (min_val <= val <= max_val):
                        raise CronParseError(f"Value {val} is out of range for this field.")
                    values = [val] # If N/S, only N matters unless the step is 1, which is covered by N.
            else:
                # Simple item (N or A-B)
                values = parse_item(item, min_val, max_val)
        except CronParseError as e:
            # Re-raise specific parsing errors
            raise e
        except Exception as e:
            # Catch any other unforeseen errors during parsing
            raise CronParseError(f"General error parsing item '{item}': {str(e)}")

        expanded_values.update(values)

    return expanded_values

# --- Field specific wrappers for clarity and range enforcement ---

def parse_minute(expr_part: str) -> Set[int]:
    return parse_field(expr_part, 0, 59)

def parse_hour(expr_part: str) -> Set[int]:
    return parse_field(expr_part, 0, 23)

def parse_day_of_month(expr_part: str) -> Set[int]:
    # Day of month is restricted to 1-31
    return parse_field(expr_part, 1, 31)

def parse_month(expr_part: str) -> Set[int]:
    return parse_field(expr_part, 1, 12)

def parse_day_of_week(expr_part: str) -> Set[int]:
    # Day of week is 0-6 (Sunday=0, Saturday=6)
    return parse_field(expr_part, 0, 6)

# --- Main field parsing function (to be used in next_run) ---

def parse_cron_expression(expr: str) -> List[Set[int]]:
    """Parses the 5-field cron expression into 5 sets of valid values."""
    parts = [p.strip() for p in expr.split() if p.strip()]

    if len(parts) != 5:
        raise CronParseError(f"Expected 5 fields, but found {len(parts)}.")

    minute_set = parse_minute(parts[0])
