                    raise TypeError("Object is not a list or tuple for integer indexing")

                # Indexing handles out-of-range by raising IndexError
                current_obj = current_obj[segment]

            else:
                # Segment type is unexpected
                if default is not None:
                    return default
                else:
                    raise PathError(path, f"Unsupported segment type encountered: {type(segment)}")

        except (TypeError, IndexError) as e:
            # This catches: 
            # 1. Type mismatch (e.g., trying to index a dict with int, or look up dict key on a list)
            # 2. Out-of-range index (IndexError)

            # Special check: If current_obj was a scalar/primitive, it's a type mismatch error.
            if isinstance(e, TypeError):
                 # This covers cases like: name never indexes a list, index never looks up a dict key, scalars are never indexed.
