def to_string(grid: Grid) -> str:
    """Converts the 9x9 grid into a single string representation.

    Args:
        grid: The 9x9 grid.

    Returns:
        An 81-character string representation with '.' for empty cells.

    Raises:
        ValueError: If the grid does not have the required 9x9 shape or contains invalid values.
    """
    # Validate shape
    if not isinstance(grid, list) or len(grid) != 9:
        raise ValueError("Grid must be a list containing 9 rows.")

    for i, row in enumerate(grid):
        if not isinstance(row, list) or len(row) != 9:
            raise ValueError(f"Row {i} must be a list containing 9 elements.")
        for j, cell in enumerate(row):
            if not isinstance(cell, int) or not (0 <= cell <= 9):
                raise ValueError(f"Cell at ({i}, {j}) has an invalid value: {cell}. Must be an integer between 0 and 9.")

    # Convert to string format
    return ''.join(['.' if cell == 0 else str(cell) for row in grid for cell in row])
