Grid = List[List[int]]

def is_valid(grid: Grid) -> bool:
    """Checks if the current state of the grid is valid according to Sudoku rules."""
    if not isinstance(grid, list) or len(grid) != 9:
        return False

    for i in range(9):
        for j in range(9):
            val = grid[i][j]
            if val != 0:
                # Check row
                for k in range(9): 
                    if k != j and grid[i][k] == val:
                        return False
                # Check column
                for k in range(9): 
                    if k != i and grid[k][j] == val:
                        return False
                # Check box
                start_row, start_col = 3 * (i // 3), 3 * (j // 3)
                for r in range(start_row, start_row + 3):
                    for c in range(start_col, start_col + 3):
                        if (r != i or c != j) and grid[r][c] == val:
                            return False
    return True

def get_candidates(grid: Grid, r: int, c: int) -> set[int]:
    """Calculates the set of possible candidates for cell (r, c)."""
    if grid[r][c] != 0:
        return set()

    used_digits = set()

    # Check row and column
    for i in range(9): 
        used_digits.add(grid[r][i])
        used_digits.add(grid[i][c])

    # Check 3x3 box
    start_row, start_col = 3 * (r // 3), 3 * (c // 3)
    for i in range(start_row, start_row + 3):
        for j in range(start_col, start_col + 3):
            used_digits.add(grid[i][j])

    # Candidates are 1-9 excluding used digits (0 is ignored as it's empty)
    return {d for d in range(1, 10) if d not in used_digits}

def hint(grid: Grid) -> Optional[Tuple[int, int, int, str]]:
    """Returns the next logical deduction step (Naked Single or Hidden Single) or None."""
    # 1. Validation (as required, raises ValueError if invalid)
    # We use is_valid, but since this function should only return None if no step is found,
    # we assume the caller handles the initial invalidity check or we check for conflicts
    # that would make the grid unsolvable by logic.
    # For strict adherence, we check validity here.
    if not is_valid(grid):
         # A puzzle that violates rules cannot be solved by logic
        raise ValueError("The grid provided is invalid.")

    # --- 1. Naked Single Check (Row-major order) ---
    for r in range(9):
        for c in range(9):
            if grid[r][c] == 0:
                candidates = get_candidates(grid, r, c)
                if len(candidates) == 1:
                    return (r, c, candidates.pop(), 'naked single')

    # --- 2. Hidden Single Check ---

    # Helper to check for hidden singles in a unit (row, col, or box)
    def find_hidden_single(unit_cells: List[Tuple[int, int]], unit_type: str) -> Optional[Tuple[int, int, int, str]]:
        present_digits = set()
        possible_locations = {d: [] for d in range(1, 10)}

        for r, c in unit_cells:
            candidates = get_candidates(grid, r, c)
            for digit in candidates:
                possible_locations[digit].append((r, c))

        for digit in range(1, 10):
            if digit in present_digits: # Skip digits already present
                continue

            locations = possible_locations[digit]

            # Hidden single: digit appears as a candidate in exactly one cell of the unit
            if len(locations) == 1:
                r, c = locations[0]
                reason = f'hidden single in {unit_type}'
                return (r, c, digit, reason)

        return None

    # 2a. Hidden Singles in Rows (Unit Type: Row)
    for r in range(9):
        row_cells = [(r, c) for c in range(9)]
        hint_result = find_hidden_single(row_cells, 'row')
        if hint_result:
            return hint_result

    # 2b. Hidden Singles in Columns (Unit Type: Column)
    for c in range(9):
        col_cells = [(r, c) for r in range(9)]
        hint_result = find_hidden_single(col_cells, 'column')
        if hint_result:
            return hint_result

    # 2c. Hidden Singles in Boxes (Unit Type: Box)
    for b in range(9):
        start_row, start_col = 3 * (b // 3), 3 * (b % 3)
        box_cells = []
        for r in range(start_row, start_row + 3):
            for c in range(start_col, start_col + 3):
                box_cells.append((r, c))

        hint_result = find_hidden_single(box_cells, 'box')
        if hint_result:
            return hint_result

    # No steps found
    return None

def difficulty(grid: Grid) -> Optional[Dict[str, int]]:
    """Calculates the difficulty rating by applying hints until the grid is solved."""
    # Work on a copy of the grid
    temp_grid = [row[:] for row in grid]
    naked_count = 0
    hidden_count = 0

    while True:
        hint_step = hint(temp_grid)

        if hint_step is None:
            # Stop condition: no more logical steps found
            # Check if the grid is complete
            is_complete = all(temp_grid[r][c] != 0 for r in range(9) for c in range(9))
            if is_complete:
                return {'naked': naked_count, 'hidden': hidden_count}
            else:
                # Puzzle is stuck (needs guessing or has no solution)
                return None
        else:
            r, c, digit, reason = hint_step

            # Write the digit into the cell
            temp_grid[r][c] = digit

