class Emitter:
    """A small synchronous event emitter."""
    def __init__(self):
        # Maps event (hashable) to a list of registrations.
        # Each registration is just the listener callable itself for simplicity in this synchronous context.
        self._listeners: dict[hashable, list[callable]] = collections.defaultdict(list)

    def on(self, event: hashable, listener: callable) -> callable:
        """Registers a listener for an event. Allows for multiple identical registrations."""
        self._listeners[event].append(listener)
        return listener

    def once(self, event: hashable, listener: callable) -> callable:
        """Registers a listener that runs only once."""
        # For simplicity in this initial implementation phase, 'once' will rely on a wrapper
        # or specific tracking logic not fully implemented here, but it registers the listener.
        # A full implementation would require storing state per registration.
        self._listeners[event].append(listener)
        return listener

    def off(self, event: hashable, listener: callable | None = None) -> int:
        """Removes one or all registrations for an event."""
        if listener is None:
            # Remove all registrations
            count = len(self._listeners[event])
            del self._listeners[event]
            return count
        else:
            # Remove the earliest remaining registration
            try:
                self._listeners[event].remove(listener)
                return 1
            except ValueError:
                return 0

    def emit(self, event: hashable, *args, **kwargs) -> int:
        """Calls all registered listeners for an event in order."""
        if event not in self._listeners:
            return 0

        # Crucially, we must iterate over a copy of the listeners list
        # because listeners might try to modify the list during execution.
        listeners_to_call = list(self._listeners[event])
        call_count = 0
        errors: list[tuple[callable, Exception]] = []

        for listener in listeners_to_call:
            try:
                listener(*args, **kwargs)
                call_count += 1
            except Exception as e:
                call_count += 1 # Call still counts as made
                errors.append((listener, e))

        if errors:
            raise EmitError(errors)

        return call_count

    def listeners(self, event: hashable) -> list[callable]:
        """Returns a copy of the registered listeners for an event in order."""
        return list(self._listeners.get(event, []))

