    def _resolve_value(self, path: str, context: Dict[str, Any], kwargs: Dict[str, Any]) -> Any:
        """Resolves a variable path against the context/kwargs."""
        # Merge context and kwargs (kwargs win)
        effective_context = {**context, **kwargs}
        parts = path.split('.')
        current_value: Any = effective_context

        for i, part in enumerate(parts):
            if current_value is None: 
                return None # On None, result is None

            # 1. Integer segment (List/Tuple access)
            if part.isdigit() and isinstance(current_value, (list, tuple)): 
                try: 
                    idx = int(part)
                    current_value = current_value[idx]
                except IndexError: 
                    return None # Out of range
                continue

            # 2. Mapping segment (string key lookup)
            if isinstance(current_value, collections.abc.Mapping):
                # Segment is used as a string key
                key = part
                current_value = current_value.get(key)
                continue

            # 3. Attribute segment (for objects)
            if not part.startswith('_') and hasattr(current_value, part):
                current_value = getattr(current_value, part)
                continue

            # Anything else fails resolution
            return None

        return current_value

    def _apply_filter(self, value: Any, filter_name: str, args_list: Optional[List[str]]) -> Any:
        """Applies a single filter to a value."""
        if value is None: 
            # Handle None early for filters where specific behavior is defined
            if filter_name == 'length': return 0
            if filter_name == 'items': return []
            # Most filters that require input on None will fail or return None/empty
            if filter_name == 'default':
                # This case should ideally be handled by the filter call site, not here
                return None 
            return None

        try:
            if filter_name == 'upper':
                return str(value).upper()
            if filter_name == 'lower':
                return str(value).lower()
            if filter_name == 'trim':
                return str(value).strip()
            if filter_name == 'length':
                return len(value) if isinstance(value, (str, list, tuple)) else 0
            if filter_name == 'first':
                return value[0] if isinstance(value, (str, list, tuple)) and value else None
            if filter_name == 'last':
                return value[-1] if isinstance(value, (str, list, tuple)) and value else None
            if filter_name == 'reverse':
                if isinstance(value, str): return value[::-1]
                if isinstance(value, (list, tuple)): return value[::-1]
                return None # As per spec
            if filter_name == 'join':
                if not args_list or not args_list[0]:
                    raise TemplateRenderError("join filter requires a separator argument.", -1)
                sep = args_list[0]
                return "".join(str(item) for item in value) if isinstance(value, (list, tuple)) else ""
            if filter_name == 'default':
                if not args_list or not args_list[0]:
                    raise TemplateRenderError("default filter requires a literal argument.", -1)
                literal = args_list[0]
                return literal if value is None or str(value) == "" else value
            if filter_name == 'truncate':
                if not args_list or not args_list[0] or not args_list[0].isdigit() or int(args_list[0]) < 0:
                    raise TemplateRenderError("truncate filter requires a non-negative integer argument.", -1)
                n = int(args_list[0])
                text = str(value)
                return text[:n] + "..." if len(text) > n else text
            if filter_name == 'items':
                if not isinstance(value, collections.abc.Mapping): 
                    raise TemplateRenderError("items filter requires a mapping type.", -1)
                return list(value.items())
            else:
                raise TemplateRenderError(f"Unknown filter: {filter_name}", -1)
        except TypeError as e:
            raise TemplateRenderError(f"Filter application error for {filter_name}: {e}", -1)
        except IndexError:
            raise TemplateRenderError(f"Filter failed due to index error during {filter_name} application.", -1)

    def _evaluate_expression(self, node: 'ExpressionNode', context: Dict[str, Any], kwargs: Dict[str, Any]) -> Any:
        """Evaluates a value expression, resolving atoms and applying filters."""
        if not node.parts: 
            raise TemplateRenderError("Expression has no parts.", node.lineno)

        # For simplicity in this complex task, we assume the ExpressionNode structure
        # means it resolves to one base atom followed by zero or more filters.
        # If it was complex (e.g., 'a + b'), this would need a full expression parser.

        part = node.parts[0]

        # 1. Resolve the base atom
        base_value = None
        if isinstance(part.atom, AtomNode):
            if part.atom.literal.startswith(('"', "'")): # String literal
                base_value = part.atom.literal.strip("'"[ "\']")
            else: # Variable path or integer literal
                if part.atom.literal.isdigit() or (part.atom.literal.startswith('-') and part.atom.literal[1:].isdigit()):
                     try: base_value = int(part.atom.literal) 
                    except ValueError: pass # Should not happen
                else:
                    base_value = self._resolve_value(part.atom.literal, context, kwargs)

        if base_value is None and not isinstance(part.atom, AtomNode): # Safety check if AtomNode was supposed to handle paths
             base_value = self._resolve_value(part.atom.literal, context, kwargs)

        # 2. Apply filters sequentially
        current_value = base_value
        for filter_name, args in part.filters:
            current_value = self._apply_filter(current_value, filter_name, args)

        return current_value

    def _evaluate_condition(self, node: 'ComparisonNode', context: Dict[str, Any], kwargs: Dict[str, Any]) -> bool:
        """Evaluates a comparison node, respecting precedence and short-circuiting."""
        # This is a massive simplification of expression parsing for conditions.
        # A real implementation would tokenize and parse the entire condition string.
        # Here we only handle the explicit ComparisonNode structure.

        left_val = self._evaluate_expression(node.left, context, kwargs)
        right_val = self._evaluate_expression(node.right, context, kwargs)

        op = node.op

        if op == "==":
            return left_val == right_val
        if op == "!=":
            return left_val != right_val
        if op == "<":
            return left_val < right_val
        if op == "<":
            return left_val <= right_val
        if op == ">":
            return left_val > right_val
        if op == ">=":
            return left_val >= right_val

        # Logical operators (assuming they are handled at a higher level, 
        # but if they appear here, we simplify)
        if op == "and":
            return bool(left_val) and bool(right_val)
        if op == "or":
            return bool(left_val) or bool(right_val)
        if op == "not":
            return not bool(left_val)

        raise TemplateRenderError(f"Unknown comparison operator: {op}", node.lineno)

    def _render_node(self, node: 'ASTNode', context: Dict[str, Any], kwargs: Dict[str, Any], loop_context: Optional[Dict[str, Any]] = None) -> str:
        """The main recursive traversal function."""
        output = []

        if isinstance(node, TextNode):
            return node.value

        elif isinstance(node, VariableNode):
            value = self._evaluate_expression(node.expression, context, kwargs)
            if value is None: 
                return ""
            return str(value)

        elif isinstance(node, AtomNode):
            # Atoms are resolved via expression evaluation if they are used as a base
            # If an AtomNode appears directly as a top-level element, it acts like text or a variable if it contains a path.
            # Assuming AtomNode here means a literal text part if not wrapped in a VariableNode.
            return node.literal

        elif isinstance(node, FilterNode):
            base_value = self._evaluate_expression(node.base_expression, context, kwargs)
            result = self._apply_filter(base_value, node.filter_name, node.args)
            if result is None and node.filter_name not in ['default', 'join', 'items']: 
                 return ""
            return str(result)

        elif isinstance(node, ComparisonNode):
            # Conditions should only appear inside IfNode bodies
            is_true = self._evaluate_condition(node, context, kwargs)
            return "" if not is_true else "True" # Returning 'True' is a placeholder for conditional rendering logic elsewhere

        elif isinstance(node, ForNode):
            # Loop context setup
            iterable_value = self._evaluate_expression(node.target, context, kwargs)
            if iterable_value is None:
                return ""

            # Loop over keys if it's a mapping (as per spec)
            if isinstance(iterable_value, collections.abc.Mapping):
                items = iterable_value.keys()
            elif isinstance(iterable_value, (list, tuple)): # Treat list/tuple as directly iterable
                items = iterable_value
            else: 
                # Looping over a non-iterable
                raise TemplateRenderError("Attempted to loop over a non-iterable value.", node.lineno)

            output_parts = []
            has_rendered = False

            for index, item in enumerate(items):
                loop_ctx = {
                    'index': index + 1, 
                    'index0': index, 
                    'first': index == 0, 
                    'last': index == len(items) - 1, 
                    'length': len(items)
                }
                # Merge existing loop context if nested
                current_loop_context = loop_context if loop_context is None else {**loop_context, **loop_context}

                # Override outer names in body scope
                body_context = {**context, **kwargs, 'loop': loop_ctx, 'NAME': item}

                # Render body
                rendered_body = self._render_nodes_list(node.body, body_context, kwargs, loop_ctx)
                output_parts.append(rendered_body)
                has_rendered = True

            # Render else block if nothing rendered
            if not has_rendered and node.else_body:
                else_body_context = {**context, **kwargs, 'loop': loop_context}
                output_parts.append(self._render_nodes_list(node.else_body, else_body_context, kwargs, loop_ctx))

            return "".join(output_parts)

        elif isinstance(node, IfNode):
            # Conditional rendering
            current_context = context
            current_kwargs = kwargs

            # 1. Test initial condition
            if self._evaluate_condition(node.condition, current_context, current_kwargs):
                return self._render_nodes_list(node.true_body, current_context, current_kwargs, loop_context)

            # 2. Test elif blocks
            for elif_cond, elif_body in node.elif_blocks:
                if self._evaluate_condition(elif_cond, current_context, current_kwargs):
                    return self._render_nodes_list(elif_body, current_context, current_kwargs, loop_context)

            # 3. Test else block
            if node.else_body:
                return self._render_nodes_list(node.else_body, current_context, current_kwargs, loop_context)

            return ""

        raise TypeError(f"Unknown AST Node Type: {type(node)}")

    def _render_nodes_list(self, nodes: List['ASTNode'], context: Dict[str, Any], kwargs: Dict[str, Any], loop_context: Optional[Dict[str, Any]]) -> str:
        """Renders a sequence of nodes, concatenating results."""
        parts = []
        for node in nodes:
            try:
                parts.append(self._render_node(node, context, kwargs, loop_context))
            except TemplateRenderError as e: 
                # Propagate render errors with the original node's lineno if available, else use error's lineno
                lineno = getattr(node, 'lineno', e.lineno)
                raise TemplateRenderError(f"Error during rendering block at line {lineno}: {e.message}", lineno)
        return "".join(parts)

    def render(self, context: Optional[Dict[str, Any]] = None, **kwargs) -> str:
        """Renders the entire template against the provided context and keyword arguments."""
        context = context if context is not None else {}

        # Initial context merge: kwargs win over context
        final_context = {**context, **kwargs}

        # Render top-level AST nodes
        return self._render_nodes_list(self.ast, final_context, kwargs)

