from typing import List, Union, Optional, Dict, Any, Tuple
from dataclasses import dataclass
from .lexer import Token, TemplateSyntaxError, tokenize

# --- AST Node Definitions ---

# Base structure for any node in the AST
ASTNode = Union[
    'TextNode', 
    'VariableNode', 
    'ForNode', 
    'IfNode', 
    'AtomNode', 
    'FilterNode', 
    'ComparisonNode', 
    'BooleanOpNode', 
    'ExtendsNode', 
    'BlockNode'
]

@dataclass
class TextNode: 
    value: str

@dataclass
class AtomNode: 
    # Represents a raw path or literal
    value: str 

@dataclass
class FilterNode: 
    # Represents value | filter or value | filter:arg
    source: ASTNode
    filter_name: str
    args: List[str]

@dataclass
class VariableNode: 
    # Represents {{ expression }}. Holds the root of the expression AST.
    expression: ASTNode

@dataclass
class ComparisonNode: 
    # Represents LHS cmp RHS (e.g., a == b)
    left: ASTNode
    operator: str 
    right: ASTNode

@dataclass
class BooleanOpNode: 
    # Represents logical operations (AND, OR, NOT)
    op: str  # 'and', 'or', 'not'
    operands: List[ASTNode]

@dataclass
class ForNode: 
    # {% for NAME in EXPR %}body{% endfor %}
    loop_name: str 
    expression: ASTNode
    body: List[ASTNode]
    else_body: Optional[List[ASTNode]]

@dataclass
class IfNode: 
    # {% if COND %}...{% elif COND %}...{% else %}...{% endif %}
    condition: ASTNode
    body: List[ASTNode]
    elif_clauses: List[Tuple[ASTNode, List[ASTNode]]]
    else_body: Optional[List[ASTNode]]

@dataclass
class ExtendsNode: 
    # {% extends "name" %}
    template_name: str

@dataclass
class BlockNode: 
    # {% block NAME %}...{% endblock %}
    block_name: str
    body: List[ASTNode]

# --- Parser Implementation ---

class Parser:
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def current_token(self) -> Token: 
        if self.pos >= len(self.tokens): 
            # Sentinel token for EOF
            return Token("EOF", "", 0)
        return self.tokens[self.pos]

    def consume(self, expected_kind: Optional[str] = None, expected_value: Optional[str] = None) -> Token:
        token = self.current_token()
        if expected_kind and token.kind != expected_kind:
            raise TemplateSyntaxError(f"Expected token of kind '{expected_kind}', but found '{token.kind}'", token.lineno)
        if expected_value and token.value != expected_value:
            raise TemplateSyntaxError(f"Expected token value '{expected_value}', but found '{token.value}'", token.lineno)
        self.pos += 1
        return token

    def parse(self) -> List[ASTNode]:
        nodes: List[ASTNode] = []
        while self.current_token().kind != "EOF":
            node = self.parse_statement()
            if node:
                nodes.append(node)

        return nodes

    def parse_statement(self) -> Optional[ASTNode]:
        token = self.current_token()

        if token.kind == "text":
            self.consume("text")
            return TextNode(token.value)

        if token.kind == "extends":
            # {% extends "name" %}. Must be the first tag.
            self.consume("extends")
            # The value contains the quoted name
            name = token.value.strip().strip('"')
            return ExtendsNode(template_name=name)

        if token.kind == "var":
            # {{ expression }}
            self.consume("var")
            expression_ast = self._parse_variable_expression(token.value, token.lineno)
            return VariableNode(expression_ast)

        if token.kind == "block":
            # {% statement %}
            self.consume("block")
            # The block value contains the statement content, possibly with whitespace stripped.
            return self._parse_control_block(token.value, token.lineno)

        # Should not happen if lexer is correct, but safety catch
        self.pos += 1 
        return None

    # --- Expression Parsing (for {{ }}) ---

    def _parse_variable_expression(self, expression_str: str, lineno: int) -> ASTNode:
        # (Implementation remains the same as before, handling atom/filter chain)
        parts = expression_str.strip().split('|')
        if not parts or not parts[0].strip():
             raise TemplateSyntaxError("Empty value expression", lineno)

        base_value_str = parts[0].strip()
        try:
            base_atom = AtomNode(base_value_str)
        except Exception:
            raise TemplateSyntaxError(f"Invalid atom format: {base_value_str}", lineno)

        filters: List[Tuple[str, List[str]]] = []
        for part in parts[1:]:
            filter_part = part.strip()
            if not filter_part: continue

            if ':' in filter_part:
                name, arg_str = filter_part.split(':', 1)
                filters.append((name.strip(), [arg_str.strip()]))
            else:
                filters.append((filter_part, []))

        current_node = base_atom
        for name, args in filters:
            current_node = FilterNode(current_node, name, args)

        return current_node

    # --- Control Block Parsing (for {% %}) ---

    def _parse_control_block(self, block_content: str, lineno: int) -> Optional[ASTNode]:
        content = block_content.strip()

        # --- 1. Handle Inheritance --- 
        if content.startswith("extends "): # {% extends "name" %}
            try:
                # Expecting format: extends "name" (or extends 'name')
                parts = content.split(" ", 1)
                if parts[0] != "extends": raise ValueError("Not an extends tag")

                name_part = parts[1].strip()
                # Extract name from quotes
                if name_part.startswith('"') and name_part.endswith('"'):
                    name = name_part.strip('"')
                elif name_part.startswith("'') and name_part.endswith("'"): # Added support for single quotes
                    name = name_part.strip("'")
                else:
                    raise ValueError("Invalid quoting for extends name")

                return ExtendsNode(template_name=name)
            except ValueError as e:
                raise TemplateSyntaxError(f"Invalid extends tag format: {e}", lineno)

        # --- 2. Handle Blocks --- 
        elif content.startswith("block "): # {% block NAME %}
            try:
                # Block name follows variable name rule
                block_name = content.split(" ", 1)[1].strip()
                if not block_name: raise ValueError("Block name missing")

                # Start parsing the content recursively until {% endblock NAME %}
                body_nodes = self._parse_block_body(block_name, lineno)
                return BlockNode(block_name=block_name, body=body_nodes)
            except Exception as e:
                raise TemplateSyntaxError(f"Error parsing block tag: {e}", lineno)

        # --- 3. Handle Other Tags (For, If, Else, End) --- 
        elif content.startswith("for "): # {% for NAME in EXPR %}
            try:
                parts = content.split(" in ", 1) 
                if len(parts) != 2:
                    raise ValueError("Malformed for statement")

                header_part, expr_part = parts
                name = header_part.replace("for ", "").strip()
                expr_ast = self._parse_variable_expression(expr_part.strip(), lineno)

                # Note: Body is empty here; it will be parsed by the surrounding block/statement context if any.
                # Since we are parsing a standalone control block, we return a structure that needs body parsing.
                # For simplicity here, we assume the body follows immediately and is handled by the caller if it's not nested in a block.
                # However, since this function is called directly from parse_statement, we treat this as a self-contained control flow statement.
                # In this context, we cannot reliably parse the body without context, so we rely on the caller handling the structure.

                # To handle the body, we must assume the caller expects us to parse the subsequent statements until 'endfor'.
                # This implies a fundamental change in how parse_statement interacts with control flow vs block parsing.
                # Given the scope, we return a basic structure, and the caller must consume tokens until 'endfor'.
                return ForNode(loop_name=name, expression=expr_ast, body=[], else_body=None)
            except Exception as e:
                raise TemplateSyntaxError(f"Error parsing for statement: {e}", lineno)

        elif content.startswith("if "): # {% if COND %}
            try:
                condition_str = content.replace("if ", "").strip()
                cond_ast = self._parse_variable_expression(condition_str, lineno)
                return IfNode(condition=cond_ast, body=[], elif_clauses=[], else_body=None)
            except Exception as e:
                raise TemplateSyntaxError(f"Error parsing if condition: {e}", lineno)

        elif content == "else":
            # This token needs to be consumed by the IF parser, not returned as a standalone node.
            return None

        elif content == "endif":
            return None # Signal end of block/if
        elif content == "endfor":
            return None # Signal end of block/for
        elif content == "endblock":
             # This token needs to be consumed by the BLOCK parser, not returned as a standalone node.
            return None

        raise TemplateSyntaxError(f"Unknown statement or malformed control block tag: '{content}'", lineno)

    # --- New Recursive Block Parsing Helpers ---

    def _parse_block_body(self, block_name: str, start_lineno: int) -> List[ASTNode]:
        """Recursively parses statements until {% endblock NAME %} is encountered."""
        body: List[ASTNode] = []
        block_start_pos = self.pos

        while self.current_token().kind != "EOF":
            token = self.current_token()

            if token.kind == "block" and token.value.strip() == "endblock":
                # Check for matching name: {% endblock NAME %}
                # We need the next token to be 'endblock' (which we just consumed implicitly by checking token.value.strip() == "endblock")
                # The lexer output for 'endblock NAME' will be a single token if it's token.value = "endblock NAME".
                # Assuming the lexer emits 'endblock' as the token value for {% endblock NAME %}
                # If the lexer emits 'endblock' for the tag keyword, we must check the next token or rely on structure.

                # Based on existing structure where block content is one string, we assume {% endblock NAME %} results in a block token with value 'endblock NAME'.
                # Let's adapt: we look for the specific token value.
                if token.value.strip() == f"endblock {block_name}":
                    self.consume("block") # Consume {% endblock NAME %}
                    return body
                elif token.value.strip() == "endblock":
                    # This means the lexer is too simplistic; we assume the required name is present.
                    raise TemplateSyntaxError(f"Mismatched or missing block name in endblock tag. Expected 'endblock {block_name}'.", token.lineno)
                else:
                    # It was an 'endblock' keyword but not the correct one
                    raise TemplateSyntaxError(f"Mismatched block end tag. Expected 'endblock {block_name}', found '{token.value}'.", token.lineno)

            # Check for nested blocks or control structures
            if token.kind == "block":
                # We recursively call _parse_control_block, which will handle nested blocks
                self.consume("block")
                nested_node = self._parse_control_block(token.value, token.lineno)
                if nested_node and isinstance(nested_node, BlockNode):
                    body.append(nested_node)
                elif nested_node: # If it was for/if/extends, append it
                    body.append(nested_node)
                # If it was a standalone control tag (e.g., {% for ... %}), it gets appended as is.
            elif token.kind == "var":
                # Variables inside blocks are standard statements
                self.consume("var")
                expression_ast = self._parse_variable_expression(token.value, token.lineno)
                body.append(VariableNode(expression_ast))
            elif token.kind == "text":
                self.consume("text")
                body.append(TextNode(token.value))
            else:
                # For other control structures (For, If), we parse them fully and append them.
                self.consume("block") # Consume the start token if it was for/if
                control_node = self._parse_control_block(token.value, token.lineno)
                if control_node:
                    body.append(control_node)
                else:
                    # This handles 'else' tokens which we consume but don't append as statements
                    pass

        # If loop finishes without hitting endblock
        raise TemplateSyntaxError(f"Unclosed block: '{block_name}'", start_lineno)

    # --- Public API Function --- 

def parse(source: str) -> List[ASTNode]:
    """Parses the template source string into a list of top-level AST nodes."""
    if not isinstance(source, str):
        raise TypeError("Source must be a string")

    tokens = tokenize(source)
    parser = Parser(tokens)
    return parser.parse()

