# --- HTML Escaping Utility ---
def _html_escape(text: str) -> str:
    """Applies HTML escaping as specified: &, <, >, ", '."""
    text = text.replace('&', '&amp;')
    text = text.replace('<', '&lt;')
    text = text.replace('>', '&gt;')
    text = text.replace('"', '&quot;')
    text = text.replace("'", '&#x27;')
    return text

# --- New Class Implementation: DictLoader ---
class DictLoader:
    """A loader that maps template names to their source text from a dictionary."""
    def __init__(self, templates: dict[str, str]):
        self.templates = templates

    def get_source(self, name: str) -> str:
        """Returns the source text for the given template name, or raises TemplateNotFound."""
        if name not in self.templates:
            raise TemplateNotFound(name)
        return self.templates[name]

# --- Environment Class Implementation ---
class Environment:
    """Manages the loading and configuration of templates."""
    def __init__(self, loader: Optional[Any] = None, autoescape: bool = False):
        self.loader = loader
        self.autoescape = autoescape

    def get_template(self, name: str) -> "tmpl.Template"[:]
        """Loads a template by name from the loader and returns a Template instance."""
        if self.loader is None:
            raise TemplateNotFound(name) # No loader provided

        try:
            source = self.loader.get_source(name)
        except TemplateNotFound as e:
            # Re-raise the specific not found error from the loader
            raise e
        except Exception as e:
            # Catch potential loader errors not covered by TemplateNotFound
            raise TemplateNotFound(name) # Generic fallback for loader failures

        # Template constructor now accepts loader, autoescape, and name
        return Template(source, loader=self.loader, autoescape=self.autoescape, name=name)

    def from_string(self, source: str) -> "tmpl.Template"[:]
        """Creates a Template instance directly from a source string."""
        # Name is left as None as per specification
        return Template(source, loader=None, autoescape=self.autoescape, name=None)

