import collections

class Headers:
    """an ordered, case-insensitive multi-map of header fields, built from (name, value) pairs.
    Names keep the case they were given; look-ups ignore case.
    """
    def __init__(self, pairs=()):
        # Stores (name, value) pairs in insertion order
        self._pairs = list(pairs)
        # Mapping from lowercased name to a list of indices where it appears
        self._name_to_indices = collections.defaultdict(list)
        self._build_lookup()

    def _build_lookup(self):
        """Rebuilds the name-to-indices map based on current _pairs."""
        self._name_to_indices.clear()
        for i, (name, _) in enumerate(self._pairs):
            self._name_to_indices[name.lower()].append(i)

    def add(self, name: str, value: str):
        """Appends a field."""
        self._pairs.append((name, value))
        self._name_to_indices[name.lower()].append(len(self._pairs) - 1)

    def set(self, name: str, value: str):
        """Replaces every field with that name by a single one (at the position of the first, or at the end if there was none)."""
        name_lower = name.lower()
        indices = self._name_to_indices[name_lower]

        if indices:
            # Replace all matching entries while preserving order of the first occurrence
            first_index = indices[0]
            # Update the first entry
            self._pairs[first_index] = (name, value)
            # Update all subsequent entries to match the first's name and value
            # This ensures they all refer to the same 'set' value and name for consistency
            for i in indices[1:]:
                self._pairs[i] = (name, value)
        else:
            # If no field exists, append it
            self.add(name, value)

