                    size_str_match = re.match(r'([0-9a-fA-F]+)(?:;.*)?\r\n', size_line)
                    if not size_str_match:
                        raise ValueError("Invalid chunk size line format.")

                    size_hex = size_str_match.group(1)
                    chunk_size = int(size_hex, 16)

                    current_pos = end_size_line + 2 # Move past '\r\n'

                    if chunk_size == 0:
                        # End of data. Now skip optional trailer lines and the final empty line
                        trailer_start = current_pos
                        trailer_end = chunk_data_bytes.find(b'\r\n\r\n', trailer_start)
                        if trailer_end == -1:
                            raise ValueError("Missing trailing CRLFCRLF after zero chunk.")
                        current_pos = trailer_end + 4
                        break

                    # Read chunk data
                    chunk_start = current_pos
                    chunk_end = chunk_start + chunk_size
                    if chunk_end > len(chunk_data_bytes):
                        raise ValueError("Incomplete chunk body data.")

                    chunk = chunk_data_bytes[chunk_start:chunk_end]
                    chunks.append(chunk)
                    current_pos = chunk_end + 2 # Move past chunk body's '\r\n'
                    # Skip optional trailer lines until final empty line
                    if chunk_size > 0: # Only check for trailer if it wasn't the zero chunk
                        trailer_end = chunk_data_bytes.find(b'\r\n\r\n', current_pos)
                        if trailer_end == -1:
                            raise ValueError("Incomplete trailer/final CRLFCRLF.")
                        current_pos = trailer_end + 4

                body_bytes = b''.join(chunks)

            except (ValueError, IndexError) as e:
                raise BadRequest(f"Chunked body decoding failed: {e}")

        elif content_length_str:
            # Content-Length Decoding
            try:
                length = int(content_length_str)
                if len(body_data_bytes) != length:
                    raise BadRequest(f"Body size mismatch. Expected {length}, got {len(body_data_bytes)}.")
                body_bytes = body_data_bytes
            except ValueError:
                raise BadRequest("Content-Length must be decimal digits only.")
        else:
            # Neither header present, body is empty
            body_bytes = b''

        # Check for leftover bytes
        if transfer_encoding == 'chunked':
            # If we exited the chunk loop, we processed up to current_pos. If current_pos < len(chunk_data_bytes), there's leftover data.
            # However, the logic above handles the zero chunk correctly, so we check if we consumed everything up to the final CRLFCRLF.
            # A simpler check: if the total data length matches what we expected or if we reached the end after zero chunk.
            if chunk_data_bytes.find(b'\r\n\r\n', current_pos) != -1:
                raise BadRequest("Extra data found after chunked body.")
        elif content_length_str and len(body_data_bytes) != int(content_length_str):
             # This case is handled above, but keeping robust checks.
             pass
        elif not content_length_str and transfer_encoding != 'chunked':
            # If neither specified, body must be empty, and body_data_bytes must be empty.
            if body_data_bytes:
                raise BadRequest("Unexpected data present when no body headers are provided.")


        return Request(
            method=method,
            target=target,
            path=target.split('?')[0],
            query_string=target.split('?', 1)[-1] if '?' in target else '',
            version=version,
            headers=headers,
            body=body_bytes,
            params={},
            state={}
        )

    except HTTPError as e:
        # Re-raise known errors
        raise e
    except Exception as e:
        # Catch all parsing errors and convert to BadRequest if not already an HTTPError
        if not isinstance(e, BadRequest):
             raise BadRequest(f"Fatal parsing error: {type(e).__name__}: {str(e)}")
        else:
