}

def get_reason_phrase(status: int) -> str:
    return REASON_PHRASES.get(status, "Unknown")

class HTTPError(Exception):
    """Base class for HTTP errors.
    Attributes: status (int), reason (str)."""
    def __init__(self, status: int, reason: str = None):
        self.status = status
        self.reason = reason or get_reason_phrase(status)
        super().__init__(f"{self.status} {self.reason}")

class BadRequest(HTTPError):
    """Represents a 400 Bad Request error.
    Inherits from HTTPError.
