# --- Error Handling ---

# Helper for reason phrases, derived from requirements
REASON_PHRASES = {
    200: "OK",
    201: "Created",
    204: "No Content",
    400: "Bad Request",
    401: "Unauthorized",
    404: "Not Found",
    405: "Method Not Allowed",
    500: "Internal Server Error",
}

def get_reason_phrase(status: int) -> str:
    return REASON_PHRASES.get(status, "Unknown")

class HTTPError(Exception):
    """Base class for HTTP errors.
    Attributes: status (int), reason (str)."""
    def __init__(self, status: int, reason: str = None):
        self.status = status
        self.reason = reason or get_reason_phrase(status)
        super().__init__(f"{self.status} {self.reason}")

class BadRequest(HTTPError):
    """Represents a 400 Bad Request error.
    Inherits from HTTPError.
    """
    def __init__(self, message: str = None):
        super().__init__(400, "Bad Request")
        self.message = message

    def __str__(self):
        if self.message:
            return f"400 Bad Request: {self.message}"
        return super().__str__()

# --- Headers Class ---

class Headers:
    def __init__(self, pairs: Tuple[Tuple[str, str], ...] = ()):
        # Stores (name, value) pairs in order. Name keeps original case.
        self._pairs: List[Tuple[str, str]] = list(pairs)

    def add(self, name: str, value: str):
        # Appends a field
        self._pairs.append((name, value))

    def set(self, name: str, value: str):
        # Replaces every field with that name by a single one (at the position of the first, or at the end if there was none).
        found = False
        for i, (n, v) in enumerate(self._pairs):
            if n.lower() == name.lower():
                self._pairs[i] = (name, value) # Keep original case for the stored name if possible, though the rule is ambiguous, we prioritize replacement at first instance.
                found = True
                break
        if not found:
            self._pairs.append((name, value))

    def get(self, name: str, default: Any = None) -> str:
        # Returns the first value
        for n, v in self._pairs:
            if n.lower() == name.lower():
                return v
        return default

    def __getitem__(self, name: str) -> str:
        # Raises KeyError if not found
        for n, v in self._pairs:
            if n.lower() == name.lower():
                return v
        raise KeyError(name)

    def get_all(self, name: str) -> List[str]:
        # Returns every value in order
        return [v for n, v in self._pairs if n.lower() == name.lower()]

    def __contains__(self, name: str) -> bool:
        # Name in h
        return any(n.lower() == name.lower() for n, v in self._pairs)

    def __len__(self) -> int:
        # Number of fields
        return len(self._pairs)

    def items(self) -> List[Tuple[str, str]]:
        # List of (name, value) pairs in order
        return self._pairs

# --- Request Dataclass ---

@dataclass
class Request:
    method: str
    target: str
    path: str
    query_string: str
    version: str
    headers: Headers
    body: bytes
    params: Dict[str, Any] = field(default_factory=dict)
    state: Dict[str, Any] = field(default_factory=dict)

    @property
    def query(self) -> Dict[str, List[str]]:
        """Decodes the query string into a dictionary.
        + means space, %XX is percent-escape. Decodes as UTF-8.
        """
        if not self.query_string:
            return {}

        query_params: Dict[str, List[str]] = {}
        parts = self.query_string.split('&')

        def decode_value(s: str) -> str:
            # Replaces '+' with ' ' and decodes %XX
            return s.replace('+', ' ').encode('utf-8', 'replace').decode('utf-8', 'replace')

        for part in parts:
            if not part:
                continue

            if '=' in part:
                name, value = part.split('=', 1)
            else:
                name, value = part, ''

            # Decode name and value
            try:
                decoded_name = decode_value(name)
                decoded_value = decode_value(value)
            except Exception as e:
                raise BadRequest(f"Query decoding failed: {e}")

            if decoded_name not in query_params:
                query_params[decoded_name] = []
            query_params[decoded_name].append(decoded_value)

        return query_params

    @property
    def content_type(self) -> Tuple[str, Dict[str, str]]:
        """Parses Content-Type header.
        """
        ct_header_value = self.headers.get('Content-Type') or self.headers.get('content-type')

        if not ct_header_value:
            return ('', {}) # Default case

        parts = [p.strip() for p in ct_header_value.split(';')]

        # 1. Media type
        media_type = parts[0].lower()

        # 2. Parameters
        params: Dict[str, str] = {}
        for part in parts[1:]:
            if '=' in part:
                name, value = [s.strip() for s in part.split('=', 1)]
                name = name.lower()
                # Strip surrounding quotes
                if value.startswith('"') and value.endswith('"'):
                    value = value[1:-1]

                # First occurrence wins
                if name not in params:
                    params[name] = value

        return (media_type, params)

    def text(self, charset: str = 'utf-8') -> str:
        """Decodes the body as text.
        """
        try:
            return self.body.decode(charset)
        except UnicodeDecodeError as e:
            raise BadRequest(f"Body decoding failed with {charset}: {e}")

    def json(self) -> Any:
        """Parses text() as JSON.
        """
        try:
            return json.loads(self.text())
        except json.JSONDecodeError as e:
            raise BadRequest(f"Invalid JSON in body: {e}")

# --- Response Dataclass ---

@dataclass
class Response:
    status: int = 200
    headers: Headers = field(default_factory=Headers)
    body: bytes = b''

    @classmethod
    def text(cls, s: str, status: int = 200):
        instance = cls(status=status)
        instance.headers.add('Content-Type', 'text/plain; charset=utf-8')
        instance.body = s.encode('utf-8')
        return instance

    @classmethod
    def json(cls, obj: Any, status: int = 200):
        instance = cls(status=status)
        # Use specified separators and sort_keys
        json_str = json.dumps(obj, separators=(',', ':'), sort_keys=True)
        instance.headers.add('Content-Type', 'application/json')
        instance.body = json_str.encode('utf-8')
        return instance

    def to_bytes(self) -> bytes:
        """Serialises the response into raw bytes.
        """
        lines = []

        # Status Line
        reason = get_reason_phrase(self.status)
        lines.append(f"HTTP/1.1 {self.status} {reason}")

        # Headers
        # Track Content-Length to enforce it as the last header
        content_length = len(self.body)
        content_length_set = False

        # Iterate over headers, excluding Content-Length if present
        header_pairs = self.headers.items()
        for name, value in header_pairs:
            if name.lower() == 'content-length':
                continue
            lines.append(f"{name}: {value}")

        # Content-Length must be the last header
        lines.append(f"Content-Length: {content_length}")

        # End of headers
        lines.append('')

        # Body
        body_bytes = self.body

        return "\r\n".join(lines).encode('ascii') + b"\r\n" + body_bytes

# --- Request Parsing Logic ---

def parse_request(data: bytes) -> Request:
    """Parses exactly one request from raw bytes.
    """

    try:
        # 1. Find separation point
        separator = b"\r\n\r\n"
        if separator not in data:
            raise BadRequest("Request missing CRLFCRLF separator.")

        header_data_bytes, body_data_bytes = data.split(separator, 1)

        # 2. Decode head (ISO-8859-1)
        header_lines_bytes = header_data_bytes.split(b"\r\n")
        header_lines_str = [line.decode('iso-8859-1') for line in header_lines_bytes if line]

        if not header_lines_str:
            raise BadRequest("Empty request head.")

        # 3. Request Line Parsing
        request_line_str = header_lines_str[0]
        parts = request_line_str.split(' ', 2)

        if len(parts) != 3:
            raise BadRequest("Invalid request line format.")

        method, target, version = parts

        if not re.fullmatch(r'[A-Z]+', method):
            raise BadRequest("Invalid method format.")
        if not target.startswith('/'):
            raise BadRequest("Target must start with '/'.")
        if version not in ("HTTP/1.1", "HTTP/1.0"):
            raise BadRequest("Unsupported HTTP version.")

        # 4. Header Parsing
        headers = Headers()
        header_fields: Dict[str, str] = {}
        for i, line in enumerate(header_lines_str[1:]):
            # Check for obsolete line folding
            if line.startswith(' ') or line.startswith('\t'):
                raise BadRequest("Obsolete line folding found.")

            if ':' not in line:
                # This line should not be a header if it doesn't have a colon, unless it's a body artifact that slipped through.
                raise BadRequest(f"Malformed header line: {line}")

            name, value = [s.strip() for s in line.split(':', 1)]
            headers.set(name, value)
            header_fields[name.lower()] = value # Store for quick access

        # HTTP/1.1 Host requirement
        if version == "HTTP/1.1" and 'host' not in header_fields:
            raise BadRequest("HTTP/1.1 request requires a Host header.")

        # 5. Body Parsing (Content-Length vs Transfer-Encoding)
        content_length_str = header_fields.get('content-length')
        transfer_encoding = header_fields.get('transfer-encoding', '').lower()

        body_bytes = b''

        if 'transfer-encoding' in header_fields and transfer_encoding == 'chunked':
            # Chunked Encoding
            try:
                chunk_data_bytes = body_data_bytes
                current_pos = 0
                chunks: List[bytes] = []

                while current_pos < len(chunk_data_bytes):
                    # Find chunk size line
                    end_size_line = chunk_data_bytes.find(b'\r\n', current_pos)
                    if end_size_line == -1:
                         raise ValueError("Incomplete chunk size header.")
                    size_line = chunk_data_bytes[current_pos:end_size_line]

                    # Parse size (hex, potentially followed by ;extension)
                    size_str_match = re.match(r'([0-9a-fA-F]+)(?:;.*)?\r\n', size_line)
                    if not size_str_match:
                        raise ValueError("Invalid chunk size line format.")

                    size_hex = size_str_match.group(1)
                    chunk_size = int(size_hex, 16)

                    current_pos = end_size_line + 2 # Move past '\r\n'

                    if chunk_size == 0:
                        # End of data. Now skip optional trailer lines and the final empty line
                        trailer_start = current_pos
                        trailer_end = chunk_data_bytes.find(b'\r\n\r\n', trailer_start)
                        if trailer_end == -1:
                            raise ValueError("Missing trailing CRLFCRLF after zero chunk.")
                        current_pos = trailer_end + 4
                        break

                    # Read chunk data
                    chunk_start = current_pos
                    chunk_end = chunk_start + chunk_size
                    if chunk_end > len(chunk_data_bytes):
                        raise ValueError("Incomplete chunk body data.")

                    chunk = chunk_data_bytes[chunk_start:chunk_end]
                    chunks.append(chunk)
                    current_pos = chunk_end + 2 # Move past chunk body's '\r\n'
                    # Skip optional trailer lines until final empty line
                    if chunk_size > 0: # Only check for trailer if it wasn't the zero chunk
                        trailer_end = chunk_data_bytes.find(b'\r\n\r\n', current_pos)
                        if trailer_end == -1:
                            raise ValueError("Incomplete trailer/final CRLFCRLF.")
                        current_pos = trailer_end + 4

                body_bytes = b''.join(chunks)

            except (ValueError, IndexError) as e:
                raise BadRequest(f"Chunked body decoding failed: {e}")

        elif content_length_str:
            # Content-Length Decoding
            try:
                length = int(content_length_str)
                if len(body_data_bytes) != length:
                    raise BadRequest(f"Body size mismatch. Expected {length}, got {len(body_data_bytes)}.")
                body_bytes = body_data_bytes
            except ValueError:
                raise BadRequest("Content-Length must be decimal digits only.")
        else:
            # Neither header present, body is empty
            body_bytes = b''

        # Check for leftover bytes
        if transfer_encoding == 'chunked':
            # If we exited the chunk loop, we processed up to current_pos. If current_pos < len(chunk_data_bytes), there's leftover data.
            # However, the logic above handles the zero chunk correctly, so we check if we consumed everything up to the final CRLFCRLF.
            # A simpler check: if the total data length matches what we expected or if we reached the end after zero chunk.
            if chunk_data_bytes.find(b'\r\n\r\n', current_pos) != -1:
                raise BadRequest("Extra data found after chunked body.")
        elif content_length_str and len(body_data_bytes) != int(content_length_str):
             # This case is handled above, but keeping robust checks.
             pass
        elif not content_length_str and transfer_encoding != 'chunked':
            # If neither specified, body must be empty, and body_data_bytes must be empty.
            if body_data_bytes:
                raise BadRequest("Unexpected data present when no body headers are provided.")


        return Request(
            method=method,
            target=target,
            path=target.split('?')[0],
            query_string=target.split('?', 1)[-1] if '?' in target else '',
            version=version,
            headers=headers,
            body=body_bytes,
            params={},
            state={}
        )

    except HTTPError as e:
        # Re-raise known errors
        raise e
    except Exception as e:
        # Catch all parsing errors and convert to BadRequest if not already an HTTPError
        if not isinstance(e, BadRequest):
             raise BadRequest(f"Fatal parsing error: {type(e).__name__}: {str(e)}")
        else:
            raise e

