                if segment == '': continue # Should only happen if pattern starts/ends with / or has //

                if segment.startswith('{') and segment.endswith('}'):
                    content = segment[1:-1]
                    match = re.match(r'(\w+):(\w+)', content)
                    name = match.group(1)
                    converter = match.group(2)

