from typing import Callable, List, Any, Dict
from web.request import Request, Response, HTTPError, BadRequest, parse_request
from web.router import Router, MethodNotAllowed

# Type definition for middleware
Middleware = Callable[[Request, Callable[[], Response]], Response]

class App:
    """Application wrapper that runs middleware before the router."""
    def __init__(self, router: Router, middleware: List[Middleware] = ()): 
        self.router = router
        self.middleware = middleware

    def use(self, mw: Middleware) -> 'App':
        """Appends a middleware function to the chain."""
        self.middleware.append(mw)
        return self

    def _create_error_response(self, error: HTTPError, request: Request = None) -> Response:
        """Creates a standardized HTTP error response from an HTTPError object."""
        status = error.status
        reason = error.reason

        response = Response(status=status)

        if isinstance(error, MethodNotAllowed):
            # Special handling for MethodNotAllowed
            response.headers.add("Allow", ", ".join(sorted(error.allowed)))

        response.text(f"{status} {reason}")
        return response

    def handle(self, request: Request) -> Response:
        """Runs the request through the middleware chain."""

        # The innermost function that calls the router
        def call_next() -> Response:
            try:
                # Dispatch handles setting request.params and calling handler
                return self.router.dispatch(request)
            except HTTPError as e:
                # Convert HTTPErrors (like 404, 405) into responses
                return self._create_error_response(e, request)
            except Exception as e:
                # Convert all other exceptions to 500 Internal Server Error
                return Response.text(f"500 Internal Server Error")

        # Chain middleware functions. The first one is the outermost.
        # We construct the chain by iterating backwards, so that the last item in self.middleware
        # is wrapped by the first lambda, making it the innermost call to call_next.
        chain = call_next
        for mw in reversed(self.middleware):
            # Wrap the current chain link for the next middleware in line
            # The lambda captures the current state of 'chain' (the next function in the chain)
            chain = lambda req, next_fn=chain: mw(req, next_fn)

        # The final 'chain' is the outermost middleware wrapper, which when called with the request,
        # will execute the entire chain down to call_next.
        return chain(request)

    def handle_bytes(self, data: bytes) -> bytes:
        """Parses raw bytes, runs through middleware, and returns response bytes. Bypasses middleware on parsing error."""
        try:
            # 1. Parse the request
            request = parse_request(data)

            # 2. Run through the middleware chain
            response = self.handle(request)

            # 3. Return response bytes
            return response.to_bytes()

        except BadRequest:
            # 1. If parsing fails (BadRequest), return 400 error response immediately.
            # We cannot create a full Request object, so we create a minimal error response.
            response = Response(status=400)
            response.text("400 Bad Request")
            return response.to_bytes()

        except Exception:
            # Catch any unexpected errors during parsing that might not be BadRequest (e.g., if parse_request raises something else)
            # Although the prompt implies only BadRequest from parsing, defensive coding suggests handling unexpected failures.
            # If parsing fails for a reason other than BadRequest, we treat it as a parsing failure (400).
            response = Response(status=400)
            response.text("400 Bad Request")
            return response.to_bytes()

