        lines.append(f"{request.method} {request.path} {response.status}")
        return response
    return middleware

def cookies() -> Middleware:
    """Parses the Cookie header and stores cookies in request.state['cookies']."""
    def middleware(request: Request, call_next: Callable[[], Response]) -> Response:
        cookies_state: Dict[str, str] = {}
        cookie_header = request.headers.get("cookie")

        if cookie_header:
            # Split by semicolon
            for cookie_pair in cookie_header.split(';'):
                cookie_pair = cookie_pair.strip()
                if not cookie_pair:
                    continue

                # Split into name and value, only on the first '='
                if '=' in cookie_pair:
                    name, value = cookie_pair.split('=', 1)
                    # Cookie names keep their case (unlike Content-Type params)
                    cookies_state[name.strip()] = value.strip()
                elif cookie_pair.strip():
                    # Handle name only case, though less common for cookies
                    cookies_state[cookie_pair.strip()] = ""

        request.state['cookies'] = cookies_state
        return call_next()
    return middleware

def basic_auth(users: Dict[str, str], realm: str = 'app') -> Middleware:
    """Authenticates requests based on the Authorization header."""
    def middleware(request: Request, call_next: Callable[[], Response]) -> Response:
        auth_header = request.headers.get("authorization")

        if not auth_header or not auth_header.startswith("Basic "): 
            # No authorization header or wrong format, proceed or error based on requirement. 
            # Requirement says: Anything else gets a 401 error response...
            # We assume if it's missing, it fails auth unless it's explicitly allowed.
            # Given the prompt implies it stops the chain on failure:
            pass # Let the logic below handle the failure case

        elif auth_header.startswith("Basic "): 
            encoded_creds = auth_header[len("Basic "):].strip()

            try:
                # Decode the base64 string
                decoded_bytes = base64.b64decode(encoded_creds).decode('ascii')

                # Split at the first colon
                if ':' not in decoded_bytes:
                    raise ValueError("Invalid credentials format")

                user, password = decoded_bytes.split(':', 1)

                if user in users and users[user] == password:
