                    response = Response(status=401)
                    response.headers.add("WWW-Authenticate", f"Basic realm=\"{realm}\"")
                    response.text("401 Unauthorized")
                    return response
            except (ValueError, TypeError, base64.binascii.Error):
                # Decoding failed or format was wrong
                response = Response(status=401)
                response.headers.add("WWW-Authenticate", f"Basic realm=\"{realm}\"")
                response.text("401 Unauthorized")
                return response

        # If the header was missing or didn't start with 'Basic ', we treat it as not authenticated and let the chain run.
        # Re-reading the requirement: "Anything else gets a 401 error response... and the rest of the chain does not run." 
        # This implies if Authorization is absent or invalid, it should return 401.
        # Let's enforce this interpretation for robustness:
        else:
            response = Response(status=401)
            response.headers.add("WWW-Authenticate", f"Basic realm=\"{realm}\"")
            response.text("401 Unauthorized")
            return response

