import re
from typing import Any, List, Dict, Set, Union, Tuple

# --- Error Values and Exceptions ---

class FormulaError(ValueError):
    """Raised when a formula is syntactically invalid or refers to an invalid cell."""
    pass

class ErrorValue(str):
    """Represents a calculation error (e.g., #ERROR! or #CYCLE!)."""
    pass

# Define specific error constants
ERROR_ERROR = ErrorValue("#ERROR!")
ERROR_CYCLE = ErrorValue("#CYCLE!")

# --- Abstract Syntax Tree (AST) Nodes ---

class ASTNode:
    """Base class for AST nodes."""
    pass

class NumberNode(ASTNode):
    def __init__(self, value: Union[int, float]):
        self.value = value

class RefNode(ASTNode):
    def __init__(self, name: str):
        self.name = name.upper()

class UnaryOpNode(ASTNode):
    def __init__(self, op: str, operand: ASTNode):
        self.op = op  # '+' or '-' (unary)
        self.operand = operand

class BinaryOpNode(ASTNode):
    def __init__(self, op: str, left: ASTNode, right: ASTNode):
        self.op = op  # '+', '-', '*', '/'
        self.left = left
        self.right = right

class ParenNode(ASTNode):
    def __init__(self, expr: ASTNode):
        self.expr = expr

# --- Formula Parsing (Shunting-Yard variant or Recursive Descent) ---

# Grammar: expr := term {(+ | -) term}
# term := unary {(* | /) unary}
# unary  := (+ | -) unary | number | ref | ( expr )
# number := digits [. digits]
# ref    := letters digits

# Regex tokens
NUMBER_REGEX = r'(  f{0,3} |  f{0,3}                                                                                     )'
REF_REGEX = r'([A-Z]{1,2}[0-9]{1,3})'
WHITESPACE = r'	|
|| ' 

# Tokenizing helpers
def tokenize(source: str) -> List[str]:
    # This implementation simplifies tokenization significantly for brevity, focusing on the required structure.
    # A full implementation requires robust regex matching across the entire expression.
    # For this context, we assume a simple split/pattern matching approach sufficient for structure validation.
    tokens = []
    source = source.strip()
    i = 0
    while i < len(source):
        char = source[i]
        if char.isspace():
            i += 1
            continue

        # Numbers
        match_num = re.match(r'\d+(\.\d+)?', source[i:])
        if match_num:
            tokens.append(match_num.group(0))
            i += len(match_num.group(0))
            continue

        # References (A1, B10, Z999)
        match_ref = re.match(r'[A-Z]\d+', source[i:], re.IGNORECASE)
        if match_ref and len(match_ref.group(0)) > 1 and len(match_ref.group(0)[0].isalpha()) == 1:
             # Check if it strictly matches ref grammar: letters digits. Since we parse after '=', the first char is usually a letter.
             # We must ensure it's not just a stray letter.
            if match_ref.group(0)[0].isalpha():
                tokens.append(match_ref.group(0).upper())
                i += len(match_ref.group(0))
                continue

        # Operators and Parentheses
        if char in '+-*/()':
            tokens.append(char)
            i += 1
            continue

        # If none of the above, it's an invalid character
        raise FormulaError(f"Unexpected character: {char} at position {i}")

    return tokens

class Parser:
    """Recursive Descent Parser."""
    def __init__(self, tokens: List[str]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Union[str, None]:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self, expected: str = None) -> str:
        token = self.tokens[self.pos]
        if expected and token != expected:
            raise FormulaError(f"Expected '{expected}' but found '{token}'")
        self.pos += 1
        return token

    # Grammar functions

    def parse_expression(self) -> ASTNode:
        # expr := term {(+ | -) term}
        node = self.parse_term()
        while self.peek() in ('+', '-'):
            op = self.consume()
            right = self.parse_term()
            node = BinaryOpNode(op, node, right)
        return node

    def parse_term(self) -> ASTNode:
        # term := unary {(* | /) unary}
        node = self.parse_unary()
        while self.peek() in ('*', '/'):
            op = self.consume()
            right = self.parse_unary()
            node = BinaryOpNode(op, node, right)
        return node

    def parse_unary(self) -> ASTNode:
        # unary  := (+ | -) unary | number | ref | ( expr )
        token = self.peek()

        if token in ('+', '-'):
            op = self.consume()
            # Unary operator binds tighter than binary operators
            return UnaryOpNode(op, self.parse_unary())

        elif token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
            # Number
            self.consume()
            try:
                if '.' in token:
                    return NumberNode(float(token))
                else:
                    return NumberNode(int(token))
            except ValueError:
                 raise FormulaError(f"Invalid number format: {token}")

        elif token.isalpha() and self.tokens[self.pos+1] and self.tokens[self.pos+1].isdigit():
            # Reference
            name = self.consume()
            return RefNode(name)

        elif token == '(': 
            self.consume('(')
            expr = self.parse_expression()
            self.consume(')')
            return ParenNode(expr)

        else:
            raise FormulaError(f"Unexpected token in unary expression: {token}")

    def parse(self) -> ASTNode:
        if not self.tokens: 
            raise FormulaError("Empty formula input")

        ast = self.parse_expression()
        if self.pos != len(self.tokens):
            # Catches trailing garbage
            raise FormulaError(f"Unparsed tokens remaining: {self.tokens[self.pos:]}")
        return ast

# --- Public API Functions ---

def parse_formula(source: str) -> ASTNode:
    """Parses the text after '=' into an AST. Raises FormulaError on failure."""
    if not source or not source.strip():
        raise FormulaError("Empty formula input")

    # Note: The tokenization must handle whitespace correctly according to the spec.
    # The provided tokenization is a placeholder for robustness.
    tokens = tokenize(source)
    parser = Parser(tokens)
    return parser.parse()


def references(tree: ASTNode) -> Set[str]:
    """Recursively finds all cell references in the AST."""
    found_refs: Set[str] = set()

    def traverse(node: ASTNode):
        if isinstance(node, RefNode):
            found_refs.add(node.name)
        elif isinstance(node, BinaryOpNode):
            traverse(node.left)
            traverse(node.right)
        elif isinstance(node, UnaryOpNode):
            traverse(node.operand)
        elif isinstance(node, ParenNode):
            traverse(node.expr)

    traverse(tree)
    return found_refs


def evaluate(tree: ASTNode, lookup: callable) -> Union[int, float, str, ErrorValue]:
    """Computes the formula's value given a lookup function."""

    def apply_op(left_val, right_val, op):
        # Rule 3: If an operand is an error value, the result is that error value (the left one if both are).
        if isinstance(left_val, ErrorValue) or isinstance(right_val, ErrorValue):
            return left_val if isinstance(left_val, ErrorValue) else right_val

        # Rule 3: If an operand is text, the result is #ERROR!.
        if isinstance(left_val, str) and not isinstance(left_val, ErrorValue) or 
           isinstance(right_val, str) and not isinstance(right_val, ErrorValue):
            return ERROR_ERROR

        # Numeric operations
        try:
            if op in ('+', '-'):
                return left_val + right_val if op == '+' else left_val - right_val
            elif op == '*':
                return left_val * right_val
            elif op == '/':
                if right_val == 0:
                    return ERROR_ERROR
                return left_val / right_val
        except TypeError:
            # This catches attempts to mix types that aren't strings/errors (e.g., int + None if not handled by rule 3)
            return ERROR_ERROR

    def evaluate_node(node: ASTNode) -> Union[int, float, str, ErrorValue]:
        if isinstance(node, NumberNode):
            return node.value

        elif isinstance(node, RefNode):
            # Rule 2: Reference evaluation
            cell_value = lookup(node.name)

            if cell_value is None: # Empty cell
                return 0 # Rule 2: empty cell gives 0 for calculation purposes

            if isinstance(cell_value, str) and not isinstance(cell_value, ErrorValue):
                # Rule 2: A formula that is only a reference therefore returns text unchanged
                return cell_value

            # If it's a number or error value, return it directly
            return cell_value

        elif isinstance(node, UnaryOpNode):
            operand_val = evaluate_node(node.operand)
            if node.op == '+':
                return operand_val if isinstance(operand_val, (int, float)) else ERROR_ERROR
            elif node.op == '-':
                if isinstance(operand_val, (int, float)): return -operand_val
                elif isinstance(operand_val, str) and not isinstance(operand_val, ErrorValue): return ERROR_ERROR # Text cannot be negated
                return operand_val # Error value propagates
            return ERROR_ERROR # Should not happen

        elif isinstance(node, BinaryOpNode):
            left_val = evaluate_node(node.left)
            right_val = evaluate_node(node.right)
            return apply_op(left_val, right_val, node.op)

        elif isinstance(node, ParenNode):
            return evaluate_node(node.expr)

    return evaluate_node(tree)
