from typing import Set, Iterable

class DependencyGraph:
    """Manages dependencies between cells in the sheet."""
    def __init__(self):
        # Maps cell name -> set of cells it refers to (Precedents)
        self._precedents: Dict[str, Set[str]] = {}
        # Maps cell name -> set of cells that refer to it (Dependents)
        self._dependents: Dict[str, Set[str]] = {}

    def set_dependencies(self, cell: str, precedents: Iterable[str]):
        """Replaces cell's precedents and updates the dependency graph."""
        new_precedents = set(precedents)
        self._precedents[cell] = new_precedents

        # 1. Clear old dependent relationships for this cell
        if cell in self._dependents:
            for dependent in self._dependents[cell].copy():
                self._dependents[dependent].discard(cell)

        # 2. Set new dependent relationships
        for p in new_precedents:
            if p not in self._dependents: 
                self._dependents[p] = set()
            self._dependents[p].add(cell)

        # 3. Ensure the cell itself is tracked even if it has no precedents
        if cell not in self._dependents:
            self._dependents[cell] = set()

    def precedents(self, cell: str) -> Set[str]:
        """Returns the direct predecessors of a cell."""
        return self._precedents.get(cell, set())

    def dependents(self, cell: str) -> Set[str]:
        """Returns the direct dependents of a cell."""
        return self._dependents.get(cell, set())

    def all_dependents(self, cell: str) -> Set[str]:
        """Returns every cell that refers to cell directly or transitively, including cell itself if on a cycle."""
        queue = list(self.dependents.get(cell, set()))
        visited = set(self.dependents.get(cell, set()))
        all_d = set(self.dependents.get(cell, set()))

        # Cycle detection for self-reference is handled implicitly by the iteration logic.
        # We need to check for self-reference in precedents for cycle detection later, 
        # but for this specific requirement: 'It contains cell itself only when cell is on a cycle.'

        while queue:
            current = queue.pop(0)

            # Add current cell to the result set
            all_d.add(current)

            # Add its dependents to the queue
            for next_dep in self.dependents.get(current, set()):
                if next_dep not in visited:
                    visited.add(next_dep)
                    queue.append(next_dep)

        # Check for self-cycle
        if cell in self.precedents.get(cell, set()):
             all_d.add(cell)

        return all_d

    def cycle_cells(self) -> Set[str]:
        """Returns every cell that lies on a cycle (i.e., following precedents leads back to itself)."""
        cycle = set()
        # Check every cell to see if it is part of a cycle
        all_cells = set(self._precedents.keys())

        for cell in all_cells:
            path: Set[str] = set()
            current = cell

            while current is not None and current not in path:
                if current == cell and len(path) > 0:
                    # Found a cycle involving 'cell'
                    return {cell}

                if current in path:
                    # This is a cycle, but we need to trace back to see if 'cell' is in it. 
                    # Simpler approach: just detect if path leads back to 'cell' at the start.
                    break

                path.add(current)

                pre = self.precedents.get(current)
                if not pre:
                    break

                # Pick an arbitrary precedent to trace the path backwards
                current = next(iter(pre)) 

        # Note: The definition given implies tracing *precedents* leads back to self. 
        # A rigorous cycle detection (like Tarjan's or DFS with states) is needed for correctness.
        # For this implementation, we rely on DFS path tracking.

        def find_cycles_dfs(start_node: str, current_node: str, path: Set[str], recursion_stack: Set[str]):
            path.add(current_node)
            recursion_stack.add(current_node)

            for precedent in self.precedents.get(current_node, set()):
                if precedent in recursion_stack:
                    # Cycle detected! All nodes from 'precedent' to 'current_node' are in the cycle.
                    cycle.add(precedent)
                    cycle.add(current_node)
                    # For simplicity, we mark them all as cycle nodes if any part of the path closes.
                elif precedent not in path:
                    find_cycles_dfs(start_node, precedent, path, recursion_stack)

            recursion_stack.remove(current_node)
            path.remove(current_node)

        # Iterating over all known cells and running DFS to find cycles
        for cell in all_cells:
            if cell not in cycle:
                find_cycles_dfs(cell, cell, set(), set())

        return cycle
