import operator
from typing import Any, Callable, Union, List, Set, Dict

# --- Placeholder Definitions based on Prompt Context (In reality, these would be defined elsewhere) ---

class FormulaError(ValueError):
    """Raised for syntax errors in formulas."""
    pass

class ErrorValue(str):
    """Represents a calculated error state."""
    def __new__(cls, value: str):
        return super().__new__(cls, value)

    def __eq__(self, other):
        if isinstance(other, ErrorValue): return self.value == other.value
        return self.value == str(other)

class ASTNode:
    """Base class for AST nodes."""
    pass

class NumberLiteral(ASTNode):
    def __init__(self, value: Union[int, float]):
        self.value = value

class ReferenceNode(ASTNode):
    def __init__(self, name: str):
        self.name = name

class UnaryOpNode(ASTNode):
    def __init__(self, op: str, operand: ASTNode):
        self.op = op  # '+' or '-' (unary)
        self.operand = operand

class BinaryOpNode(ASTNode):
    def __init__(self, op: str, left: ASTNode, right: ASTNode):
        self.op = op  # '+', '-', '*', '/'
        self.left = left
        self.right = right

class ParenthesizedExprNode(ASTNode):
    def __init__(self, expression: ASTNode):
        self.expression = expression

# --- Evaluation Logic Implementation ---

# Type alias for clarity
CellValue = Union[int, float, str, None, ErrorValue]

def _is_error(value: CellValue) -> bool:
    """Checks if a value is an ErrorValue."""
    return isinstance(value, ErrorValue)

def _handle_reference_value(name: str, lookup: Callable[[str], CellValue]) -> CellValue:
    """Implements Rule 2: Reference handling."""
    value = lookup(name)

    if value is None:
        # Empty cell gives 0
        return 0

    if _is_error(value):
        return value

    # If the formula is ONLY a reference, it returns text unchanged.
    # We assume if this function is called directly on a ReferenceNode, 
    # this is the context for the 'unchanged text' return.
    if isinstance(value, str) and not value.isdigit() and '.' not in value:
         # If the retrieved value is text (and not just a number string representation)
         return value

    # Otherwise, return the value as is (number or string that might be a literal in context)
    return value

def _apply_binary_op(op: str, left_val: CellValue, right_val: CellValue) -> CellValue:
    """Implements Rule 3 and Rule 4 arithmetic.

    Returns: ErrorValue if an error is present, or computed value.
    """
    # Rule 3: Error propagation (left one if both)
    if _is_error(left_val): return left_val
    if _is_error(right_val): return right_val

    # Check if either operand is text
    is_left_text = isinstance(left_val, str) and not isinstance(left_val, ErrorValue)
    is_right_text = isinstance(right_val, str) and not isinstance(right_val, ErrorValue)

    if is_left_text or is_right_text:
        # If text is involved in arithmetic, result is #ERROR!
        return ErrorValue("#ERROR!")

    # Both are numeric (int or float)
    try:
        if op == '+':
            return left_val + right_val
        elif op == '-':
            return left_val - right_val
        elif op == '*':
            return left_val * right_val
        elif op == '/':
            # Rule 4: Division by zero
            if right_val == 0:
                return ErrorValue("#ERROR!")
            # Rule 4: Always results in float
            return float(left_val) / float(right_val)
    except TypeError:
        # Should theoretically not happen if type checking above is correct,
        # but acts as a catch-all for unexpected type mismatches.
        return ErrorValue("#ERROR!")

    return ErrorValue("#ERROR!") # Should be unreachable

def _evaluate_unary(op: str, operand_val: CellValue) -> CellValue:
    """Handles unary +/- operators.
    """
    if _is_error(operand_val): return operand_val

    # If the operand is text, unary op results in #ERROR!
    if isinstance(operand_val, str) and not isinstance(operand_val, ErrorValue):
        return ErrorValue("#ERROR!")

    # Numeric handling
    val = float(operand_val) if isinstance(operand_val, float) else float(operand_val)

    if op == '+':
        return val
    elif op == '-':
        return -val

    return operand_val # Should not happen

def _evaluate_term(tree: ASTNode, lookup: Callable[[str], CellValue]) -> CellValue:
    """Handles multiplication and division (higher precedence).
    """
    if isinstance(tree, NumberLiteral): return tree.value
    if isinstance(tree, ReferenceNode): return _handle_reference_value(tree.name, lookup)
    if isinstance(tree, ParenthesizedExprNode): return _evaluate_expr(tree.expression, lookup)
    if isinstance(tree, UnaryOpNode): return _evaluate_unary(tree.op, _evaluate_term(tree.operand, lookup)) # Unary binds tighter than *, /

    if isinstance(tree, BinaryOpNode) and tree.op in ('*', '/'):
        left = _evaluate_term(tree.left, lookup)
        right = _evaluate_term(tree.right, lookup)
        return _apply_binary_op(tree.op, left, right)

    # If we reached here, the structure was unexpected for a 'term'
    return ErrorValue("#ERROR!")

def _evaluate_expr(tree: ASTNode, lookup: Callable[[str], CellValue]) -> CellValue:
    """Handles addition and subtraction (lower precedence, left-associative).
    """
    # For expr, we start by evaluating the first term
    if isinstance(tree, NumberLiteral): return tree.value
    if isinstance(tree, ReferenceNode): return _handle_reference_value(tree.name, lookup)
    if isinstance(tree, ParenthesizedExprNode): return _evaluate_expr(tree.expression, lookup)
    if isinstance(tree, UnaryOpNode): return _evaluate_unary(tree.op, _evaluate_expr(tree.operand, lookup)) # Unary can appear at expr level if it's the first element

    if isinstance(tree, BinaryOpNode) and tree.op in ('+', '-'):
        # Left-associative evaluation
        left_val = _evaluate_expr(tree.left, lookup)
        current_result = left_val

        # Process remaining right side recursively
        right_tree = tree.right

        # Handle sequential binary ops: L op R1 op R2 -> (L op R1) op R2
        # Since we only handle one binary op node structure here, we process it iteratively.
        # Note: A true left-associative implementation requires flattening the tree structure
        # or using a loop. We simplify for a single BinaryOpNode structure matching the grammar
        # (expr := term {(+ | -) term}) by evaluating the entire right side as the second operand.
        right_val = _evaluate_expr(right_tree, lookup)

        return _apply_binary_op(tree.op, left_val, right_val)

    # Fallback for complex structures not handled by simple recursion
    return ErrorValue("#ERROR!")

# The main entry point function required by the task
def evaluate(tree: ASTNode, lookup: Callable[[str], CellValue]) -> CellValue:
    """Computes the formula's value based on the AST tree and cell lookup map.

    Args:
        tree: The root of the formula's Abstract Syntax Tree.
        lookup: A function that takes an uppercase cell name (str) and returns its current CellValue.

    Returns: The computed CellValue (int, float, str, ErrorValue, or None/0).
    """
    # The top level of the grammar is 'expr'
    return _evaluate_expr(tree, lookup)

