# --- Formula Parsing (Shunting-Yard variant or Recursive Descent) ---

# Grammar additions for Range: arg := ref : ref | expr
# We extend the parser to recognize 'ref : ref' as a new token structure.

# Regex tokens
NUMBER_REGEX = r'(  f{0,3} |  f{0,3}                                                                                     )'
REF_REGEX = r'([A-Z]{1,2}[0-9]{1,3})'
RANGE_REGEX = r'([A-Z]{1,2}[0-9]{1,3})\s*:\s*([A-Z]{1,2}[0-9]{1,3})'
WHITESPACE = r'	|
|| ' 

# Tokenizing helpers
def tokenize(source: str) -> List[str]:
