# Update evaluate signature to accept Sheet object context
def evaluate(tree: ASTNode, sheet: Sheet, lookup: LookupFunc) -> Union[int, float, str, ErrorValue]:
    """Computes the formula's value given a lookup function and Sheet context."""

    def apply_op(left_val, right_val, op):
        # Rule 3: If an operand is an error value, the result is that error value (the left one if both are).
        if isinstance(left_val, ErrorValue) or isinstance(right_val, ErrorValue):
            return left_val if isinstance(left_val, ErrorValue) else right_val

        # Rule 3: If an operand is text, the result is #ERROR!.
        if isinstance(left_val, str) and not isinstance(left_val, ErrorValue) or 
           isinstance(right_val, str) and not isinstance(right_val, ErrorValue):
            return ERROR_ERROR

        # Numeric operations
        try:
            if op in ('+', '-'):
                return left_val + right_val if op == '+' else left_val - right_val
            elif op == '*':
                return left_val * right_val
            elif op == '/':
                if right_val == 0:
                    return ERROR_ERROR
                return left_val / right_val
        except TypeError:
            # This catches attempts to mix types that aren't strings/errors (e.g., int + None if not handled by rule 3)
            return ERROR_ERROR

    def evaluate_node(node: ASTNode) -> Union[int, float, str, ErrorValue, List[Union[int, float]]]:

        if isinstance(node, NumberNode):
            return node.value

        elif isinstance(node, RefNode):
            # Rule 2: Reference evaluation
            cell_value = lookup(node.name)

            if cell_value is None: # Empty cell
                return 0 # Rule 2: empty cell gives 0 for calculation purposes

            if isinstance(cell_value, str) and not isinstance(cell_value, ErrorValue):
                # Rule 2: A formula that is only a reference therefore returns text unchanged
                return cell_value

            # If it's a number or error value, return it directly
            return cell_value

        elif isinstance(node, RangeNode):
            # CORE LOGIC: Range Evaluation
            collected = _collect_range_values(sheet, node.start, node.end, lookup)

            if isinstance(collected, ErrorValue):
                return collected # Range returned an error
            # Successfully collected numbers; return the list
            return collected

        elif isinstance(node, UnaryOpNode):
            operand_val = evaluate_node(node.operand)

            # Handle unary operations on ranges (e.g., -A1:B3). The requirement states: 
            # "An argument that is a single reference, with or without parentheses, is treated as a one-cell range, so text in it is skipped." 
            # Since ranges are only allowed as function arguments, unary ops on ranges are likely invalid syntax or imply applying the op to the first element.
            # For robust calculation, if unary op hits a range, we treat it as applying the op to the first collected number, or propagate error.
            if isinstance(operand_val, list):
                if not operand_val: return ERROR_ERROR
                operand_val = operand_val[0] # Take first number if range

            if isinstance(operand_val, (int, float)):
                if node.op == '+': return operand_val
                if node.op == '-': return -operand_val

            # If operand was error, text, or list (and empty), propagate error
            return ERROR_ERROR

        elif isinstance(node, BinaryOpNode):
            left_val = evaluate_node(node.left)
            right_val = evaluate_node(node.right)

            # Handle case where one side is a range (list) and the other is a number/error
            if isinstance(left_val, list) and isinstance(right_val, (int, float, ErrorValue)):
                # Range on left, scalar/error on right
                if isinstance(left_val, ErrorValue): return left_val
                # Range -> List[num], Scalar/Error on Right
                right_val = [right_val]
            elif isinstance(right_val, list) and isinstance(left_val, (int, float, ErrorValue)):
                # Scalar/Error on left, Range on right
                if isinstance(right_val, ErrorValue): return right_val
                # Scalar/Error on Left, Range -> List[num]
                left_val = [left_val]

            # Now both are lists or scalars/errors
            if isinstance(left_val, list) and isinstance(right_val, list):
                # Both are ranges. Arithmetic on ranges is undefined in the spec, assume #ERROR! or first element comparison.
                # Since the spec focuses on collecting numbers *from* ranges for functions, we treat this as invalid binary operation.
                return ERROR_ERROR 

            # If one is a list and the other is scalar, the list should have been expanded above. If we reach here, we have (scalar op scalar) or (error op error).

            return apply_op(left_val, right_val, node.op)

        elif isinstance(node, ParenNode):
            return evaluate_node(node.expr)

    # The main entry point now requires the sheet context
    return evaluate_node(tree)
