from typing import List, Dict, Any, Set, Optional, Tuple
from .formula import FormulaError, ErrorValue, parse_formula, references, evaluate, ERROR_ERROR, ERROR_CYCLE
from .graph import DependencyGraph

# Constants
MAX_COL = 26 # A-Z
MAX_ROW = 999

class Sheet:
    """The main spreadsheet engine orchestrator."""
    def __init__(self):
        # Internal storage: CellName -> Value (int, float, str, None, ErrorValue)
        self._values: Dict[str, Any] = {}
        # Input storage: CellName -> Raw String input
        self._raws: Dict[str, str] = {}
        # Dependency tracking
        self.graph = DependencyGraph()
        # Calculation tracking
        self.evaluations: int = 0

    def _cell_to_name(self, col_idx: int, row: int) -> str:
        """Converts 0-indexed column and 1-indexed row to uppercase cell name."""
        if not (0 <= col_idx < MAX_COL and 1 <= row <= MAX_ROW):
            raise ValueError("Cell name out of bounds")

        # Convert 0-indexed column to letter (A=0, B=1, ...)
        col_letter = chr(ord('A') + col_idx)
        return col_letter + str(row)

    def _name_to_cell(self, name: str) -> Tuple[int, int]:
        """Converts uppercase cell name (e.g., 'B7') to (col_idx, row)."""
        if not name or not name[0].isalpha() or not name[1:].isdigit():
            raise ValueError(f"Invalid cell name format: {name}")

        col_char = name[0].upper()
        row_str = name[1:]

        col_idx = ord(col_char) - ord('A')
        row = int(row_str)

        if not (0 <= col_idx < MAX_COL and 1 <= row <= MAX_ROW):
             raise ValueError(f"Cell name {name} is outside sheet boundaries (A-Z, 1-999).")
        if row_str.startswith('0') and len(row_str) > 1: # Check for leading zero restriction on rows > 0
             raise ValueError(f"Cell name {name} has an invalid leading zero in row number.")

        return col_idx, row

    def _is_valid_name(self, name: str) -> bool:
        """Checks if the name conforms to sheet constraints (case, bounds, no leading zero on row)."""
        try:
            self._name_to_cell(name)
            return True
        except ValueError:
            return False

    def _get_all_cell_names(self) -> List[str]:
        """Generates all cell names in row-major order."""
        names = []
        for r in range(1, MAX_ROW + 1):
            for c in range(MAX_COL):
                names.append(self._cell_to_name(c, r))
        return names

    def _calculate_all(self) -> List[str]:
        """
        Recalculates all formulas in the sheet based on current values, respecting cycles.
        Returns a list of cells whose value might have changed, in row-major order.
        This mimics a full scratch calculation.
        """
        cycle_cells = self.graph.cycle_cells()
        new_values = self._values.copy()
        new_evaluations = 0
        all_names = self._get_all_cell_names()

        for name in all_names:
            raw_input = self._raws.get(name, '')

            if raw_input == '' and name not in self._values: 
                new_values[name] = None
                continue

            if name in cycle_cells:
                new_values[name] = ERROR_CYCLE
                continue

            if not raw_input.strip().startswith('='):
                try:
                    val = float(raw_input) if '.' in raw_input else int(raw_input)
                    new_values[name] = val
                except ValueError:
                    new_values[name] = raw_input
                continue

            try:
                formula_source = raw_input[1:].strip()
                if not formula_source:
                    new_values[name] = None 
                    continue

                ast = parse_formula(formula_source)
                precedents_set = references(ast)
                self.graph.set_dependencies(name, precedents_set)

                def lookup(ref_name: str) -> Any:
                    return new_values.get(ref_name, None)

                result = evaluate(ast, self, lookup)

                if isinstance(result, ErrorValue):
                    new_values[name] = result
                elif isinstance(result, str) and not isinstance(result, ErrorValue):
                    new_values[name] = result
                else:
                    new_values[name] = result

                new_evaluations += 1

            except FormulaError:
                new_values[name] = ERROR_ERROR
            except Exception:
                new_values[name] = ERROR_ERROR

        old_values = self._values.copy()
        self._values = new_values
        self.evaluations = new_evaluations

        changed = []
        for name in all_names:
            if old_values.get(name) != self._values.get(name):
                changed.append(name)

        return changed

    def set(self, name: str, raw: str) -> List[str]:
        if not self._is_valid_name(name):
            raise ValueError(f"Name '{name}' is outside the sheet or invalid.")
        if not isinstance(raw, str):
            raise TypeError("Raw input must be a string.")

        self._raws[name] = raw
        changed_cells = self._calculate_all()
        return sorted(changed_cells)

    def get(self, name: str) -> Any:
        if not self._is_valid_name(name):
            raise ValueError(f"Name '{name}' is outside the sheet or invalid.")

        value = self._values.get(name)
        return value if value is not None else None

    def raw(self, name: str) -> str:
        if not self._is_valid_name(name):
            raise ValueError(f"Name '{name}' is outside the sheet or invalid.")
        return self._raws.get(name, '')

    def cells(self) -> List[str]:
        non_empty = [name for name, raw in self._raws.items() if raw.strip() != '']
        return sorted(non_empty, key=lambda name: (int(name[1:]), ord(name[0]))) 

    @property
    def evaluations(self) -> int:
        return self._evaluations
