import re
from typing import Any, List, Dict, Set, Union, Tuple

# --- Error Values and Exceptions ---

class FormulaError(ValueError):
    """Raised when a formula is syntactically invalid or refers to an invalid cell."""
    pass

class ErrorValue(str):
    """Represents a calculation error (e.g., #ERROR! or #CYCLE!)."""
    pass

# Define specific error constants
ERROR_ERROR = ErrorValue("#ERROR!")
ERROR_DIV_ZERO = ErrorValue("#DIV/0!")
ERROR_REF = ErrorValue("#REF!")
ERROR_CYCLE = ErrorValue("#CYCLE!")

# --- Abstract Syntax Tree (AST) Nodes ---

class ASTNode:
    """Base class for AST nodes."""
    pass

class NumberNode(ASTNode):
    def __init__(self, value: Union[int, float]):
        self.value = value

class RefNode(ASTNode):
    def __init__(self, name: str):
        self.name = name.upper()

class UnaryOpNode(ASTNode):
    def __init__(self, op: str, operand: ASTNode):
        self.op = op  # '+' or '-' (unary)
        self.operand = operand

class BinaryOpNode(ASTNode):
    def __init__(self, op: str, left: ASTNode, right: ASTNode):
        self.op = op  # '+', '-', '*', '/'
        self.left = left
        self.right = right

class ParenNode(ASTNode):
    def __init__(self, expr: ASTNode):
        self.expr = expr

class CallNode(ASTNode):
    """Represents a function call: fname(arg1, arg2, ...)"""
    def __init__(self, func_name: str, args: List[ASTNode]):
        self.func_name = func_name.upper()
        self.args = args

class RangeNode(ASTNode):
    """Represents a range reference: ref1:ref2"""
    def __init__(self, start_ref: str, end_ref: str):
        self.start_ref = start_ref.upper()
        self.end_ref = end_ref.upper()

# --- Formula Parsing (Recursive Descent) ---

# Function names allowed
FUNCTION_NAMES = {'SUM', 'AVG', 'MIN', 'MAX'}

# Regex tokens
# Note: Simplified number regex from original, focusing on structural additions.
NUMBER_REGEX = r'(\d+(\.\d+)?)'
REF_REGEX = r'([A-Z]+[0-9]+)'
WHITESPACE = r'\t|\n|\r|\f'

# Tokenizing helpers
def tokenize(source: str) -> List[str]:
    tokens = []
    source = source.strip()
    i = 0
    while i < len(source):
        char = source[i]
        if char.isspace():
            i += 1
            continue

        # 1. Numbers
        match_num = re.match(r'\d+(\.\d+)?', source[i:])
        if match_num:
            tokens.append(match_num.group(0))
            i += len(match_num.group(0))
            continue

        # 2. Function Names
        match_func = re.match(r'[A-Z]{2,}', source[i:], re.IGNORECASE)
        if match_func and match_func.group(0).upper() in FUNCTION_NAMES:
             tokens.append(match_func.group(0).upper())
             i += len(match_func.group(0))
             continue

        # 3. References (e.g., A1, B100)
        # Updated to be slightly more general to catch function names if they weren't matched above, but we prioritize function names.
        match_ref = re.match(r'[A-Z]+\d+', source[i:], re.IGNORECASE)
        if match_ref and not match_func: # Only treat as ref if it wasn't identified as a function
             tokens.append(match_ref.group(0).upper())
             i += len(match_ref.group(0))
             continue

        # 4. Operators and Delimiters
        if char in '+-*/()':
            tokens.append(char)
            i += 1
            continue

        # 5. Range Separator (:) - Must be checked last among symbols
        if char == ':':
            tokens.append(':')
            i += 1
            continue

        # If none of the above, it's an invalid character
        raise FormulaError(f"Unexpected character: {char} at position {i}")

    return tokens

class Parser:
    """Recursive Descent Parser."""
    def __init__(self, tokens: List[str]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Union[str, None]:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self, expected: str = None) -> str:
        token = self.tokens[self.pos]
        if expected and token != expected:
            raise FormulaError(f"Expected '{expected}' but found '{token}'")
        self.pos += 1
        return token

    # --- Argument Parsing (arg := ref : ref | expr) ---
    def parse_arg(self) -> ASTNode:
        # Check if the next token starts a range (i.e., it's a RefNode)
        start_token = self.peek()
        if start_token and re.match(r'[A-Z]+\d+', start_token) and self.pos + 1 < len(self.tokens) and self.tokens[self.pos+1] == ':':
            # It looks like a range: ref1 : ref2
            ref1 = self.consume()
            self.consume(':')
            ref2 = self.consume()
            return RangeNode(ref1, ref2)

        # Otherwise, it must be a general expression (including a single RefNode or ParenNode)
        return self.parse_expression()

    # --- Call Parsing (call := fname ( arg {, arg} ) ) ---
    def parse_call(self) -> CallNode:
        # The function name must have been consumed before calling this, so we assume self.peek() is the start of arguments or '('.
        func_name = self.tokens[self.pos-1]
        self.consume()
        self.consume('(')

        args: List[ASTNode] = []
        if self.peek() is not None and self.peek() != ')':
            # Parse first argument
            args.append(self.parse_arg())

            # Parse subsequent arguments
            while self.peek() == ',' and self.peek() != ')':
                self.consume(',')
                args.append(self.parse_arg())

        self.consume(')')

        if not args:
            # Rule: call with no arguments raises FormulaError
            raise FormulaError("Function call requires at least one argument.")

        return CallNode(func_name, args)

    # --- Main Grammar Functions ---

    def parse_expression(self) -> ASTNode:
        # expr := term {(+ | -) term}
        node = self.parse_term()
        while self.peek() in ('+', '-'):
            op = self.consume()
            right = self.parse_term()
            node = BinaryOpNode(op, node, right)
        return node

    def parse_term(self) -> ASTNode:
        # term := unary {(* | /) unary}
        node = self.parse_unary()
        while self.peek() in ('*', '/'):
            op = self.consume()
            right = self.parse_unary()
            node = BinaryOpNode(op, node, right)
        return node

    def parse_unary(self) -> ASTNode:
        # unary  := (+ | -) unary | number | ref | call | ( expr )
        token = self.peek()

        if token in ('+', '-'):
            op = self.consume()
            return UnaryOpNode(op, self.parse_unary())

        elif token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
            # Number
            self.consume()
            try:
                if '.' in token:
                    return NumberNode(float(token))
                else:
                    return NumberNode(int(token))
            except ValueError:
                 raise FormulaError(f"Invalid number format: {token}")

        elif token == '(': 
            self.consume('(')
            expr = self.parse_expression()
            self.consume(')')
            return ParenNode(expr)

        # Check for Function Call (Call)
        elif token in FUNCTION_NAMES:
            func_name = self.consume()
            return self.parse_call()

        # Check for Reference (Ref)
        elif re.match(r'[A-Z]+\d+', token): # Check if it matches ref structure
            name = self.consume()
            return RefNode(name)

        else:
            raise FormulaError(f"Unexpected token in unary expression: {token}")

    def parse(self) -> ASTNode:
        if not self.tokens: 
            raise FormulaError("Empty formula input")

        ast = self.parse_expression()
        if self.pos != len(self.tokens):
            # Catches trailing garbage
            raise FormulaError(f"Unparsed tokens remaining: {self.tokens[self.pos:]}")
        return ast

# --- Public API Functions ---

def parse_formula(source: str) -> ASTNode:
    """Parses the text after '=' into an AST. Raises FormulaError on failure."""
    if not source or not source.strip():
        raise FormulaError("Empty formula input")

    # Tokenize handles the complexity of recognizing functions, ranges (via :), and refs.
    tokens = tokenize(source)
    parser = Parser(tokens)
    return parser.parse()


def references(tree: ASTNode) -> Set[str]:
    """Recursively finds all cell references in the AST."""
    found_refs: Set[str] = set()

    def traverse(node: ASTNode):
        if isinstance(node, RefNode):
            found_refs.add(node.name)
        elif isinstance(node, RangeNode):
            # Collect all cell names contained within the range definition (needed for dependency tracking)
            # Note: Full range expansion is complex; here we just add the corner references as predecessors.
            found_refs.add(node.start_ref)
            found_refs.add(node.end_ref)
        elif isinstance(node, CallNode):
            for arg in node.args:
                traverse(arg)
        elif isinstance(node, BinaryOpNode):
            traverse(node.left)
            traverse(node.right)
        elif isinstance(node, UnaryOpNode):
            traverse(node.operand)
        elif isinstance(node, ParenNode):
            traverse(node.expr)

    traverse(tree)
    return found_refs


def evaluate(tree: ASTNode, lookup: callable) -> Union[int, float, str, ErrorValue]:
    """Computes the formula's value given a lookup function."""

    def apply_op(left_val, right_val, op):
        # Rule 3: If an operand is an error value, the result is that error value (the left one if both are).
        if isinstance(left_val, ErrorValue) or isinstance(right_val, ErrorValue):
            return left_val if isinstance(left_val, ErrorValue) else right_val

        # Rule 3: If an operand is text, the result is #ERROR!.
        if isinstance(left_val, str) and not isinstance(left_val, ErrorValue) or 
           isinstance(right_val, str) and not isinstance(right_val, ErrorValue):
            return ERROR_ERROR

        # Numeric operations
        try:
            if op in ('+', '-'):
                return left_val + right_val if op == '+' else left_val - right_val
            elif op == '*':
                return left_val * right_val
            elif op == '/':
                if right_val == 0:
                    return ERROR_DIV_ZERO
                return left_val / right_val
        except TypeError:
            # This catches attempts to mix types that aren't strings/errors (e.g., int + None if not handled by rule 3)
            return ERROR_ERROR

    def evaluate_node(node: ASTNode) -> Union[int, float, str, ErrorValue]:
        if isinstance(node, NumberNode):
            return node.value

        elif isinstance(node, RefNode):
            # Rule 2: Reference evaluation
            cell_value = lookup(node.name)

            if cell_value is None: # Empty cell
                return 0 # Rule 2: empty cell gives 0 for calculation purposes

            if isinstance(cell_value, str) and not isinstance(cell_value, ErrorValue):
                # Rule 2: A formula that is only a reference therefore returns text unchanged
                return cell_value

            # If it's a number or error value, return it directly
            return cell_value

        elif isinstance(node, RangeNode):
            # Range expansion: The arguments for function calls must handle this, but if a RangeNode is evaluated standalone (e.g., =A1:B3), it's ambiguous. 
            # Based on spec, ranges are ONLY allowed as function arguments. If we reach here, we treat it as an error or return a placeholder.
            # Since the spec implies it must resolve to a set of numbers/errors, we throw an error if used outside a function.
            raise FormulaError("Range references are only permitted as function arguments.")

        elif isinstance(node, UnaryOpNode):
            operand_val = evaluate_node(node.operand)
            if node.op == '+':
                return operand_val if isinstance(operand_val, (int, float)) else ERROR_ERROR
            elif node.op == '-':
                if isinstance(operand_val, (int, float)): return -operand_val
                elif isinstance(operand_val, str) and not isinstance(operand_val, ErrorValue): return ERROR_ERROR # Text cannot be negated
                return operand_val # Error value propagates
            return ERROR_ERROR # Should not happen

        elif isinstance(node, BinaryOpNode):
            left_val = evaluate_node(node.left)
            right_val = evaluate_node(node.right)
            return apply_op(left_val, right_val, node.op)

        elif isinstance(node, ParenNode):
            return evaluate_node(node.expr)

        elif isinstance(node, CallNode):
            # --- Function Call Evaluation Logic ---
            func_name = node.func_name
            collected_numbers: List[Union[int, float]] = []

            # 1. Evaluate arguments and collect numbers/check for errors
            for arg_node in node.args:
                arg_result = evaluate_node(arg_node)

                if isinstance(arg_result, ErrorValue):
                    # The call's result is the first error met in this order.
                    return arg_result 

                if isinstance(arg_result, str) and not isinstance(arg_result, ErrorValue):
                    # Text argument -> #VALUE!
                    if func_name in ('MIN', 'MAX'): # MIN/MAX usually skip text, but based on strict rule: "text gives #VALUE!"
                        return ERROR_ERROR 
                    elif func_name == 'AVG': # AVG requires numbers
                        return ERROR_ERROR 
                    elif func_name == 'SUM': # SUM can technically sum text if coerced, but standard is numeric
                        return ERROR_ERROR
                    # If text is passed to other functions, we treat it as an error if not skipped.
                    return ERROR_ERROR # Treating non-numeric text as immediate #VALUE! error for safety

                # If it's a number, collect it
                if isinstance(arg_result, (int, float)):
                    collected_numbers.append(arg_result)
                # If it's None (empty), it's skipped implicitly by not being added to collected_numbers.

            # 2. Compute result based on function
            if not collected_numbers and func_name in ('MIN', 'MAX'):
                return 0 # MIN/MAX gives 0 when none are collected

            if func_name == 'SUM':
                return sum(collected_numbers) if all(isinstance(n, int) for n in collected_numbers) else sum(collected_numbers) # Python handles mixed int/float sum correctly

            elif func_name == 'AVG':
                if not collected_numbers:
                    return ERROR_DIV_ZERO
                return sum(collected_numbers) / len(collected_numbers)

            elif func_name == 'MIN':
                return min(collected_numbers)

            elif func_name == 'MAX':
                return max(collected_numbers)

            return ERROR_ERROR # Should be unreachable

    return evaluate_node(tree)
