        self.left = left
        self.right = right

class ParenNode(ASTNode):
    def __init__(self, expr: ASTNode):
        self.expr = expr

# --- Formula Parsing (Shunting-Yard variant or Recursive Descent) ---

# Grammar additions for Range: arg := ref : ref | expr
# We extend the parser to recognize 'ref : ref' as a new token structure.

# Regex tokens
NUMBER_REGEX = r'(  f{0,3} |  f{0,3}                                                                                     )'
REF_REGEX = r'([A-Z]{1,2}[0-9]{1,3})'
RANGE_REGEX = r'([A-Z]{1,2}[0-9]{1,3})\s*:\s*([A-Z]{1,2}[0-9]{1,3})'
WHITESPACE = r'	|
|| ' 

# Tokenizing helpers
def tokenize(source: str) -> List[str]:
    tokens = []
    source = source.strip()
    i = 0
    while i < len(source):
        char = source[i]
        if char.isspace():
            i += 1
            continue

        # 1. Check for Range (ref : ref)
        match_range = re.match(RANGE_REGEX, source[i:], re.IGNORECASE)
        if match_range:
            # Push the full range token, e.g., 'A1:B3'
            tokens.append(match_range.group(0).upper())
            i += len(match_range.group(0))
            continue

        # 2. Numbers
        match_num = re.match(r'\d+(\.\d+)?', source[i:])
        if match_num:
            tokens.append(match_num.group(0))
            i += len(match_num.group(0))
            continue

        # 3. References (A1, B10, Z999)
        match_ref = re.match(r'[A-Z]\d+', source[i:], re.IGNORECASE)
        if match_ref and len(match_ref.group(0)) > 1 and len(match_ref.group(0)[0].isalpha()) == 1:
            tokens.append(match_ref.group(0).upper())
            i += len(match_ref.group(0))
            continue

        # 4. Operators and Parentheses
        if char in '+-*/()':
            tokens.append(char)
            i += 1
            continue

        # If none of the above, it's an invalid character
        raise FormulaError(f"Unexpected character: {char} at position {i}")

    return tokens

class Parser:
    """Recursive Descent Parser."""
    def __init__(self, tokens: List[str]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Union[str, None]:
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def consume(self, expected: str = None) -> str:
        token = self.tokens[self.pos]
        if expected and token != expected:
            raise FormulaError(f"Expected '{expected}' but found '{token}'")
        self.pos += 1
        return token

    # Grammar functions

    def parse_expression(self) -> ASTNode:
        # expr := term {(+ | -) term}
        node = self.parse_term()
        while self.peek() in ('+', '-'):
            op = self.consume()
            right = self.parse_term()
            node = BinaryOpNode(op, node, right)
        return node

    def parse_term(self) -> ASTNode:
        # term := unary {(* | /) unary}
        node = self.parse_unary()
        while self.peek() in ('*', '/'):
            op = self.consume()
            right = self.parse_unary()
            node = BinaryOpNode(op, node, right)
        return node

    def parse_unary(self) -> ASTNode:
        # unary  := (+ | -) unary | number | ref | range | ( expr )
        token = self.peek()

        if token in ('+', '-'):
            op = self.consume()
            # Unary operator binds tighter than binary operators
            return UnaryOpNode(op, self.parse_unary())

        elif token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
            # Number
            self.consume()
            try:
                if '.' in token:
                    return NumberNode(float(token))
                else:
                    return NumberNode(int(token))
            except ValueError:
                 raise FormulaError(f"Invalid number format: {token}")

        elif token.isalpha() and self.tokens[self.pos+1] and self.tokens[self.pos+1].isdigit():
            # Reference
            name = self.consume()
            return RefNode(name)

        elif re.match(r'[A-Z]\d*:\s*[A-Z]\d*', token, re.IGNORECASE): # Range detected
            # Consume the full range token, e.g., 'A1:B3'
            range_token = self.consume()
            start_ref, end_ref = [r.strip() for r in range_token.split(':')]
            return RangeNode(start_ref, end_ref)

        elif token == '(': 
            self.consume('(')
            expr = self.parse_expression()
            self.consume(')')
            return ParenNode(expr)

        else:
            raise FormulaError(f"Unexpected token in unary expression: {token}")

    def parse(self) -> ASTNode:
        if not self.tokens: 
            raise FormulaError("Empty formula input")

        ast = self.parse_expression()
        if self.pos != len(self.tokens):
            # Catches trailing garbage
            raise FormulaError(f"Unparsed tokens remaining: {self.tokens[self.pos:]}")
        return ast

# --- Range Collection Logic ---

def _collect_range_values(sheet: Sheet, start_ref: str, end_ref: str, lookup: callable) -> Union[List[Union[int, float]], ErrorValue]:
    """Collects numerical values from a range, handling errors and out-of-bounds references.
    Returns a list of numbers, or an ErrorValue if an error occurs.
    """
    try:
        # 1. Convert corners to (col_idx, row) indices.
        # Sheet methods raise ValueError if bounds are violated, which we catch.
        start_col, start_row = sheet._name_to_cell(start_ref)
        end_col, end_row = sheet._name_to_cell(end_ref)
    except ValueError: 
        # This catches both invalid formatting and out-of-sheet bounds for the corners.
        return ERROR_REF

    # 2. Determine iteration bounds (Row-major order: iterate rows, then columns)
    # min/max coordinates are calculated by comparing row/col indices.
    min_row = min(start_row, end_row)
    max_row = max(start_row, end_row)
    min_col = min(start_col, end_col)
    max_col = max(start_col, end_col)

    collected_numbers: List[Union[int, float]] = []

    # 3. Iterate row-major
    for r in range(min_row, max_row + 1):
        for c in range(min_col, max_col + 1):
            # Convert back to name for lookup
            cell_name = sheet._cell_to_name(c, r)

            # 4. Lookup and Process Value
            cell_value = lookup(cell_name)

            if cell_value is None: # Empty cell
                continue

            if isinstance(cell_value, str) and not isinstance(cell_value, ErrorValue):
                # Skip text cells
                continue

            if isinstance(cell_value, ErrorValue):
                # Propagate error immediately (first error encountered)
                return cell_value

            # Must be a number or None (but None was handled above)
            if isinstance(cell_value, (int, float)):
                collected_numbers.append(cell_value)

    return collected_numbers

# --- Public API Functions ---

def parse_formula(source: str) -> ASTNode:
    """Parses the text after '=' into an AST. Raises FormulaError on failure."""
    if not source or not source.strip():
        raise FormulaError("Empty formula input")

    tokens = tokenize(source)
    parser = Parser(tokens)
    return parser.parse()


def references(tree: ASTNode) -> Set[str]:
    """Recursively finds all cell references in the AST."""
    found_refs: Set[str] = set()

    def traverse(node: ASTNode):
        if isinstance(node, RefNode):
            found_refs.add(node.name)
        elif isinstance(node, BinaryOpNode):
            traverse(node.left)
            traverse(node.right)
        elif isinstance(node, UnaryOpNode):
            traverse(node.operand)
        elif isinstance(node, ParenNode):
            traverse(node.expr)
        elif isinstance(node, RangeNode):
            # Range nodes refer to many cells, but we only list the corners for dependency tracking here.
            found_refs.add(node.start)
            found_refs.add(node.end)

    traverse(tree)
    return found_refs

# Type alias for lookup function: CellName -> Any (Value)
LookupFunc = callable

# Update evaluate signature to accept Sheet object context
def evaluate(tree: ASTNode, sheet: Sheet, lookup: LookupFunc) -> Union[int, float, str, ErrorValue]:
    """Computes the formula's value given a lookup function and Sheet context."""

    def apply_op(left_val, right_val, op):
        # Rule 3: If an operand is an error value, the result is that error value (the left one if both are).
        if isinstance(left_val, ErrorValue) or isinstance(right_val, ErrorValue):
            return left_val if isinstance(left_val, ErrorValue) else right_val

        # Rule 3: If an operand is text, the result is #ERROR!.
        if isinstance(left_val, str) and not isinstance(left_val, ErrorValue) or 
           isinstance(right_val, str) and not isinstance(right_val, ErrorValue):
            return ERROR_ERROR

        # Numeric operations
        try:
            if op in ('+', '-'):
                return left_val + right_val if op == '+' else left_val - right_val
            elif op == '*':
                return left_val * right_val
            elif op == '/':
                if right_val == 0:
                    return ERROR_ERROR
                return left_val / right_val
        except TypeError:
            # This catches attempts to mix types that aren't strings/errors (e.g., int + None if not handled by rule 3)
            return ERROR_ERROR

    def evaluate_node(node: ASTNode) -> Union[int, float, str, ErrorValue, List[Union[int, float]]]:

        if isinstance(node, NumberNode):
            return node.value

        elif isinstance(node, RefNode):
            # Rule 2: Reference evaluation
            cell_value = lookup(node.name)

            if cell_value is None: # Empty cell
                return 0 # Rule 2: empty cell gives 0 for calculation purposes

            if isinstance(cell_value, str) and not isinstance(cell_value, ErrorValue):
                # Rule 2: A formula that is only a reference therefore returns text unchanged
                return cell_value

            # If it's a number or error value, return it directly
            return cell_value

        elif isinstance(node, RangeNode):
            # CORE LOGIC: Range Evaluation
            collected = _collect_range_values(sheet, node.start, node.end, lookup)

            if isinstance(collected, ErrorValue):
                return collected # Range returned an error
            # Successfully collected numbers; return the list
            return collected

        elif isinstance(node, UnaryOpNode):
            operand_val = evaluate_node(node.operand)

            # Handle unary operations on ranges (e.g., -A1:B3). The requirement states: 
            # "An argument that is a single reference, with or without parentheses, is treated as a one-cell range, so text in it is skipped." 
            # Since ranges are only allowed as function arguments, unary ops on ranges are likely invalid syntax or imply applying the op to the first element.
            # For robust calculation, if unary op hits a range, we treat it as applying the op to the first collected number, or propagate error.
            if isinstance(operand_val, list):
                if not operand_val: return ERROR_ERROR
                operand_val = operand_val[0] # Take first number if range

            if isinstance(operand_val, (int, float)):
                if node.op == '+': return operand_val
                if node.op == '-': return -operand_val

            # If operand was error, text, or list (and empty), propagate error
            return ERROR_ERROR

        elif isinstance(node, BinaryOpNode):
            left_val = evaluate_node(node.left)
            right_val = evaluate_node(node.right)

            # Handle case where one side is a range (list) and the other is a number/error
            if isinstance(left_val, list) and isinstance(right_val, (int, float, ErrorValue)):
                # Range on left, scalar/error on right
                if isinstance(left_val, ErrorValue): return left_val
                # Range -> List[num], Scalar/Error on Right
                right_val = [right_val]
            elif isinstance(right_val, list) and isinstance(left_val, (int, float, ErrorValue)):
                # Scalar/Error on left, Range on right
                if isinstance(right_val, ErrorValue): return right_val
                # Scalar/Error on Left, Range -> List[num]
                left_val = [left_val]

            # Now both are lists or scalars/errors
            if isinstance(left_val, list) and isinstance(right_val, list):
                # Both are ranges. Arithmetic on ranges is undefined in the spec, assume #ERROR! or first element comparison.
                # Since the spec focuses on collecting numbers *from* ranges for functions, we treat this as invalid binary operation.
                return ERROR_ERROR 

            # If one is a list and the other is scalar, the list should have been expanded above. If we reach here, we have (scalar op scalar) or (error op error).

            return apply_op(left_val, right_val, node.op)

        elif isinstance(node, ParenNode):
            return evaluate_node(node.expr)

    # The main entry point now requires the sheet context
    return evaluate_node(tree)
