from typing import List, Optional

class TicTacToe:
    """Represents the state of a Tic-Tac-Toe game."""
    def __init__(self, board: str = '.........'):
        if len(board) != 9:
            raise ValueError("TicTacToe board must have length 9.")

        x_count = board.count('X')
        o_count = board.count('O')

        if not all(c in ('X', 'O', '.') for c in board):
            raise ValueError("TicTacToe board must only contain 'X', 'O', or '.'.")

        # X must have the same number of marks as O or one more
        if not (x_count == o_count or x_count == o_count + 1):
            raise ValueError("Impossible counts of 'X' and 'O' on the board.")

        self.board = board

    def __eq__(self, other):
        if not isinstance(other, TicTacToe):
            return NotImplemented
        return self.board == other.board

    def __hash__(self):
        return hash(self.board)

    def __str__(self) -> str:
        # One line per row from the top, joined with '\n' (no trailing newline)
        # Rows are 3 cells each. Index 0-2 is row 1, 3-5 is row 2, 6-8 is row 3.
        return f"{self.board[0:3]}\n{self.board[3:6]}\n{self.board[6:9]}"

    def get_counts(self) -> tuple[int, int]:
        x_count = self.board.count('X')
        o_count = self.board.count('O')
        return x_count, o_count

    def _get_player_from_counts(self, x_count: int, o_count: int) -> str:
        # X always moves first
        if x_count == o_count: # X is next
            return 'X'
        elif x_count == o_count + 1:
            return 'O'
        # This case should not happen if called internally after validation
        raise RuntimeError("Invalid counts for determining next player.")

    def player(self) -> str:
        """Returns the player to move ('X' or 'O')."""
        x_count, o_count = self.get_counts()
        return self._get_player_from_counts(x_count, o_count)

    def moves(self) -> List[int]:
        """Returns the legal moves (square numbers) in ascending order."""
        if self.is_over():
            return []
        return [i for i, char in enumerate(self.board) if char == '.']

    def play(self, move: int) -> 'TicTacToe':
        """Returns a new state with the move made. Raises ValueError if illegal."""
        if self.is_over():
            raise ValueError("Cannot make a move, the game is over.")
        if not (0 <= move <= 8) or self.board[move] != '.':
            raise ValueError(f"Illegal move: square {move} is invalid or taken.")

        new_board = list(self.board)
        new_board[move] = self.player()
        return TicTacToe("".join(new_board))

    def winner(self) -> Optional[str]:
        """Returns 'X', 'O', or None."""
        b = list(self.board)
        # Check rows and columns
        for i in range(3):
            # Rows
            if b[i*3] == b[i*3+1] == b[i*3+2] and b[i*3] != '.':
                return b[i*3]
            # Columns
            if b[i] == b[i+3] == b[i+6] and b[i] != '.':
                return b[i]

        # Check diagonals
        # Top-left to bottom-right
        if b[0] == b[4] == b[8] and b[0] != '.':
            return b[0]
        # Top-right to bottom-left
        if b[2] == b[4] == b[6] and b[2] != '.':
            return b[2]

        return None

    def is_over(self) -> bool:
        """True when there is a winner or the board is full."""
        return self.winner() is not None or len(self.moves()) == 0

    @classmethod
    def from_moves(cls, moves: List[int]) -> 'TicTacToe':
        """Plays the given squares in order from the empty board, raising ValueError at the first illegal one."""
        initial_board = '.........'
        current_state = cls(initial_board)

        for move in moves:
            try:
                current_state = current_state.play(move)
            except ValueError as e:
                raise ValueError(f"Illegal move during sequence: {e}")

        return current_state
