    Recursive Negamax implementation with alpha-beta pruning.
    Returns the score relative to the current player (state.player).
    """
    nodes_counter[0] += 1

    if state.is_over():
        winner = state.winner()
        if winner is None:  # Draw
            return 0.0
        else:
