            # The score is for the player who *just* moved to reach this state's opponent.
            # If state.player is 'X', and 'O' won, the score is bad for 'X'.
            # If the game is over, the score is relative to the player *to move* at the root.
            # Since the standard negamax framework evaluates from the current node's perspective,
            # we must adjust the terminal score relative to the player who *would have* moved next.

            # A finished game is scored for the player to move in it (the player whose turn it *was* before this state).
            # Since the state is terminal, we look at the winner.
            # The ply passed here is the number of moves taken to reach this terminal state.

            if winner == state.player: 
                # Current player won: Score proportional to speed (higher is better)
                return 1000.0 - ply
            else: # winner != state.player, or winner is None (already handled)
                # Current player lost: Score proportional to slowness (more negative is worse)
                return -(1000.0 - ply)

    if depth is not None and depth == 0:
        # Depth limit reached. Score using the provided heuristic.
        if evaluate:
            # The score is for the player to move in it (state.player)
            return evaluate(state)
        else:
            return 0.0

    # Recursive step
    best_val = -float('inf')
    moves = state.moves()

    # Ensure moves are processed in ascending order for tie-breaking
    for move in moves:
        new_state = state.play(move)
        # Negamax: invert the score received from the child node
        val = -_negamax(new_state,
                        depth - 1 if depth is not None else None,
                        -beta, 
                        -alpha,
                        ply + 1, 
                        evaluate, 
                        nodes_counter)

        if val > best_val:
            best_val = val

        # Alpha-beta pruning
        alpha = max(alpha, val)
        if alpha >= beta:
            break

    return best_val

