            break # Found the first move achieving the best score
        elif move_score > max_score: # Fallback/Safety check if the initial score calculation was slightly off due to path dependence
             max_score = move_score
             best_move = move

    return SearchResult(score, best_move, nodes_counter[0])

def best_move(state: object, depth: Optional[int] = None, evaluate: Optional[Callable[[object], float]] = None) -> object:
    """
    Returns the best move for the given state.
    """
    result = search(state, depth, evaluate)
    if result.move is None:
        raise ValueError("Game is over or no legal moves exist.")
    return result.move


def search_agent(depth: Optional[int] = None, evaluate: Optional[Callable[[object], float]] = None) -> Agent:
    """
    Returns an agent that plays best_move.
    """
    def agent(state: object) -> object:
        return best_move(state, depth, evaluate)
    return agent

def random_agent(seed: int) -> Agent:
    """
    Returns an agent that plays a random move.
    """
    rng = random.Random(seed)
    def agent(state: object) -> object:
        moves = state.moves()
        if not moves:
            raise ValueError("No legal moves available.")
        return rng.choice(moves)
    return agent
