    moves = state.moves()

    # Iterate through moves in ascending order to satisfy tie-breaking rule
    for move in moves:
        new_state = state.play(move)
        # Calculate the score resulting from this move
        # Note: We pass the initial alpha/beta for the top level comparison.
        # We need to re-run the search logic just to get the score for this specific move.
        # Re-using _negamax is complex here because we need the internal tracking/scoring logic.

        # For simplicity and adherence to the spec (finding the move that achieves 'score'), 
        # we will search for the move that maximizes the result of _negamax.
        # If the calculated 'score' from the first run is the true optimal value, 
        # we find the move that produces that value.

        # Re-running the search for each move is computationally expensive but necessary if we strictly need the move that produced the 'score' from the first run.
        # Since _negamax returns the value for the current player, we look for the move that yields the highest value.

        # A pragmatic approach: trust the score found, and then find the first move that produces a score equal to or very close to it.
        temp_nodes = [0]
        # The score returned by _negamax is relative to state.player
        move_score = -_negamax(new_state, depth - 1 if depth is not None else None, -float('inf'), float('inf'), 1, evaluate, temp_nodes) 

        # Due to floating point arithmetic, we check for near-equality
        if abs(move_score - score) < 1e-9:
            best_move = move
            break # Found the first move achieving the best score
        elif move_score > max_score: # Fallback/Safety check if the initial score calculation was slightly off due to path dependence
             max_score = move_score
             best_move = move

    return SearchResult(score, best_move, nodes_counter[0])

def best_move(state: object, depth: Optional[int] = None, evaluate: Optional[Callable[[object], float]] = None) -> object:
    """
    Returns the best move for the given state.
    """
    result = search(state, depth, evaluate)
    if result.move is None:
        raise ValueError("Game is over or no legal moves exist.")
    return result.move


def search_agent(depth: Optional[int] = None, evaluate: Optional[Callable[[object], float]] = None) -> Agent:
    """
    Returns an agent that plays best_move.
    """
    def agent(state: object) -> object:
        return best_move(state, depth, evaluate)
    return agent

def random_agent(seed: int) -> Agent:
    """
    Returns an agent that plays a random move.
    """
    rng = random.Random(seed)
    def agent(state: object) -> object:
        moves = state.moves()
        if not moves:
            raise ValueError("No legal moves available.")
        return rng.choice(moves)
    return agent

def play_game(state: object, agents: Dict[str, Agent]) -> Tuple[object, list]:
    """
    Plays a game between agents until it is over.
    Returns the final state and the list of moves played.
    Raises ValueError if any agent makes an illegal move.
    """
    current_state = state
    moves_played = []

    while not current_state.is_over():
        player = current_state.player()
        if player not in agents:
            raise ValueError(f"No agent provided for player: {player}")

        agent = agents[player]

        try:
            # Get move from agent
            move = agent(current_state)

            # Play move and update state (raises ValueError if illegal)
            current_state = current_state.play(move)
            moves_played.append(move)

        except ValueError as e:
            # Re-raise the ValueError originating from state.play(move) or agent logic if it's about illegal moves
            raise ValueError(f"Illegal move attempted by {player}: {e}")

    return current_state, moves_played
