from typing import List, Tuple, Optional

class ConnectFour:
    def __init__(self, columns: int = 7, rows: int = 6):
        if columns < 1 or rows < 1:
            raise ValueError("Columns and rows must be at least 1")
        self.columns = columns
        self.rows = rows
        # Internal board representation: board[row][col] where row 0 is the bottom
        self._board = [['.' for _ in range(columns)] for _ in range(rows)]
        self._move_history: List[int] = []

    def __eq__(self, other):
        if not isinstance(other, ConnectFour):
            return NotImplemented
        return self.board_as_list() == other.board_as_list()

    def __hash__(self):
        return hash(tuple(tuple(row) for row in self.board_as_list()))

    def board_as_list(self) -> List[List[str]]:
        return self._board

    def cell(self, column: int, row: int) -> str:
        """Returns the piece at (column, row). Row 0 is at the bottom."""
        if not (0 <= column < self.columns and 0 <= row < self.rows):
            raise IndexError("Column or row out of bounds")
        return self._board[row][column]

    def _get_next_open_row(self, col: int) -> Optional[int]:
        """Returns the lowest available row in the given column, or None if full."""
        for r in range(self.rows):
            if self._board[r][col] == '.':
                return r
        return None

    def moves(self) -> List[int]:
        """Returns a list of legal moves (column numbers) in ascending order."""
        legal_moves = []
        for c in range(self.columns):
            if self._get_next_open_row(c) is not None:
                legal_moves.append(c)
        return legal_moves

    def play(self, move: int) -> 'ConnectFour':
        """Returns a new state with the move made (the original is unchanged)."""
        # 1. Create a deep copy of the current state
        new_state = ConnectFour(self.columns, self.rows)
        new_state._board = [row[:] for row in self._board]
        new_state._move_history = self._move_history[:] # Copy history

        # 2. Check legality in the new state context
        legal_moves = new_state.moves()
        if move not in legal_moves:
            raise ValueError("Illegal move: column is full or out of bounds.")

        # 3. Apply the move
        row = new_state._get_next_open_row(move)
        new_state._board[row][move] = 'X' if len(new_state._move_history) % 2 == 0 else 'O'
        new_state._move_history.append(move)

        return new_state

    def winner(self) -> Optional[str]:
        """Returns the winner ('X' or 'O') or None if no winner."""
        # Check for 4-in-a-row
        R, C = self.rows, self.columns
        for p in ['X', 'O']:
            for r in range(R):
                for c in range(C):
                    if self.cell(c, r) == p:
                        # Horizontal check
                        if c + 3 <= C and all(self.cell(c + i, r) == p for i in range(4)):
                            return p
                        # Vertical check
                        if r + 3 <= R and all(self.cell(c, r + i) == p for i in range(4)):
                            return p
                        # Diagonal (bottom-left to top-right) check
                        if r + 3 <= R and c + 3 <= C and all(self.cell(c + i, r + i) == p for i in range(4)):
                            return p
                        # Diagonal (top-left to bottom-right) check
                        if r + 3 <= R and c - 3 >= -1 and all(self.cell(c - i, r + i) == p for i in range(4)):
                            return p
        return None

    def is_over(self) -> bool:
        """True when there is a winner or the board is full."""
        if self.winner() is not None:
            return True
        return len(self._move_history) == self.columns * self.rows

    def __str__(self) -> str:
        """Shows the top row first. Row index 0 in str() output is the top row (self.rows-1 in internal board)."""
        output_rows = []
        # Iterate from top row (self.rows - 1) down to bottom row (0)
        for r in range(self.rows - 1, -1, -1):
            output_rows.append("".join(self._board[r]))
        return '\n'.join(output_rows)

    @classmethod
    def from_moves(cls, moves: List[int], columns: int = 7, rows: int = 6) -> 'ConnectFour':
        """Plays a sequence of moves from an empty board, raising ValueError on illegal move."""
        state = cls(columns, rows)
        for move in moves:
            try:
                # We must call play on the state to ensure state immutability is respected
                state = state.play(move)
            except ValueError as e:
                raise ValueError(f"Illegal move at step {moves.index(move) + 1}: {e}")
        return state

# Heuristic evaluation function for depth-limited search
