    """Heuristic evaluation scored for state.player (X if X moves next)."""
    # NOTE: The documentation states: 'It looks at every window, a line of four cells (horizontal, vertical or diagonal) that fits on the board.'
    # The scoring is based on n*n where n is the count of pieces for the current player in that window.
    # The evaluation is for state.player, which is determined by the move count.

    R, C = state.rows, state.columns
    current_player = 'X' if len(state._move_history) % 2 == 0 else 'O'
    opponent_player = 'O' if current_player == 'X' else 'X'

