from dataclasses import dataclass, field
from typing import Tuple, List, Union, Any

# --- Error Handling ---
class RegexError(ValueError):
    """Custom exception for regex parsing errors."""
    def __init__(self, message: str, position: int):
        super().__init__(f"RegexError at position {position}: {message}")
        self.message = message
        self.position = position

# --- AST Definitions ---

@dataclass(frozen=True, eq=True)
class Empty:
    """Matches the empty string."""
    pass

@dataclass(frozen=True, eq=True)
class Literal:
    """Matches a literal character."""
    char: str

@dataclass(frozen=True, eq=True)
class AnyChar:
    """Matches any single character except '\n'."""
    pass

@dataclass(frozen=True, eq=True)
class CharClass:
    """Character class definition."""
    # Each item is a (low, high) pair, e.g., ('a', 'a') or ('a', 'z')
    items: Tuple[Tuple[str, str], ...] = field(compare=False)
    negated: bool = False

@dataclass(frozen=True, eq=True)
class Concat:
    """Concatenation of two or more nodes."""
    items: Tuple[Any, ...] = field(compare=False)

@dataclass(frozen=True, eq=True)
class Alt:
    """Alternation of two or more nodes."""
    options: Tuple[Any, ...] = field(compare=False)

@dataclass(frozen=True, eq=True)
class Star:
    """Zero or more repetitions (Kleene star)."""
    node: Any

@dataclass(frozen=True, eq=True)
class Plus:
    """One or more repetitions (Positive closure)."""
    node: Any

@dataclass(frozen=True, eq=True)
class Optional:
    """Zero or one repetition (Optional)."""
    node: Any

@dataclass(frozen=True, eq=True)
class Group:
    """A parenthesised sub-pattern."""
    node: Any

# --- Parser Implementation ---

# Helper class to manage parsing state
class Parser:
    def __init__(self, pattern: str):
        self.pattern = pattern
        self.pos = 0

    def peek(self) -> str: 
        return self.pattern[self.pos] if self.pos < len(self.pattern) else ''

    def consume(self) -> str:
        if self.pos >= len(self.pattern):
            raise RegexError("Unexpected end of pattern", self.pos)
        char = self.pattern[self.pos]
        self.pos += 1
        return char

    def match_literal(self, char: str) -> Literal:
        return Literal(char)

    def match_any_char(self) -> AnyChar:
        return AnyChar()

    def parse_char_class(self) -> CharClass:
        # Must have '['
        self.consume() # Consume '['
        start_pos = self.pos - 1

        negated = False
        if self.peek() == '^':
            negated = True
            self.consume() # Consume '^'

        items: List[Tuple[str, str]] = []

        # Check for empty class immediately after '[' or '[^']
        if self.peek() == ']':
            raise RegexError("Empty character class [], or [^]", start_pos)

        while self.peek() != ']':
            low_char = self.consume()

            # Check for range
            if self.peek() == '-':
                self.consume() # Consume '-'
                high_char = self.consume()
                if self.peek() == ']': # Range ends immediately
                    break
                # If it's not followed by ']', it's invalid in a simple parser context, but let's rely on the loop condition.

                if low_char > high_char: # Range low > high
                    raise RegexError(f"Range low ({low_char}) greater than high ({high_char})", start_pos + items.index((low_char, high_char)) + 1)

                items.append((low_char, high_char))
                continue
            else:
                # Single character
                items.append((low_char, low_char))

        self.consume() # Consume ']'

        if not items:
             raise RegexError("Empty character class [], or [^]", start_pos)

        return CharClass(tuple(items), negated)

    def parse_atom(self) -> Any:
        """Parses the smallest meaningful unit: literal, '.', class, or grouped pattern."""
        if self.pos >= len(self.pattern):
            raise RegexError("Expected atom, found end of pattern", self.pos)

        char = self.peek()

        # 1. Escaped character (\x)
        if char == '\':
            self.consume() # Consume '\'
            if self.pos >= len(self.pattern):
                raise RegexError("\ at the end of the pattern", self.pos - 1)
            escaped_char = self.consume()
            return Literal(escaped_char)

        # 2. Character Class ([...])
        elif char == '[':
            return self.parse_char_class()

        # 3. Grouping ((...))
        elif char == '(':
            self.consume() # Consume '('
            node = self.parse_expression() # Parse content inside group

            if self.peek() != ')':
                # Unclosed parenthesis error
                raise RegexError("Unclosed parenthesis", len(self.pattern))
            self.consume() # Consume ')'
            return Group(node)

        # 4. Any Character (.)
        elif char == '.':
            self.consume() # Consume '.'
            return AnyChar()

        # 5. Literal Character
        else:
            self.consume() # Consume literal
            return self.match_literal(char)

    def parse_quantifier(self, node: Any) -> Any:
        """Applies *, +, ? to the preceding atom/node."""
        if self.pos >= len(self.pattern):
            return node

        quantifier = self.peek()
        if quantifier in ('*', '+', '?'):
            self.consume() # Consume quantifier

            if node is Empty: 
                raise RegexError(f"Quantifier '{quantifier}' with nothing to repeat", self.pos - 1)

            if quantifier == '*':
                return Star(node)
            elif quantifier == '+':
                return Plus(node)
            elif quantifier == '?':
                return Optional(node)

        return node

    def parse_concat(self) -> Any:
        """Handles concatenation (implicit concatenation, binding tighter than |)."""
        # Start by parsing the next atom/quantified node
        try:
            node = self.parse_atom()
            node = self.parse_quantifier(node)
            items = [node]
        except RegexError as e:
            # If parse_atom fails here, it's an initial error.
            raise e
        else:
            items = [node]

        # Loop to handle subsequent concatenations
        while self.pos < len(self.pattern) and self.peek() not in ('|', ')'):
            # If the next character starts a new atom (literal, ., [, ()
            next_char = self.peek()
            if next_char in ('\', '.', '[' , '(') or (next_char.isalpha() and self.pattern[self.pos] not in ('|', ')' )):
                try:
                    next_node = self.parse_atom()
                    next_node = self.parse_quantifier(next_node)
                    items.append(next_node)
                except RegexError as e:
                    # If the next item fails to parse as an atom, we stop concatenation here.
                    break
            else:
                # Not an atom start, stop concatenation.
                break

        if len(items) == 1:
            return items[0]
        return Concat(tuple(items))

    def parse_expression(self) -> Any:
        """Handles alternation (|), binding loosest."""
        # First, parse the left-most expression (which handles concatenation)
        left_expr = self.parse_concat()
        options = [left_expr]

        # Loop to handle subsequent alternations
        while self.peek() == '|':
            self.consume() # Consume '|'
            try:
                right_expr = self.parse_concat()
                options.append(right_expr)
            except RegexError as e:
                 # If the right side of | fails to parse as a valid expression, report that error.
                 raise e

        if len(options) == 1:
            return options[0]
        return Alt(tuple(options))

    def parse(self) -> Any:
        """Entry point for parsing."""
        if not self.pattern:
            return Empty()

        # Start parsing the highest level expression
        ast = self.parse_expression()

        # Check for trailing characters
        if self.pos < len(self.pattern):
            # Check for unclosed '('
            if self.pattern[self.pos] == '(': 
                 raise RegexError("Unclosed parenthesis", self.pos)
            # If it's not '(', it means there are unexpected characters left over.
            raise RegexError(f"Unexpected character '{self.pattern[self.pos]}'", self.pos)

        # Handle the specific rule: A sequence of one node is that node, never a one-item Concat.
        # This is handled naturally by the structure (parse_concat returns node if len=1).

        return ast

# --- Public API ---
def parse(pattern: str) -> Any:
    """Parses a regular expression string into an AST node."""
    parser = Parser(pattern)
    return parser.parse()


