class Parser:
    """Parser class to consume a token stream and build the Python data structure."""
    def __init__(self, tokens: List[Token], max_depth: Optional[int] = None, duplicate_keys: str = 'last'):
        self.tokens = tokens
        self.pos = 0
        self.max_depth = max_depth
        self.duplicate_keys = duplicate_keys

    def peek(self) -> Token:
        if self.pos >= len(self.tokens):
            # Return an EOF token representation if we run out of tokens
            return Token('EOF', None, -1, -1)
        return self.tokens[self.pos]

    def advance(self) -> Token:
        token = self.peek()
        self.pos += 1
        return token

    def expect(self, kind: str, expected_value: Any = None) -> Token:
        token = self.peek()
        if token.kind != kind or (expected_value is not None and token.value != expected_value):
            # Error reporting uses the position of the *current* token we are expecting
            raise JSONError(f"Expected {kind}{f' ({expected_value})' if expected_value else ''} but found {token.kind} with value {token.value}", token.line, token.column)
        return self.advance()

    def parse_value(self, current_depth: int) -> Any:
        token = self.peek()

        if token.kind == 'STRING':
            return self.advance().value
        elif token.kind == 'NUMBER':
            return self.advance().value
        elif token.kind == 'TRUE':
            return self.advance().value
        elif token.kind == 'FALSE':
            return self.advance().value
        elif token.kind == 'NULL':
            return self.advance().value
        elif token.kind == '{':
            # Increase depth for object container
            return self.parse_object(current_depth + 1)
        elif token.kind == '[':
            # Increase depth for array container
            return self.parse_array(current_depth + 1)
        else:
            # Text ending where a value or token is still needed
            raise JSONError("Unexpected token encountered while parsing value", token.line, token.column)

    def parse_array(self, current_depth: int) -> List[Any]:
        if self.max_depth is not None and current_depth > self.max_depth:
            raise JSONError("Maximum nesting depth exceeded", self.peek().line, self.peek().column)

        self.expect('[') # Expect '['
        arr = []

        if self.peek().kind == ']':
            self.advance() # Consume ']' for empty array
            return []

        while True:
            # Parse element, passing down the current depth
            value = self.parse_value(current_depth)
            arr.append(value)

            # Check for next token
            next_token = self.peek()
            if next_token.kind == ']':
                self.advance() # Consume ']' 
                return arr
            elif next_token.kind == ',':
                self.advance() # Consume ',' and loop
            else:
                # Missing ',' or ']' (e.g., [1 2] or [1)) 
                raise JSONError("Expected ',' or ']' in array", next_token.line, next_token.column)

    def parse_object(self, current_depth: int) -> dict:
        if self.max_depth is not None and current_depth > self.max_depth:
            raise JSONError("Maximum nesting depth exceeded", self.peek().line, self.peek().column)

        self.expect('{') # Expect '{'
        obj = {}

        if self.peek().kind == '}':
            self.advance() # Consume '}' for empty object
            return {}

        while True:
            # Key must be a string
            key_token = self.expect('STRING')
            key = key_token.value

            # Check for key repetition before parsing value
            if key in obj:
                if self.duplicate_keys == 'first':
                    # Ignore subsequent occurrences
                    pass
                elif self.duplicate_keys == 'last':
                    # Allow overwrite (default behavior)
                    pass
                elif self.duplicate_keys == 'error':
                    # Raise error pointing at the opening quote of the repeated key
                    raise JSONError(f"Duplicate key found: '{key}'", key_token.line, key_token.column)

