from typing import List, Any
from .scanner import tokenize, Token, JSONError

class Parser:
    """Parser class to consume a token stream and build the Python data structure."""
    def __init__(self, tokens: List[Token]):
        self.tokens = tokens
        self.pos = 0

    def peek(self) -> Token:
        if self.pos >= len(self.tokens):
            # Return an EOF token representation if we run out of tokens
            return Token('EOF', None, -1, -1)
        return self.tokens[self.pos]

    def advance(self) -> Token:
        token = self.peek()
        self.pos += 1
        return token

    def expect(self, kind: str, expected_value: Any = None) -> Token:
        token = self.peek()
        if token.kind != kind or (expected_value is not None and token.value != expected_value):
            # Error reporting uses the position of the *current* token we are expecting
            raise JSONError(f"Expected {kind}{f' ({expected_value})' if expected_value else ''} but found {token.kind} with value {token.value}", token.line, token.column)
        return self.advance()

    def parse_value(self) -> Any:
        token = self.peek()

        if token.kind == 'STRING':
            return self.advance().value
        elif token.kind == 'NUMBER':
            return self.advance().value
        elif token.kind == 'TRUE':
            return self.advance().value
        elif token.kind == 'FALSE':
            return self.advance().value
        elif token.kind == 'NULL':
            return self.advance().value
        elif token.kind == '{':
            return self.parse_object()
        elif token.kind == '[':
            return self.parse_array()
        else:
            # Text ending where a value or token is still needed
            raise JSONError("Unexpected token encountered while parsing value", token.line, token.column)

    def parse_array(self) -> List[Any]:
        self.expect('[') # Expect '['
        arr = []

        if self.peek().kind == ']':
            self.advance() # Consume ']' for empty array
            return []

        while True:
            # Parse element
            value = self.parse_value()
            arr.append(value)

            # Check for next token
            next_token = self.peek()
            if next_token.kind == ']':
                self.advance() # Consume ']' 
                return arr
            elif next_token.kind == ',':
                self.advance() # Consume ',' and loop
            else:
                # Missing ',' or ']' (e.g., [1 2] or [1)) 
                raise JSONError("Expected ',' or ']' in array", next_token.line, next_token.column)

    def parse_object(self) -> dict:
        self.expect('{') # Expect '{'
        obj = {}

        if self.peek().kind == '}':
            self.advance() # Consume '}' for empty object
            return {}

        while True:
            # Key must be a string
            key_token = self.expect('STRING')
            key = key_token.value

            # Expect ':' separator
            self.expect(':')

            # Parse value
            value = self.parse_value()

            # Dictionary rule: repeated key keeps its last value
            obj[key] = value

            # Check for next token
            next_token = self.peek()
            if next_token.kind == '}':
                self.advance() # Consume '}'
                return obj
            elif next_token.kind == ',':
                self.advance() # Consume ',' and loop
            else:
                # Missing ',' or '}' (e.g., {"a":1 2} or {"a":1)
                raise JSONError("Expected ',' or '}' in object", next_token.line, next_token.column)


def loads(text: str) -> Any:
    """Parses a JSON string into a Python object."""
    if not text: 
        # Per requirement: empty text ends at line 1, column 1
        raise JSONError("Unexpected end of text", 1, 1)

    tokens = tokenize(text)
    parser = Parser(tokens)

    # Start parsing from the root value
    root_value = parser.parse_value()

    # Check for anything but whitespace after the top-level value
    next_token = parser.peek()
    if next_token.kind != 'EOF':
        # Since the scanner ignores whitespace, anything left before EOF is an error if it's not EOF itself.
        raise JSONError("Unexpected characters after top-level value", next_token.line, next_token.column)

    return root_value
