from typing import List, Any, Optional
from .scanner import tokenize, Token, JSONError

class Parser:
    """Parser class to consume a token stream and build the Python data structure."""
    def __init__(self, tokens: List[Token], max_depth: Optional[int] = None, duplicate_keys: str = 'last'):
        self.tokens = tokens
        self.pos = 0
        self.max_depth = max_depth
        self.duplicate_keys = duplicate_keys

    def peek(self) -> Token:
        if self.pos >= len(self.tokens):
            # Return an EOF token representation if we run out of tokens
            return Token('EOF', None, -1, -1)
        return self.tokens[self.pos]

    def advance(self) -> Token:
        token = self.peek()
        self.pos += 1
        return token

    def expect(self, kind: str, expected_value: Any = None) -> Token:
        token = self.peek()
        if token.kind != kind or (expected_value is not None and token.value != expected_value):
            # Error reporting uses the position of the *current* token we are expecting
            raise JSONError(f"Expected {kind}{f' ({expected_value})' if expected_value else ''} but found {token.kind} with value {token.value}", token.line, token.column)
        return self.advance()

    def parse_value(self, current_depth: int) -> Any:
        token = self.peek()

        if token.kind == 'STRING':
            return self.advance().value
        elif token.kind == 'NUMBER':
            return self.advance().value
        elif token.kind == 'TRUE':
            return self.advance().value
        elif token.kind == 'FALSE':
            return self.advance().value
        elif token.kind == 'NULL':
            return self.advance().value
        elif token.kind == '{':
            # Increase depth for object container
            return self.parse_object(current_depth + 1)
        elif token.kind == '[':
            # Increase depth for array container
            return self.parse_array(current_depth + 1)
        else:
            # Text ending where a value or token is still needed
            raise JSONError("Unexpected token encountered while parsing value", token.line, token.column)

    def parse_array(self, current_depth: int) -> List[Any]:
        if self.max_depth is not None and current_depth > self.max_depth:
            raise JSONError("Maximum nesting depth exceeded", self.peek().line, self.peek().column)

        self.expect('[') # Expect '['
        arr = []

        if self.peek().kind == ']':
            self.advance() # Consume ']' for empty array
            return []

        while True:
            # Parse element, passing down the current depth
            value = self.parse_value(current_depth)
            arr.append(value)

            # Check for next token
            next_token = self.peek()
            if next_token.kind == ']':
                self.advance() # Consume ']' 
                return arr
            elif next_token.kind == ',':
                self.advance() # Consume ',' and loop
            else:
                # Missing ',' or ']' (e.g., [1 2] or [1)) 
                raise JSONError("Expected ',' or ']' in array", next_token.line, next_token.column)

    def parse_object(self, current_depth: int) -> dict:
        if self.max_depth is not None and current_depth > self.max_depth:
            raise JSONError("Maximum nesting depth exceeded", self.peek().line, self.peek().column)

        self.expect('{') # Expect '{'
        obj = {}

        if self.peek().kind == '}':
            self.advance() # Consume '}' for empty object
            return {}

        while True:
            # Key must be a string
            key_token = self.expect('STRING')
            key = key_token.value

            # Check for key repetition before parsing value
            if key in obj:
                if self.duplicate_keys == 'first':
                    # Ignore subsequent occurrences
                    pass
                elif self.duplicate_keys == 'last':
                    # Allow overwrite (default behavior)
                    pass
                elif self.duplicate_keys == 'error':
                    # Raise error pointing at the opening quote of the repeated key
                    raise JSONError(f"Duplicate key found: '{key}'", key_token.line, key_token.column)

            # Expect ':' separator
            self.expect(':')

            # Parse value, passing down the current depth
            value = self.parse_value(current_depth)

            # Dictionary rule: assign value based on policy
            if self.duplicate_keys == 'first' and key in obj:
                # Already set, ignore new value
                pass
            else:
                obj[key] = value

            # Check for next token
            next_token = self.peek()
            if next_token.kind == '}':
                self.advance() # Consume '}'
                return obj
            elif next_token.kind == ',':
                self.advance() # Consume ',' and loop
            else:
                # Missing ',' or '}' (e.g., {"a":1 2} or {"a":1)
                raise JSONError("Expected ',' or '}' in object", next_token.line, next_token.column)


def loads(text: str, *, duplicate_keys: str = 'last', max_depth: Optional[int] = None, allow_nan: bool = False) -> Any:
    """Parses a JSON string into a Python object."""
    if not text: 
        # Per requirement: empty text ends at line 1, column 1
        raise JSONError("Unexpected end of text", 1, 1)

    # Pass allow_nan to tokenize
    tokens = tokenize(text, allow_nan=allow_nan)
    # Initialize parser with all relevant options
    parser = Parser(tokens, max_depth=max_depth, duplicate_keys=duplicate_keys)

    # Determine initial depth based on root token type
    root_token = parser.peek()
    if root_token.kind in ('{', '['):
        # Root object or array starts at depth 1
        root_value = parser.parse_value(1)
    else:
        # Root scalar starts at depth 0
        root_value = parser.parse_value(0)

    # Check for anything but whitespace after the top-level value
    next_token = parser.peek()
    if next_token.kind != 'EOF':
        raise JSONError("Unexpected characters after top-level value", next_token.line, next_token.column)

    return root_value

import sys

# Set recursion limit higher for potentially deeply nested JSON structures
# though cycle detection should prevent infinite recursion.
sys.setrecursionlimit(3000)

class JSONSerializer:
    """Helper class to manage serialization state, including cycle detection."""
    def __init__(self):
        # Stores object references that are currently being serialized
        self.visited = set()

    def serialize(self, obj, indent=None, sort_keys=False, ensure_ascii=False):
        """Main entry point for serialization."""
        try:
            return self._dump(obj, indent, sort_keys, ensure_ascii, self.visited)
        except ValueError as e:
            # Re-raise cycle errors or invalid float errors as required
            raise e

    def _dump(self, obj, indent, sort_keys, ensure_ascii, visited):
        """Recursive serialization logic."""

        # 1. Cycle Detection
        if isinstance(obj, (dict, list, tuple)) and id(obj) in visited:
            raise ValueError("Circular reference detected")
        if isinstance(obj, (dict, list, tuple)):
            visited.add(id(obj))

        # 2. Primitives
        if obj is None:
            return "null"
        if isinstance(obj, bool):
            return "true" if obj else "false"
        if isinstance(obj, int):
            return str(obj)
        if isinstance(obj, float):
            if obj != obj:  # Check for NaN
                raise ValueError("NaN is not representable in this JSON implementation")
            if obj == float('inf') or obj == float('-inf'):
                raise ValueError("Infinity is not representable in this JSON implementation")
            # Finite float
            return repr(obj)

        # 3. Strings
        if isinstance(obj, str):
            return self._dump_string(obj, ensure_ascii)

        # 4. Containers
        if isinstance(obj, list): # Lists are always arrays
            return self._dump_list(obj, indent, sort_keys, ensure_ascii, visited)
        if isinstance(obj, tuple): # Tuples become lists
            return self._dump_list(list(obj), indent, sort_keys, ensure_ascii, visited)
        if isinstance(obj, dict):
            return self._dump_dict(obj, indent, sort_keys, ensure_ascii, visited)

        # 5. Unsupported types
        raise TypeError(f"Object of type {type(obj).__name__} is not JSON serializable")

    def _dump_string(self, s, ensure_ascii):
        """Handles string quoting and escaping."""
        # Escape characters first
        escaped = []
        for char in s:
            cp = ord(char)

            if char == '"':
                escaped.append('\"')
            elif char == '\':
                escaped.append('\\')
            elif char == '
':
                escaped.append('\n')
            elif char == '':
                escaped.append('\r')
            elif char == '	':
                escaped.append('\t')
            elif char == ' ':
                escaped.append('\b')
            elif char == ' ':
                escaped.append('\f')
            elif cp < 0x20 and char not in ('\', '"'): # Control characters U+0000-U+001F
                # If ensure_ascii is True, we must escape everything below U+007F.
                # If ensure_ascii is False, we might write them directly, but the prompt
                # implies control chars inside strings must be escaped if they are raw.
                # Following standard JSON rules and the requirement:
                # "every other character below U+0020 becomes \u00xx"
                if ensure_ascii:
                    escaped.append(f"\\u{cp:04x}")
                else:
                    # Write raw control characters if not forcing ASCII encoding
                    # Note: For strict compliance, even if not ASCII forced, raw control chars might need escaping.
                    # We use unicode escape for safety unless explicit raw writing is desired.
                    escaped.append(f"\\u{cp:04x}") # Stick to 4-digit hex escape for control chars
            elif cp <= 0xFFFF:
                if ensure_ascii and cp > 0x7F:
                    escaped.append(f"\\u{cp:04x}")
                elif cp < 0x80: # ASCII characters
                    escaped.append(char)
                else: # Non-ASCII, not forced ASCII
                    escaped.append(char)
            else: # Surrogate pair handling (Unicode > U+FFFF)
                if ensure_ascii:
                    # Encode as surrogate pair if forcing ASCII output
                    high = 0xD800 + ((cp - 0x10000) >> 10)
                    low = 0xDC00 + ((cp - 0x10000) & 0x3FF)
                    escaped.append(f"\\u{high:04x}")
                    escaped.append(f"\\u{low:04x}")
                else:
                    # Write character directly if not forcing ASCII
                    escaped.append(char)

        return f'"{''.join(escaped)}"'

    def _dump_list(self, obj, indent, sort_keys, ensure_ascii, visited):
        """Serializes a Python list to a JSON array."""
        if not obj:
            return "[]"

        items = []
        for item in obj:
            items.append(self._dump(item, indent, sort_keys, ensure_ascii, visited))

        if indent is None:
            return f"[{','.join(items)}]"

        # Indented output
        body = "\n  ".join(items)
        return f"[
  {body}
]"

    def _dump_dict(self, obj, indent, sort_keys, ensure_ascii, visited):
        """Serializes a Python dictionary to a JSON object."""
        if not obj:
            return "{}"

        if not all(isinstance(k, str) for k in obj):
            raise TypeError("Dictionary keys must be strings")

        if sort_keys: 
            keys = sorted(obj.keys())
        else:
            keys = obj.keys()

        members = []
        for k in keys:
            v = obj[k]
            key_str = self._dump_string(k, ensure_ascii)
            value_str = self._dump(v, indent, sort_keys, ensure_ascii, visited)
            members.append(f"{key_str}: {value_str}")

        if indent is None:
            return f"{{{','.join(members)}}}"

        # Indented output
        body = "\n  ".join(members)
        return f"{{\n  {body}\n}}"


def dumps(obj, *, indent=None, sort_keys=False, ensure_ascii=False):
    """Serializes a Python object to a JSON string."""
    if indent is not None and indent < 0:
        raise ValueError("Indent cannot be negative")

    serializer = JSONSerializer()
    return serializer.serialize(obj, indent, sort_keys, ensure_ascii)

