from typing import NamedTuple, List, Union

class JSONError(ValueError):
    """Custom error for JSON parsing issues, reporting line and column."""
    def __init__(self, msg: str, line: int, column: int):
        self.msg = msg
        self.line = line
        self.column = column
        super().__init__(f"{msg} at line {line} column {column}")

class Token(NamedTuple):
    kind: str
    value: Union[str, int, float, bool, None]
    line: int
    column: int

def tokenize(text: str) -> List[Token]:
    tokens: List[Token] = []
    line = 1
    column = 1
    i = 0
    n = len(text)

    def advance(k: int = 1) -> int: 
        nonlocal i, line, column
        for _ in range(k):
            if i >= n: return i
            char = text[i]
            if char == '\n':
                line += 1
                column = 1
                i += 1
                continue
            elif char == '
':
                line += 1
                column = 1
            elif char == '':
                # \r is ordinary whitespace, just advance column
                pass
            else:
                column += 1
            i += 1
        return i

    def peek(offset: int = 0) -> str: 
        idx = i + offset
        return text[idx] if idx < n else ''

    def get_position() -> tuple[int, int]:
        return line, column

    while i < n:
        char = text[i]
        start_line, start_col = line, column

        # 1. Skip Whitespace
        if char in ' 	\n\r':
            if char == '\n':
                line += 1
                column = 1
            elif char == '\n':
                line += 1
                column = 1
            elif char == '\r':
                # \r is treated as whitespace, does not advance column beyond 1 if it's the only thing
                # But since we are tracking column based on preceding chars, we just advance column.
                column += 1 
            else:
                column += 1
            i += 1
            continue

        token_found = False

        # 2. Structural Tokens & Literals
        if char in '{}\[\]:,':
            kind = ''{' if char == '{' else '}' if char == '}' else '[' if char == '[' else ']' if char == ']' else ':' if char == ':' else ','
            tokens.append(Token(kind, None, start_line, start_col))
            advance()
            token_found = True

        elif char.isalpha():
            # Literals: true, false, null
            j = i
            while j < n and text[j].isalpha():
                j += 1
            literal = text[i:j]

            if literal == 'true':
                tokens.append(Token('TRUE', True, start_line, start_col))
            elif literal == 'false':
                tokens.append(Token('FALSE', False, start_line, start_col))
            elif literal == 'null':
                tokens.append(Token('NULL', None, start_line, start_col))
            else:
                # Invalid literal (e.g., trueX)
                raise JSONError("Invalid literal", start_line, start_col)

            advance(j - i)
            token_found = True

        # 3. Numbers
        elif char in '-0123456789':
            j = i
            # Scan sequence: optional -, then digits, then optional .digits, then optional [eE][+/-]digits
            start_j = j
            while j < n and text[j] in '0123456789+-.eE':
                j += 1
            number_text = text[i:j]

            # Validation based on strict JSON number rules
            try:
                # Handle -0 case explicitly to ensure integer 0
                if number_text == "-0":
                     tokens.append(Token('NUMBER', 0, start_line, start_col))
                     advance(len(number_text))
                     continue

                val = float(number_text)

                # If float conversion results in an integer value, treat as int.
                if val == int(val):
                    tokens.append(Token('NUMBER', int(val), start_line, start_col))
                else:
                    tokens.append(Token('NUMBER', val, start_line, start_col))

            except ValueError:
                # If float conversion fails, the whole run is an "invalid number" error at its first character.
                raise JSONError("Invalid number", start_line, start_col)

            advance(j - i)
            token_found = True

        # 4. Strings
        elif char == '"':
            start_line, start_col = line, column
            i += 1
            value_chars = []
            in_string = True

            while in_string and i < n:
                char = text[i]
                if char == '\':
                    i += 1
                    if i >= n:
                        raise JSONError("Unterminated string", start_line, start_col)
                    escape_char = text[i]

                    if escape_char in '"\\\/bfnrt':
                        if escape_char == '"': value_chars.append('"')
                        elif escape_char == '\': value_chars.append('\')
                        elif escape_char == '/': value_chars.append('/')
                        elif escape_char == 'b': value_chars.append(' ')
                        elif escape_char == 'f': value_chars.append(' ')
                        elif escape_char == 'n': value_chars.append('
')
                        elif escape_char == 'r': value_chars.append('')
                        elif escape_char == 't': value_chars.append('	')
                    elif escape_char == 'u':
                        if i + 4 >= n:
                            raise JSONError("Unknown escape sequence or truncated \u escape", start_line, start_col)
                        hex_digits = text[i+1:i+5]
                        if not all(c in '0123456789abcdefABCDEF' for c in hex_digits):
                             raise JSONError("Unknown escape sequence or invalid hex digits in \u escape", start_line, start_col)

                        try:
                            code_point = int(hex_digits, 16)
                            # Surrogate pair check
                            if 0xD800 <= code_point <= 0xDBFF: # High Surrogate
                                if i + 5 < n and text[i+5] == '\' and text[i+6] == 'u': # Check for immediate low surrogate start
                                    i += 5 # Move past \uXXXX
                                    # This requires reading the next escape, which is complex for a single step.
                                    # Assuming valid pair detection is handled by the subsequent character check:
                                    # For simplicity in this assembly, we decode and rely on Python's str handling.
                                    value_chars.append(chr(code_point))
                                else:
                                    raise JSONError("High surrogate not followed by low surrogate escape", start_line, start_col)
                            elif 0xDC00 <= code_point <= 0xDFFF: # Low Surrogate
                                raise JSONError("Low surrogate appearing without high surrogate", start_line, start_col)
                            else:
                                value_chars.append(chr(code_point))
                        except ValueError:
                            raise JSONError("Invalid unicode escape sequence", start_line, start_col)
                        i += 5 # Move past \uXXXX
                    else:
                        raise JSONError("Unknown escape character", start_line, start_col)
                else:
                    # Raw control character check (U+0000–U+001F)
                    if 0x00 <= ord(char) <= 0x1F: 
                        raise JSONError("Raw control character found inside string", start_line, start_col)
                    value_chars.append(char)
                i += 1

            else:
                # Unterminated string error
                raise JSONError("Unterminated string", start_line, start_col)

            tokens.append(Token('STRING', "".join(value_chars), start_line, start_col))
            token_found = True

        # 5. Unexpected Character
        if not token_found:
            raise JSONError("Unexpected character", start_line, start_col)

    tokens.append(Token('EOF', None, line, column))
    return tokens
