                escaped.append('\"')
            elif char == '\':
                escaped.append('\\')
            elif char == '
':
                escaped.append('\n')
            elif char == '':
                escaped.append('\r')
            elif char == '	':
                escaped.append('\t')
            elif char == ' ':
                escaped.append('\b')
            elif char == ' ':
                escaped.append('\f')
            elif cp < 0x20 and char not in ('\', '"'): # Control characters U+0000-U+001F
                # If ensure_ascii is True, we must escape everything below U+007F.
                # If ensure_ascii is False, we might write them directly, but the prompt
                # implies control chars inside strings must be escaped if they are raw.
                # Following standard JSON rules and the requirement:
                # "every other character below U+0020 becomes \u00xx"
                if ensure_ascii:
