                else:
                    # Write raw control characters if not forcing ASCII encoding
                    # Note: For strict compliance, even if not ASCII forced, raw control chars might need escaping.
                    # We use unicode escape for safety unless explicit raw writing is desired.
                    escaped.append(f"\\u{cp:04x}") # Stick to 4-digit hex escape for control chars
            elif cp <= 0xFFFF:
                if ensure_ascii and cp > 0x7F:
                    escaped.append(f"\\u{cp:04x}")
                elif cp < 0x80: # ASCII characters
                    escaped.append(char)
                else: # Non-ASCII, not forced ASCII
