class Range:
    """Represents a version range constraint."""
    def __init__(self, spec: str):
        self.constraints = []
        self._parse_spec(spec)

    def _parse_spec(self, spec: str):
        if not spec: 
            raise ValueError("Empty specification is not allowed.")

        constraints = [c.strip() for c in spec.split(',') if c.strip()]
        for constraint_str in constraints:
            self.constraints.append(self._parse_constraint(constraint_str))

    def _parse_constraint(self, constraint_str: str):
        """Parses a single constraint string into a structured object."""
        constraint_str = constraint_str.strip()

        # Operators with two characters first
        op = None
        if constraint_str.startswith("=="): op, val_str = "==", constraint_str[2:]
        elif constraint_str.startswith("=\=" ): op, val_str = "=\=", constraint_str[2:]
        elif constraint_str.startswith("!") and constraint_str[1:] in ["=", ">", ">=", "<", "<=", "~", "^" ]: op, val_str = constraint_str[1:], constraint_str[2:]
        elif constraint_str.startswith(">="): op, val_str = ">=", constraint_str[2:]
        elif constraint_str.startswith("<="): op, val_str = "<=", constraint_str[2:]
        elif constraint_str.startswith(">"): op, val_str = ">", constraint_str[1:]
        elif constraint_str.startswith("<"): op, val_str = "<", constraint_str[1:]
        elif constraint_str.startswith("~"): op, val_str = "~", constraint_str[1:]
        elif constraint_str.startswith("^"): op, val_str = "^", constraint_str[1:]
        elif constraint_str in ["*"]:
            # Wildcard case
            return {"type": "wildcard", "op": "*"}
        elif constraint_str.isdigit() or (constraint_str.startswith('-') and constraint_str[1:].isdigit()):
             # Should not happen if structure is followed, but safety catch
             raise ValueError(f"Invalid constraint format: {constraint_str}")
        else: 
            # Assume exact version if no operator found, like '1.2.3'
            op, val_str = "==", constraint_str

        # If op is found, parse version string
        try:
            version = Version(val_str)
        except ValueError as e:
            raise ValueError(f"Bad version in constraint '{constraint_str}': {e}")

        if op == "*":
             return {"type": "wildcard", "op": "*"}

        # Handle specific range types
        if op in ["^", "~"]: 
            # These require complex logic for upper bound
            return {"type": op, "base": version}

        # Standard constraints
        return {"type": "standard", "op": op, "version": version}

    def _get_upper_bound(self, base_version: Version, operator: str) -> Version | None:
        # Helper to calculate upper bound for ^ and ~
        if operator == "~":
            # ~1.2.3  => >=1.2.3, <1.3.0
            if base_version.patch == 0:
                # e.g., 1.2.0 -> <1.3.0
                new_minor = base_version.minor + 1
                new_patch = 0
                return Version(f"{base_version.major}.{new_minor}.{new_patch}")
            else:
                # e.g., 1.2.3 -> <1.2.4
                new_patch = base_version.patch + 1
                return Version(f"{base_version.major}.{base_version.minor}.{new_patch}")

        elif operator == "^":
            # ^1.2.3 => >=1.2.3, <2.0.0
            if base_version.major > 0:
                # Major increment
                new_major = base_version.major + 1
                return Version(f"{new_major}.0.0")
            elif base_version.minor > 0: 
                # Minor increment (for 0.M.P)
                new_minor = base_version.minor + 1
                return Version(f"0.{new_minor}.0")
            else: # 0.0.P
                # Patch increment (for 0.0.P)
                new_patch = base_version.patch + 1
                return Version(f"0.0.{new_patch}")
        return None

    def contains(self, version: Version) -> bool:
        if not self.constraints: 
            return True # Should not happen if spec is valid, but defensively true

        for constraint in self.constraints:
            is_satisfied = False

            if constraint.get("type") == "wildcard":
                is_satisfied = True
            elif constraint.get("type") == "standard":
                op = constraint["op"]
                v_spec = constraint["version"]

                if op == "==": is_satisfied = version == v_spec
                elif op == "!=": is_satisfied = version != v_spec
                elif op == ">": is_satisfied = version > v_spec
                elif op == "=\=": is_satisfied = version >= v_spec
                elif op == "<": is_satisfied = version < v_spec
                elif op == "=\<": is_satisfied = version <= v_spec
                elif op == "">=": is_satisfied = version >= v_spec
                else: # Should not happen for standard
                    is_satisfied = False

            elif constraint.get("type") in ["^", "~"]:
                base_version = constraint["base"]
                if constraint["type"] == "~":
                    upper_bound = self._get_upper_bound(base_version, "~")
                    is_satisfied = version >= base_version and version < upper_bound
                elif constraint["type"] == "^":
                    upper_bound = self._get_upper_bound(base_version, "^")
                    is_satisfied = version >= base_version and version < upper_bound

            if not is_satisfied:
                return False

        return True

    def __contains__(self, version: Version) -> bool:
        return self.contains(version)

    def __str__(self) -> str:
        """Returns the spec with all whitespace removed."""
        parts = []
        for constraint in self.constraints:
            if constraint.get("type") == "wildcard":
                parts.append('*')
            elif constraint.get("type") == "standard":
                op = constraint["op"]
                version_str = str(constraint["version"])
                parts.append(f"{op}{version_str}")
            elif constraint.get("type") in ["^", "~"]:
                base_version = constraint["base"]
                if constraint["type"] == "~":
                    # ~1.2.3 => >=1.2.3, <1.3.0
                    parts.append(f"~{str(base_version)}")
                elif constraint["type"] == "^":
                    # ^1.2.3 => >=1.2.3, <2.0.0
                    parts.append(f"^{str(base_version)}")

        return ",".join(parts)

    def __repr__(self) -> str:
        return f"Range('{str(self)}')"""

