class Version:
    """Represents a software version in MAJOR.MINOR.PATCH format."""
    def __init__(self, text: str):
        if not isinstance(text, str):
            raise TypeError("Version must be initialized with a string.")

        parts = text.split('.')
        if len(parts) != 3:
            raise ValueError(f"Version string must have exactly three parts (M.m.p), got {text}")

        self.major = self._parse_part(parts[0], "major")
        self.minor = self._parse_part(parts[1], "minor")
        self.patch = self._parse_part(parts[2], "patch")

    def _parse_part(self, part_str: str, name: str) -> int:
        """Validates and converts a version part string to an integer."""
        if not part_str.isdigit():
            raise ValueError(f"Version part '{part_str}' for {name} must contain only digits.")

        # Check for leading zeros: '0' is fine, '01' is not.
        if len(part_str) > 1 and part_str.startswith('0'):
            raise ValueError(f"Version part '{part_str}' for {name} cannot have leading zeros.")

        return int(part_str)

    def __hash__(self):
        return hash((self.major, self.minor, self.patch))

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) == \
               (other.major, other.minor, other.patch)

    # Comparison methods for numerical ordering (10.0.0 > 9.0.0)
    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) < \
               (other.major, other.minor, other.patch)

    def __le__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) <= \
               (other.major, other.minor, other.patch)

    def __gt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) > \
               (other.major, other.minor, other.patch)

    def __ge__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) >= \
               (other.major, other.minor, other.patch)

    def __str__(self) -> str:
        """Returns the canonical MAJOR.MINOR.PATCH string."""
        return f"{self.major}.{self.minor}.{self.patch}"

    def __repr__(self) -> str:
        return f"Version('{self.__str__()}')"
