        if 'rooms' not in data or not isinstance(data['rooms'], dict):
            raise WorldError("World data missing or invalid 'rooms' key.")
        if 'items' not in data or not isinstance(data['items'], dict):
            raise WorldError("World data missing or invalid 'items' key.")

        start_id = data['start']
        raw_rooms = data['rooms']
        raw_items_data = data['items']

        # --- 2. Process Items First to establish Item IDs and check for duplicates ---
        items: Dict[str, Item] = {}
        item_ids_seen = set()
        for item_id, item_data in raw_items_data.items():
            if item_id in item_ids_seen:
                # This check is slightly redundant if we assume input dict keys are unique, 
                # but it safeguards against malicious/corrupted input if item_id were not the key.
