                name=item_data['name'],
                description=item_data['description'],
                portable=item_data.get('portable', True)
            )
            items[item_id] = item_obj
            item_ids_seen.add(item_id)

        # --- 3. Process Rooms and Validate ---
        rooms: Dict[str, Room] = {}
        room_item_listings: Dict[str, Tuple[str, ...]] = {}
        all_room_item_listings = []

        for room_id, room_data in raw_rooms.items():
            # Validation: Room must have name and description
            if 'name' not in room_data or 'description' not in room_data:
                raise WorldError(f"Room '{room_id}' lacks 'name' or 'description'.")

            # Validation: Exits
            exits: Dict[str, str] = {} 
            for direction, target_id in room_data.get('exits', {}).items():
                if direction not in DIRECTIONS:
                    raise WorldError(f"Room '{room_id}' uses invalid direction: '{direction}'.")
                # Check if target room exists (will be fully checked after all rooms are parsed, but we can check for existence later)
                exits[direction] = target_id

            # Validation: Items in room
            room_items_list = []
            listed_item_ids = []
            for item_id in room_data.get('items', []):
                # Check if item ID is known
                if item_id not in items:
                    raise WorldError(f"Room '{room_id}' lists unknown item ID: '{item_id}'.")
                # Check for multiple listings in one room
                if item_id in listed_item_ids:
                    raise WorldError(f"Item '{item_id}' is listed more than once in room '{room_id}'.")

                listed_item_ids.append(item_id)
                room_items_list.append(item_id)

            room_item_listings[room_id] = tuple(room_items_list)
            all_room_item_listings.extend(room_items_list)

            # Create Room object (exits dict is mutable in input, but Room is frozen, so we pass the constructed dict)
            rooms[room_id] = Room(
                id=room_id,
                name=room_data['name'],
                description=room_data['description'],
                exits=exits,
                items=tuple(room_items_list)
            )

        # --- 4. Final Consistency Checks ---

        # Check start room existence
        if start_id not in rooms:
            raise WorldError(f"Start room ID '{start_id}' is missing or not a room.")

        # Check exit validity (target rooms must exist)
        for room_id, room_obj in rooms.items():
            for direction, target_id in room_obj.exits.items():
                if target_id not in rooms:
                    raise WorldError(f"Room '{room_id}' exit to '{target_id}' is not a known room.")

        # Check item duplication across the entire world (room + main list, though main list is just definitions)
        # The requirement is: "an item is listed more than once (in one room or across rooms)"
        # If an item is defined in `items`, and listed in a room, it's counted. We just need to ensure no ID appears twice in `all_room_item_listings`.
        if len(all_room_item_listings) != len(set(all_room_item_listings)):
