                 raise WorldError(f"Item IDs {list(duplicates)} appear more than once across rooms.")

        # Note: The spec says "An item that no room lists is allowed; it is simply nowhere." This is covered by defining items separately.

        return cls(
            start=start_id,
            rooms=rooms,
