# Assuming these are available via package import based on the layout provided
from adventure.world import World, DIRECTIONS, Room, Item, WorldError
from adventure.parser import Command, ParseError, parse


class SaveError(ValueError):
    """Raised when game save/load operations fail."""
    pass

@dataclass
class Game:
    world: World
    room: str
    inventory: List[str]
    moves: int
    # Internal state to track items dynamically removed/added from rooms
    _room_contents: Dict[str, List[str]]

    def __post_init__(self):
        # Initialize room contents based on World structure
        self._room_contents = {}
        for room_id, room in self.world.rooms.items():
            # Room.items is a tuple of item ids in order
            self._room_contents[room_id] = list(room.items)

    def items_in(self, room_id: str) -> List[str]:
        """Returns a new list of item IDs currently in that room, in order."""
        if room_id not in self.world.rooms:
            return []

        # Use the dynamically tracked contents
        return list(self._room_contents.get(room_id, []))

    def look(self) -> str:
        """Returns the description of the current room."""
        room = self.world.rooms[self.room]

        # 1. Room Name
        output = [room.name]

        # 2. Description
        output.append(room.description)

        # 3. Exits
        exits_list = []
        for direction in DIRECTIONS:
            if direction in room.exits:
                exits_list.append(direction)

        if exits_list:
            output.append(f"Exits: {', '.join(exits_list)}.")
        else:
            output.append("Exits: none.")

        # 4. Items present
        current_items = self.items_in(self.room)
        if current_items:
            item_names = [self.world.items[item_id].name for item_id in current_items]
            output.append(f"You see: {', '.join(item_names)}.")

        return "\n".join(output)

    def look_item(self, arg: str) -> str:
        """Returns the description of a matching item in the room or inventory."""
        # Search in room first
        room_items = self.items_in(self.room)
        for item_id in room_items:
            item = self.world.items[item_id]
            if item.id.lower() == arg or item.name.lower() == arg:
                return f"{item.description}"

        # Search in inventory
        for item_id in self.inventory:
            item = self.world.items[item_id]
            if item.id.lower() == arg or item.name.lower() == arg:
                return f"{item.description}"

        return "You see no {arg} here."

    def go(self, direction: str) -> str:
        """Handles movement based on direction."""
        room = self.world.rooms[self.room]

        if direction not in room.exits:
            return "You can't go that way."

        new_room_id = room.exits[direction]

        # State update
        self.room = new_room_id
        self.moves += 1

        # Return look text of new room
        return self.look()

    def take(self, item_arg: str) -> str:
        """Handles taking an item."""
        # 1. Check room first
        room_items = self.items_in(self.room)
        matching_item_id = None
        for item_id in room_items:
            item = self.world.items[item_id]
            if item.id.lower() == item_arg or item.name.lower() == item_arg:
                matching_item_id = item_id
                break

        if matching_item_id:
            item = self.world.items[matching_item_id]
            if not item.portable:
                return f"You can't take the {item.name}."
            else:
                # Move item from room to inventory
                # 1. Remove from room contents state
                if matching_item_id in self._room_contents[self.room]:
                    self._room_contents[self.room].remove(matching_item_id)

                # 2. Add to inventory
                self.inventory.append(matching_item_id)
                return f"Taken: {item.name}."

        # 2. Check inventory
        for item_id in self.inventory:
            item = self.world.items[item_id]
            if item.id.lower() == item_arg or item.name.lower() == item_arg:
                return f"You already have the {item.name}."

        # 3. Not found
        return "You see no X here."

    def drop(self, item_arg: str) -> str:
        """Handles dropping an item."""
        # 1. Check inventory
        item_to_drop_id = None
        for item_id in self.inventory:
            item = self.world.items[item_id]
            if item.id.lower() == item_arg or item.name.lower() == item_arg:
                item_to_drop_id = item_id
                break

        if item_to_drop_id:
            item = self.world.items[item_to_drop_id]
            # 1. Remove from inventory
            self.inventory.remove(item_to_drop_id)

            # 2. Add to room contents state (at the end)
            self._room_contents[self.room].append(item_to_drop_id)
            return f"Dropped: {item.name}."

        # 3. Not found in inventory
        return "You aren't carrying that."

    def inventory(self) -> str:
        """Displays player inventory."""
        if not self.inventory:
            return "You are carrying nothing."

        item_names = [self.world.items[item_id].name for item_id in self.inventory]
        return f"You are carrying: {', '.join(item_names)}."

    def do(self, line: str) -> str:
        """Runs one command and returns the response text. Never raises for any input."""
        try:
            command: Command = parse(line)
        except ParseError as e:
            return str(e)

        verb = command.verb
        arg = command.arg

        if verb == 'go' and arg:
            return self.go(arg)

        elif verb == 'go' and not arg:
            return "Go where?"

        elif verb == 'look':
            if arg is None:
                return self.look()
            else:
                return self.look_item(arg)

        elif verb == 'inventory':
            # Handle aliases 'inv', 'i'
            return self.inventory()

        elif verb == 'take' and arg:
            return self.take(arg)

        elif verb == 'drop' and arg:
            return self.drop(arg)

        else:
            # This handles cases like 'take' with no argument, or invalid verbs/args not caught by ParseError
            return "I don't understand that."

