        """Returns a new list of item IDs currently in that room, in order, excluding items in inventory."""
        if room_id not in self.world.rooms:
            return []

        room = self.world.rooms[room_id]
        # Start with the static list of items defined for this room in the world
        initial_items = list(room.items)

        # Filter out any items currently in the player's inventory
        current_in_room = [item_id for item_id in initial_items if item_id not in self.inventory]
        return current_in_room

    def look(self) -> str:
        """Returns the description of the current room."""
        room = self.world.rooms[self.room]

        # 1. Room Name
        output = [room.name]

        # 2. Description
        output.append(room.description)

        # 3. Exits
        exits_list = []
        for direction in DIRECTIONS:
