from dataclasses import dataclass, field
from typing import Dict, Tuple, FrozenSet

DIRECTIONS: Tuple[str, ...] = ('north', 'south', 'east', 'west', 'up', 'down')

class WorldError(ValueError):
    """Error raised when loading a world from dictionary data."""
    pass

@dataclass(frozen=True)
class Item:
    id: str
    name: str
    description: str
    portable: bool = True

@dataclass(frozen=True)
class Room:
    id: str
    name: str
    description: str
    exits: Dict[str, str] = field(default_factory=dict)
    items: Tuple[str, ...] = field(default_factory=tuple)

@dataclass(frozen=True)
class World:
    start: str
    rooms: Dict[str, Room]
    items: Dict[str, Item]

    @classmethod
    def from_dict(cls, data: Dict) -> 'World':
        # 1. Check for required top-level keys
        if 'start' not in data:
            raise WorldError("World data missing 'start' key.")
        if 'rooms' not in data or not isinstance(data['rooms'], dict):
            raise WorldError("World data missing or invalid 'rooms' key.")
        if 'items' not in data or not isinstance(data['items'], dict):
            raise WorldError("World data missing or invalid 'items' key.")

        start_id = data['start']
        raw_rooms = data['rooms']
        raw_items_data = data['items']

        # --- 2. Process Items First to establish Item IDs and check for duplicates ---
        items: Dict[str, Item] = {}
        item_ids_seen = set()
        for item_id, item_data in raw_items_data.items():
            if item_id in item_ids_seen:
                # This check is slightly redundant if we assume input dict keys are unique, 
                # but it safeguards against malicious/corrupted input if item_id were not the key.
                # Given the requirement: "an item is listed more than once (in one room or across rooms)"
                # We will primarily check cross-room listing later, but ensure item definition itself is clean.
                pass

            if 'name' not in item_data or 'description' not in item_data:
                raise WorldError(f"Item '{item_id}' is missing 'name' or 'description'.")

            item_obj = Item(
                id=item_id,
                name=item_data['name'],
                description=item_data['description'],
                portable=item_data.get('portable', True)
            )
            items[item_id] = item_obj
            item_ids_seen.add(item_id)

        # --- 3. Process Rooms and Validate ---
        rooms: Dict[str, Room] = {}
        room_item_listings: Dict[str, Tuple[str, ...]] = {}
        all_room_item_listings = []

        for room_id, room_data in raw_rooms.items():
            # Validation: Room must have name and description
            if 'name' not in room_data or 'description' not in room_data:
