            if direction in room.exits:
                exits_list.append(direction)

        if exits_list:
            output.append(f"Exits: {', '.join(exits_list)}.")
        else:
            output.append("Exits: none.")

        # 4. Items present
        current_items = self.items_in(self.room)
        if current_items:
            item_names = [self.world.items[item_id].name for item_id in current_items]
            output.append(f"You see: {', '.join(item_names)}.")

        return "\n".join(output)

    def look_item(self, arg: str) -> str:
        """Returns the description of a matching item in the room or inventory."""
        # Search in room first
        room_items = self.items_in(self.room)
        for item_id in room_items:
            item = self.world.items[item_id]
            if item.id.lower() == arg or item.name.lower() == arg:
                return f"{item.description}"

        # Search in inventory
        for item_id in self.inventory:
            item = self.world.items[item_id]
            if item.id.lower() == arg or item.name.lower() == arg:
                return f"{item.description}"

        return f"You see no {arg} here."

    def go(self, direction: str) -> str:
        """Handles movement based on direction."""
        room = self.world.rooms[self.room]

        if direction not in room.exits:
            return "You can't go that way."

        new_room_id = room.exits[direction]

        # State update
        self.room = new_room_id
        self.moves += 1

        # Return look text of new room
        return self.look()

    def take(self, item_arg: str) -> str:
        """Handles taking an item."""
        # 1. Check room first
        room_items = self.items_in(self.room)
        matching_item_id = None
        for item_id in room_items:
            item = self.world.items[item_id]
            if item.id.lower() == item_arg or item.name.lower() == item_arg:
                matching_item_id = item_id
                break

        if matching_item_id:
            item = self.world.items[matching_item_id]
            if not item.portable:
                return f"You can't take the {item.name}."
            else:
                # Item is in room and portable: move to inventory
                self.inventory.append(matching_item_id)
                return f"Taken: {item.name}."

        # 2. Check inventory
        for item_id in self.inventory:
            item = self.world.items[item_id]
            if item.id.lower() == item_arg or item.name.lower() == item_arg:
                return f"You already have the {item.name}."

        # 3. Not found
        return f"You see no {item_arg} here."

    def drop(self, item_arg: str) -> str:
        """Handles dropping an item from inventory into the current room."""
        try:
            # Find matching item ID in inventory
            item_id_to_drop = None
            for item_id in self.inventory:
                item = self.world.items[item_id]
                if item.id.lower() == item_arg or item.name.lower() == item_arg:
                    item_id_to_drop = item_id
                    break

            if item_id_to_drop:
                # Move from inventory to room
                self.inventory.remove(item_id_to_drop)
                # Note: We don't modify World, so we rely on items_in() to show it
                return f"Dropped: {self.world.items[item_id_to_drop].name}."
            else:
                return "You aren't carrying that."
        except KeyError:
            # Should not happen if inventory only contains valid IDs, but handles robustness
            return "An error occurred while checking inventory."

    def inventory(self) -> str:
        """Returns the inventory contents."""
        if not self.inventory:
            return "You are carrying nothing."

        item_names = [self.world.items[item_id].name for item_id in self.inventory]
        return f"You are carrying: {', '.join(item_names)}."

    def save(self) -> str:
        """Serializes the game state to a JSON string."""

        # Calculate the current effective list of items in every room
        current_room_items: Dict[str, List[str]] = {}
        for room_id in self.world.rooms:
            # We must capture the list in order
            current_room_items[room_id] = self.items_in(room_id)

        save_data = {
            "version": 1,
            "room": self.room,
            "inventory": self.inventory, # List of item IDs
            "items": current_room_items, # Dict of {room_id: [item_ids]} in order
            "moves": self.moves
        }
        return json.dumps(save_data)

    @classmethod
    def load(cls, world: World, text: str) -> 'Game':
        """Loads a game state from a JSON string."""
        try:
            data = json.loads(text)
        except json.JSONDecodeError:
            raise SaveError("Not valid JSON.")

        # Validation 1: Check structure and version
        required_keys = ["version", "room", "inventory", "items", "moves"]
        if not all(key in data for key in required_keys):
            raise SaveError("Save data is missing required keys.")
        if data.get("version") != 1:
            raise SaveError("Unsupported save version.")

        saved_room_id = data["room"]
        saved_inventory_ids = data["inventory"]
        saved_room_items: Dict[str, List[str]] = data["items"]
        saved_moves = data["moves"]

        # Validation 2: Check room and item existence
        if saved_room_id not in world.rooms:
            raise SaveError(f"Saved room '{saved_room_id}' does not exist in the world.")

        all_tracked_ids = set(saved_inventory_ids)
        all_room_items_tracker = set()

        for room_id, item_list in saved_room_items.items():
            if room_id not in world.rooms:
                raise SaveError(f"Saved room key '{room_id}' does not exist in the world.")
            for item_id in item_list:
                if item_id not in world.items: # Item ID must exist in the world definition
                    raise SaveError(f"Item ID '{item_id}' found in room data does not exist in the world items.")
                if item_id in all_tracked_ids: # Check for cross-state duplication
                    raise SaveError(f"Item ID '{item_id}' appears in both inventory and a room.")
                all_room_items_tracker.add(item_id)

        # Final check: Inventory items must exist in the world
        for item_id in saved_inventory_ids:
            if item_id not in world.items:
                raise SaveError(f"Item ID '{item_id}' in inventory does not exist in the world items.")

        # Validation 3: Moves
        if not isinstance(saved_moves, int) or saved_moves < 0:
            raise SaveError("Moves count is invalid.")

        # Construct the new game instance
        new_game = cls(world=world, room=saved_room_id, inventory=saved_inventory_ids, moves=saved_moves)

        # Crucial step: For the loaded game, items_in() must correctly reflect the loaded state.
        # Since the static Room.items tuple holds ALL items for that room, and we loaded the precise list of items that SHOULD be there
        # (i.e., those not in inventory), we rely on the fact that our modified items_in() handles this filtering correctly.
        # We don't need complex manual state overriding if items_in() is robust.

        return new_game

