# --- CLF Parser Implementation ---

# Regex for CLF: client, ident, user, [time], "method path protocol" status size [latency]
# Time format: DD/Mon/YYYY:HH:MM:SS ±HHMM
# The latency is optional, and if present, it's in microseconds.
clf_regex = re.compile(r"(\S+) \S+ \S+ \[([^\]]+)\] ""([A-Z]+) (.*?) HTTP/[0-9]\.[0-9]" ([0-9]+) (\S+)(?: ([0-9]+))?")

def parse_clf(line: str) -> Tuple[Optional[Record], Optional[ParseError]]:
    """Parses a single line in Apache Common Log Format."""
    match = clf_regex.match(line.strip())
    if not match:
        return None, ParseError(f"Line does not match CLF format: {line.strip()}")

    (client, time_str, method, path, status_str, size_str, latency_str) = match.groups()

    # 1. Time Parsing
    try:
        # Format: DD/Mon/YYYY:HH:MM:SS ±HHMM
        # We use strptime and then manually adjust timezone if the offset is present.
        dt_obj = datetime.strptime(time_str, "%d/%b/%Y:%H:%M:%S %z")
    except ValueError:
        return None, ParseError(f"Invalid time format in CLF line: {time_str}")

    # Ensure time is timezone-aware and converted to UTC
    time_utc = dt_obj.astimezone(timezone.utc)

    # 2. Client
    if not client: # Should not happen with regex, but good practice
        return None, ParseError("Missing client in CLF line")

    # 3. Method
    if not method or not method.isalpha():
        return None, ParseError("Invalid or empty HTTP method in CLF line")
    method_upper = method.upper()

    # 4. Path Normalization
    # Path is captured up to the protocol, we must clean it.
    # The regex captured everything after the method until HTTP/X.Y
    raw_path = path.strip()
    if not raw_path.startswith('/'):
        return None, ParseError("Path must start with '/' in CLF line")

    # Remove query/fragment and collapse slashes
    path_no_query = raw_path.split('?')[0].split('#')[0]
    normalized_path = re.sub(r'/+', '/', path_no_query)

    # 5. Status
    try:
        status = int(status_str)
        if not (100 <= status <= 599):
            return None, ParseError(f"Status code {status} out of range (100-599).")
    except ValueError:
        return None, ParseError(f"Invalid status code: {status_str}")

    # 6. Size
    try:
        if size_str == '-' or size_str is None:
            size = 0
        else:
            size = int(size_str)
        if size < 0:
             return None, ParseError("Size cannot be negative.")
    except ValueError:
        return None, ParseError(f"Invalid size value: {size_str}")

    # 7. Latency
    latency_ms: Optional[float] = None
    if latency_str and latency_str.isdigit():
        try:
            # Latency is in whole microseconds, convert to ms
            latency_us = int(latency_str)
            latency_ms = latency_us / 1000.0
            if latency_ms < 0: # Should not happen if it's digits
                 return None, ParseError("Latency cannot be negative.")
        except ValueError:
            # Should be caught by isdigit, but for safety
            pass

    record = Record(
        time=time_utc,
        client=client,
        method=method_upper,
        path=normalized_path,
        status=status,
        size=size,
        latency_ms=latency_ms
    )

    return record, None

