    except json.JSONDecodeError:
        return None, ParseError(f"Invalid JSON format: {line.strip()}")

    required_keys = ['ts', 'client', 'method', 'path', 'status']
    for key in required_keys:
        if key not in data or data[key] is None:
            return None, ParseError(f"Missing required key: '{key}' in JSON object.")

    # 1. Time Parsing (ISO 8601 with offset or Z)
    ts_str = data['ts']
    try:
        if ts_str.endswith('Z'):
            # Handle 'Z' suffix (Zulu time / UTC)
            time_utc = datetime.fromisoformat(ts_str.replace('Z', '+00:00'))
        else:
            # Use fromisoformat which handles various offsets
            time_utc = datetime.fromisoformat(ts_str)

        # Ensure it's timezone-aware and convert to UTC
        if time_utc.tzinfo is None or time_utc.tzinfo.utcoffset(time_utc) is None:
            return None, ParseError("Time 'ts' must include a timezone offset.")

        time_utc = time_utc.astimezone(timezone.utc)

    except ValueError:
        return None, ParseError(f"Invalid ISO 8601 timestamp format: {ts_str}")

    # 2. Client
    client = str(data['client'])
    if not client:
        return None, ParseError("Client string cannot be empty.")

    # 3. Method
    method = str(data['method'])
    if not method or not method.isalpha():
        return None, ParseError("Method must be a non-empty string of ASCII letters.")
    method_upper = method.upper()

    # 4. Path Normalization
    path = str(data['path'])
    if not path.startswith('/'):
