import re
from datetime import datetime, timezone
from typing import Tuple, Any, Optional
from dataclasses import dataclass
import json

# Assuming ParseError and Record are defined elsewhere in parsers.py
class ParseError(ValueError):
    pass

@dataclass(frozen=True)
class Record:
    time: datetime
    client: str
    method: str
    path: str
    status: int
    size: int
    latency_ms: Optional[float]

# --- CLF Parser Implementation ---

# Regex for CLF: client, ident, user, [time], "method path protocol" status size [latency]
# Time format: DD/Mon/YYYY:HH:MM:SS ±HHMM
# The latency is optional, and if present, it's in microseconds.
clf_regex = re.compile(r"(\S+) \S+ \S+ \[([^\]]+)\] ""([A-Z]+) (.*?) HTTP/[0-9]\.[0-9]" ([0-9]+) (\S+)(?: ([0-9]+))?")

def parse_clf(line: str) -> Tuple[Optional[Record], Optional[ParseError]]:
    """Parses a single line in Apache Common Log Format."""
    match = clf_regex.match(line.strip())
    if not match:
        return None, ParseError(f"Line does not match CLF format: {line.strip()}")

    (client, time_str, method, path, status_str, size_str, latency_str) = match.groups()

    # 1. Time Parsing
    try:
        # Format: DD/Mon/YYYY:HH:MM:SS ±HHMM
        # We use strptime and then manually adjust timezone if the offset is present.
        dt_obj = datetime.strptime(time_str, "%d/%b/%Y:%H:%M:%S %z")
    except ValueError:
        return None, ParseError(f"Invalid time format in CLF line: {time_str}")

    # Ensure time is timezone-aware and converted to UTC
    time_utc = dt_obj.astimezone(timezone.utc)

    # 2. Client
    if not client: # Should not happen with regex, but good practice
        return None, ParseError("Missing client in CLF line")

    # 3. Method
    if not method or not method.isalpha():
        return None, ParseError("Invalid or empty HTTP method in CLF line")
    method_upper = method.upper()

    # 4. Path Normalization
    # Path is captured up to the protocol, we must clean it.
    # The regex captured everything after the method until HTTP/X.Y
    raw_path = path.strip()
    if not raw_path.startswith('/'):
        return None, ParseError("Path must start with '/' in CLF line")

    # Remove query/fragment and collapse slashes
    path_no_query = raw_path.split('?')[0].split('#')[0]
    normalized_path = re.sub(r'/+', '/', path_no_query)

    # 5. Status
    try:
        status = int(status_str)
        if not (100 <= status <= 599):
            return None, ParseError(f"Status code {status} out of range (100-599).")
    except ValueError:
        return None, ParseError(f"Invalid status code: {status_str}")

    # 6. Size
    try:
        if size_str == '-' or size_str is None:
            size = 0
        else:
            size = int(size_str)
        if size < 0:
             return None, ParseError("Size cannot be negative.")
    except ValueError:
        return None, ParseError(f"Invalid size value: {size_str}")

    # 7. Latency
    latency_ms: Optional[float] = None
    if latency_str and latency_str.isdigit():
        try:
            # Latency is in whole microseconds, convert to ms
            latency_us = int(latency_str)
            latency_ms = latency_us / 1000.0
            if latency_ms < 0: # Should not happen if it's digits
                 return None, ParseError("Latency cannot be negative.")
        except ValueError:
            # Should be caught by isdigit, but for safety
            pass

    record = Record(
        time=time_utc,
        client=client,
        method=method_upper,
        path=normalized_path,
        status=status,
        size=size,
        latency_ms=latency_ms
    )

    return record, None

# --- JSONL Parser Implementation ---

def parse_jsonl(line: str) -> Tuple[Optional[Record], Optional[ParseError]]:
    """Parses a single line in JSON Lines format."""
    try:
        data: dict[str, Any] = json.loads(line)
    except json.JSONDecodeError:
        return None, ParseError(f"Invalid JSON format: {line.strip()}")

    required_keys = ['ts', 'client', 'method', 'path', 'status']
    for key in required_keys:
        if key not in data or data[key] is None:
            return None, ParseError(f"Missing required key: '{key}' in JSON object.")

    # 1. Time Parsing (ISO 8601 with offset or Z)
    ts_str = data['ts']
    try:
        if ts_str.endswith('Z'):
            # Handle 'Z' suffix (Zulu time / UTC)
            time_utc = datetime.fromisoformat(ts_str.replace('Z', '+00:00'))
        else:
            # Use fromisoformat which handles various offsets
            time_utc = datetime.fromisoformat(ts_str)

        # Ensure it's timezone-aware and convert to UTC
        if time_utc.tzinfo is None or time_utc.tzinfo.utcoffset(time_utc) is None:
            return None, ParseError("Time 'ts' must include a timezone offset.")

        time_utc = time_utc.astimezone(timezone.utc)

    except ValueError:
        return None, ParseError(f"Invalid ISO 8601 timestamp format: {ts_str}")

    # 2. Client
    client = str(data['client'])
    if not client:
        return None, ParseError("Client string cannot be empty.")

    # 3. Method
    method = str(data['method'])
    if not method or not method.isalpha():
        return None, ParseError("Method must be a non-empty string of ASCII letters.")
    method_upper = method.upper()

    # 4. Path Normalization
    path = str(data['path'])
    if not path.startswith('/'):
        return None, ParseError("Path must start with '/' in JSON line.")

    # Remove query/fragment and collapse slashes
    path_no_query = path.split('?')[0].split('#')[0]
    normalized_path = re.sub(r'/+', '/', path_no_query)

    # 5. Status
    try:
        status = int(data['status'])
        if not (100 <= status <= 599):
            return None, ParseError(f"Status code {status} out of range (100-599).")
    except (ValueError, TypeError):
        return None, ParseError(f"Invalid status code: {data['status']}")

    # 6. Size
    size: int = 0
    if 'bytes' in data:
        try:
            size = int(data['bytes'])
            if size < 0: # Should not happen with standard logs but good check
                 return None, ParseError("Size cannot be negative.")
        except (ValueError, TypeError):
            # Ignore if bytes is present but non-numeric, treat as 0
            pass

    # 7. Latency
    latency_ms: Optional[float] = None
    if 'latency_ms' in data and data['latency_ms'] is not None:
        try:
            latency_ms = float(data['latency_ms'])
            if latency_ms < 0: # Should not happen
                 return None, ParseError("Latency cannot be negative.")
        except (ValueError, TypeError):
            return None, ParseError(f"Invalid latency_ms value: {data['latency_ms']}")

    record = Record(
        time=time_utc,
        client=client,
        method=method_upper,
        path=normalized_path,
        status=status,
        size=size,
        latency_ms=latency_ms
    )

    return record, None

from vfs.paths import normalize

class FSError(Exception):
    """Base class for FileSystem errors. str(error) must return a normalized absolute path."""
    def __init__(self, path: str):
        self.path = path
        super().__init__(str(self))

    def __str__(self) -> str:
        # Ensure the path provided to the error is normalized
        return normalize(self.path)

class NotFound(FSError):
    """Raised when a file or directory is not found."""
    pass

class AlreadyExists(FSError):
    """Raised when attempting to create something that already exists."""
    pass

class NotADirectory(FSError):
    """Raised when an operation passes through an existing file path."""
    pass

class IsADirectory(FSError):
    """Raised when treating a directory as a file or attempting operations on it inappropriately."""
    pass

class InvalidOperation(FSError):
    """Raised when an operation is invalid for the path (e.g., trying to rm / or its ancestors)."""
    pass

