from dataclasses import dataclass, field
from typing import Any
import random

@dataclass(frozen=True)
class RetryPolicy:
    max_attempts: int
    base: float
    factor: float
    max_delay: float
    jitter: float

    def __post_init__(self):
        if not (self.max_attempts >= 1):
            raise ValueError("max_attempts must be >= 1")
        if not (self.base > 0):
            raise ValueError("base must be > 0")
        if not (self.factor >= 1):
            raise ValueError("factor must be >= 1")
        if not (self.max_delay >= self.base):
            raise ValueError("max_delay must be >= base")
        if not (0 <= self.jitter < 1):
            raise ValueError("jitter must be in range [0, 1)")

    def backoff(self, attempt: int) -> float:
        if attempt < 1:
            raise ValueError("attempt must be >= 1")
        return min(self.max_delay, self.base * (self.factor ** (attempt - 1)))

    def delay(self, attempt: int, rng: random.Random) -> float:
        backoff_val = self.backoff(attempt)
        # u = rng.random() is called exactly once
        u = rng.random()
        return backoff_val * (1 - self.jitter + 2 * self.jitter * u)

    def should_retry(self, attempt: int) -> bool:
        return attempt < self.max_attempts

class PermanentError(Exception):
    """Raised by a handler that should never be retried."""
    pass

