# jobs/queue.py
from dataclasses import dataclass, field
from typing import Callable, Dict, Any, List, Optional

# Assuming Job is defined elsewhere (e.g., in this file or imported from jobs/queue.py itself if it's self-contained)
@dataclass(frozen=True)
class Job:
    id: str
    payload: Any
    status: str  # 'pending', 'running', 'done' or 'dead'
    attempts: int = 0
    available_at: float = 0.0
    last_error: Optional[str] = None

class JobQueue:
    def __init__(self, clock: Callable[[], float]):
        self.clock = clock
        # Stores all jobs, keyed by job_id
        self._jobs: Dict[str, Job] = {}
        # Tracks submission order for tie-breaking in claim()
        self._submission_order: List[str] = []
        # Stores dead jobs in order they died
        self._dead_letters: List[Job] = []

    def submit(self, job_id: str, payload: Any, delay: float = 0.0) -> Job:
        current_time = self.clock()
        if job_id in self._jobs: 
            raise ValueError(f"Job ID {job_id} already exists.")
        if delay < 0.0:
            raise ValueError("Delay cannot be negative.")

        available_at = current_time + delay
        new_job = Job(id=job_id, payload=payload, status='pending', attempts=0, available_at=available_at)

        self._jobs[job_id] = new_job
        self._submission_order.append(job_id)
        return new_job

    def claim(self) -> Optional[Job]:
        current_time = self.clock()
        earliest_job_id: Optional[str] = None
        min_available_at = float('inf')

        # Iterate through submission order to respect tie-breaking
        for job_id in self._submission_order:
            job = self._jobs[job_id]

            if job.status == 'pending' and job.available_at <= current_time:
                # Check if this job is earlier or at the same time as the current best candidate
                if job.available_at < min_available_at:
                    min_available_at = job.available_at
                    earliest_job_id = job_id
                elif job.available_at == min_available_at and earliest_job_id is None: # Initial candidate or tie breaker logic refinement
                    earliest_job_id = job_id

        if earliest_job_id is None:
            return None

        job_to_claim = self._jobs[earliest_job_id]

        # Update job state: Running, increment attempts
        new_attempts = job_to_claim.attempts + 1
        new_job = job_to_claim.copy(status='running', attempts=new_attempts)
        self._jobs[earliest_job_id] = new_job

        return new_job

    def complete(self, job_id: str):
        if job_id not in self._jobs:
            raise KeyError(f"Job ID {job_id} not found.")
        job = self._jobs[job_id]
        if job.status != 'running':
            raise ValueError(f"Job {job_id} is not running (status: {job.status}).")

        # Update job state: Done
        new_job = job.copy(status='done')
        self._jobs[job_id] = new_job

    def retry(self, job_id: str, error: str, at: float):
        if job_id not in self._jobs:
            raise KeyError(f"Job ID {job_id} not found.")
        job = self._jobs[job_id]
        if job.status != 'running':
            raise ValueError(f"Job {job_id} is not running (status: {job.status}).")

        # Update job state: Pending, new availability time, error recorded
        new_job = job.copy(status='pending', available_at=at, last_error=error)
        self._jobs[job_id] = new_job

    def bury(self, job_id: str, error: str):
        if job_id not in self._jobs:
            raise KeyError(f"Job ID {job_id} not found.")
        job = self._jobs[job_id]
        if job.status != 'running':
            raise ValueError(f"Job {job_id} is not running (status: {job.status}).")

        # Update job state: Dead, add to dead letters
        new_job = job.copy(status='dead', last_error=error)
        self._jobs[job_id] = new_job
        self._dead_letters.append(new_job)

    def get(self, job_id: str) -> Job:
        if job_id not in self._jobs:
            raise KeyError(f"Job ID {job_id} not found.")
        return self._jobs[job_id].copy() # Return a copy to prevent external modification

    def dead_letters(self) -> List[Job]:
        # Return a copy of the list
        return self._dead_letters.copy()

    def counts(self) -> Dict[str, int]:
        counts = {'pending': 0, 'running': 0, 'done': 0, 'dead': 0}
        for job in self._jobs.values():
            counts[job.status] = counts.get(job.status, 0) + 1
        return counts

    def next_available(self) -> Optional[float]:
        current_time = self.clock()
        min_time = float('inf')
        found = False

        for job in self._jobs.values():
            if job.status == 'pending' and job.available_at > current_time:
                if job.available_at < min_time:
                    min_time = job.available_at
                    found = True

        return min_time if found else None

