            # If for some reason a number slipped through here as a word token, push it.
            self._push(int(word), token)
            return

        # Arithmetic
        if word in ('+', '-', '*', '//', '%'):
            b = self._pop(token)
            a = self._pop(token)
            self.steps_taken += 2 # Two pops
            result = 0
            if word == '+': result = a + b
            elif word == '-': result = a - b
            elif word == '*': result = a * b
            elif word == '//':
                if b == 0: raise DivisionByZero("Division by zero", word, token.line, token.col)
                result = a // b  # Python's floor semantics
            elif word == '%':
                if b == 0: raise DivisionByZero("Modulo by zero", word, token.line, token.col)
                result = a % b
            self._push(result, token)
            self.steps_taken += 1 # One push

        # Unary Operations
        elif word == 'negate':
            a = self._pop(token)
            result = -a
            self._push(result, token)

        elif word == 'abs':
            a = self._pop(token)
            result = abs(a)
            self._push(result, token)

        # Stack Manipulation
        elif word == 'dup':
            a = self._pop(token)
            self._push(a, token) # Original item
            self._push(a, token) # Duplicate
            self.steps_taken += 2

        elif word == 'drop':
            self._pop(token) # Pops and discards
            self.steps_taken += 1

        elif word == 'swap':
            b = self._pop(token)
            a = self._pop(token)
            self._push(b, token)
            self._push(a, token)
            self.steps_taken += 2

        elif word == 'over':
            # ( a b -- a b a )
            c = self._pop(token)
            self._push(c, token)
            self._push(c, token)
            self.steps_taken += 2

        elif word == 'rot':
            # ( a b c -- b c a )
            c = self._pop(token)
            b = self._pop(token)
            self._push(c, token)
            self._push(b, token)
            self._push(c, token)
            self.steps_taken += 3

        # Comparison/Logical
        elif word in ('=', '<>', '<', '>'):
            b = self._pop(token)
            a = self._pop(token)
            self.steps_taken += 2
            result = False
            if word == '=': result = (a == b)
            elif word == '<>': result = (a != b)
            elif word == '<': result = (a < b)
            elif word == '>': result = (a > b)
            # Flag: -1 for true, 0 for false
            self._push(-1 if result else 0, token)
            self.steps_taken += 1

        elif word == '0=':
            a = self._pop(token)
            self.steps_taken += 1
            # Flag: -1 for true, 0 for false
            self._push(-1 if a == 0 else 0, token)

        elif word == 'and':
            b = self._pop(token)
            a = self._pop(token)
            self.steps_taken += 2
            result = a & b
            self._push(result, token)
            self.steps_taken += 1

        elif word == 'or':
            b = self._pop(token)
            a = self._pop(token)
            self.steps_taken += 2
            result = a | b
            self._push(result, token)
            self.steps_taken += 1

        # State/Output
        elif word == 'depth':
            # ( -- n )
            self.steps_taken += 1
            self._push(len(self.stack), token)

        elif word == '.':
            # ( a -- )
            a = self._pop(token)
            self.output.append(a)
            self.steps_taken += 1

    def _execute_if(self, token):
        # 'if A then' or 'if A else B then'
        # A is evaluated first (this is one step, accounted for by _evaluate_word call)
        # Then we check the result.

        condition_token = self._peek_token() # The token right after 'if'
