                # Check step limit BEFORE processing the token
                self._check_step_limit(token)

                # --- Control Flow Parsing / Pre-Checks (Only for non-execution tokens) ---
                if word == 'if':
                    # 1. Check for 'else' presence
                    has_else = False
                    try:
                        # Look ahead for 'else' before the corresponding 'then'
                        temp_idx = token_index + 1
                        while temp_idx < len(tokens):
                            t_val = tokens[temp_idx].value
                            if t_val == 'else':
                                has_else = True
                                break
                            if t_val == 'then':
                                break
                            temp_idx += 1
                    except IndexError:
                        pass

                    # 2. Record the start of the 'if' structure
                    # We tentatively set the else jump target to -1 (None) if not found yet.
                    # A proper compiler would scan ahead to find the correct else/then pair.
                    # For this interpreter, we rely on the structure being correct, and the execution will check.
                    control_stack.append(('if', token_index, -1 if not has_else else None))
                    token_index += 1
                    continue

                elif word == 'begin':
                    # Record start of 'begin' loop
                    control_stack.append(('begin', token_index, None))
                    token_index += 1
                    continue

                elif word == 'until':
                    # Until must follow a begin. Check stack.
                    if not control_stack or control_stack[-1][0] != 'begin':
                        raise ControlError("until without preceding begin", word, token.line, token.col)

                    # Set loop continuation point: the token immediately following 'until'
                    loop_start_index = token_index + 1
                    # Record the 'until' token index as the loop control point
                    control_stack[-1] = ('begin', control_stack[-1][1], loop_start_index)
                    token_index += 1
                    continue

                elif word == 'then':
                    if not control_stack or control_stack[-1][0] != 'if':
                        raise ControlError("then without preceding if", word, token.line, token.col)

                    # The token *after* 'then' is the start of the true branch.
                    # We don't need an explicit jump here, execution just continues.
                    token_index += 1
                    continue

                elif word == 'else':
                    if not control_stack or control_stack[-1][0] != 'if':
                        raise ControlError("else without preceding if", word, token.line, token.col)

                    # Find the 'if' frame and set the jump target to the token *after* 'else'
                    if_type, start_idx, _ = control_stack[-1]
                    if if_type == 'if':
                        # Set the jump target for the false branch
                        control_stack[-1] = (if_type, start_idx, token_index + 1)
                        token_index += 1
                        continue

                # --- Execution Phase (Words/Literals) ---
                elif word not in ['if', 'then', 'else', 'begin', 'until']:
                    # Execute standard word or literal
                    self._handle_word(token)
                    token_index += 1
                    continue

                # --- Control Structure Flow Control ---

                # Handle closing structures (These are implicit in Forth-style languages, 
                # but here we must look for structural keywords that signal closure if needed, 
                # though the prompt implies simple sequential execution unless a branch is taken.)
                # Since there are no explicit 'end' markers, closing is determined by the structure 
                # completion or flow control.

                # If we reach here, it means we hit a token that didn't match a known keyword 
                # or was a structural keyword that requires flow control management not fully defined here.
                # For robust implementation, we rely on the control_stack popping when the structure implicitly ends.

                # --- Control Flow Evaluation/Branching ---
                if control_stack:
                    frame_type, _, else_target = control_stack[-1]

                    if frame_type == 'if':
                        # If we executed past the 'if' condition (which was the token before 'then'), 
                        # and the stack top is the condition result (0 or -1).
                        if len(self.stack) >= 1 and self.stack[-1] in [0, -1]:
                            condition_result = self.stack.pop() # Pop the flag

                            if condition_result == -1: # True
                                # Continue normally (true branch was executed)
                                pass
                            else: # False (0)
                                if else_target is not None:
                                    # Jump to else branch start
                                    token_index = else_target
                                else:
                                    # No else branch, skip to after the entire if structure
                                    # This requires knowing the end index, which is complex without 'end'.
                                    # For simplicity matching Forth style, if no else, we assume flow continues after the current block.
                                    # A proper implementation would require knowing the end of the 'then' block.
                                    # We assume execution simply continues past the current token index if no else target is set.
                                    token_index += 1
                                    # (In a real system, we'd jump over the 'then' block)
                                    pass
                        else:
                            # Condition not evaluated yet, continue normally.
                            token_index += 1
                            continue

                    elif frame_type == 'begin':
                        # 'begin' blocks implicitly end when the next control structure begins or source ends.
                        # We only pop 'begin' when an explicit closer is found, or the scope ends.
                        pass

                # Default advance if no jumps/special handling occurred
                token_index += 1

        except StackError as e:
            # If an error occurs, state persists up to the point of the error token.
            raise e
        except ControlError as e:
            # Control errors happen before execution, state is pristine.
            raise e
        finally:
            # Clear the control stack upon completion of run
            control_stack.clear()

    def evaluate(self, source: str) -> List[int]:
        """Runs the source in a new Interpreter and returns the final stack."""
        # Reset state for evaluation
        evaluator = Interpreter(max_steps=self.max_steps)
        try:
            tokens = tokenize(source) # Uses the imported tokenizer
            evaluator.run(tokens)
            return evaluator.stack
        except Exception as e:
            # Re-raise specific errors, or wrap generic ones if needed
            if isinstance(e, StackError): 
                raise e
            # If tokenizer fails or another unexpected error occurs during evaluation,
            # it should be treated as a fatal setup error.
            raise StackError(f"Evaluation setup failed: {e}")
