                    control_stack.append(('if', token_index, -1 if not has_else else None))
                    token_index += 1
                    continue

                elif word == 'begin':
                    # Record start of 'begin' loop
                    control_stack.append(('begin', token_index, None))
                    token_index += 1
                    continue

                elif word == 'until':
                    # Until must follow a begin. Check stack.
                    if not control_stack or control_stack[-1][0] != 'begin':
                        raise ControlError("until without preceding begin", word, token.line, token.col)

                    # Set loop continuation point: the token immediately following 'until'
                    loop_start_index = token_index + 1
                    # Record the 'until' token index as the loop control point
                    control_stack[-1] = ('begin', control_stack[-1][1], loop_start_index)
                    token_index += 1
                    continue

                elif word == 'then':
                    if not control_stack or control_stack[-1][0] != 'if':
                        raise ControlError("then without preceding if", word, token.line, token.col)

                    # The token *after* 'then' is the start of the true branch.
                    # We don't need an explicit jump here, execution just continues.
                    token_index += 1
                    continue

                elif word == 'else':
                    if not control_stack or control_stack[-1][0] != 'if':
                        raise ControlError("else without preceding if", word, token.line, token.col)

                    # Find the 'if' frame and set the jump target to the token *after* 'else'
                    if_type, start_idx, _ = control_stack[-1]
                    if if_type == 'if':
                        # Set the jump target for the false branch
                        control_stack[-1] = (if_type, start_idx, token_index + 1)
                        token_index += 1
                        continue

                # --- Execution Phase (Words/Literals) ---
                elif word not in ['if', 'then', 'else', 'begin', 'until']: 
                    # Execute standard word or literal
                    self._handle_word(token)
                    token_index += 1
                    continue

                # --- Control Structure Flow Control ---

                if control_stack:
                    frame_type, _, else_target = control_stack[-1]

                    if frame_type == 'if':
                        # If we executed past the 'if' condition (which was the token before 'then'), 
                        # and the stack top is the condition result (0 or -1).
                        # NOTE: This logic assumes the condition token immediately precedes the check.
                        if len(self.stack) >= 1 and self.stack[-1] in [0, -1]:
                            condition_result = self.stack.pop() # Pop the flag

                            if condition_result == -1: # True
                                # Continue normally (true branch was executed)
                                pass
                            else: # False (0)
                                if else_target is not None:
                                    # Jump to else branch start
                                    token_index = else_target
                                else:
                                    # No else branch, skip to after the entire if structure
                                    # Since we lack an 'end', we advance normally, relying on subsequent logic/scope end.
                                    token_index += 1
                                    pass
                        else:
                            # Condition not evaluated yet, continue normally.
                            token_index += 1
                            continue

                    elif frame_type == 'begin':
                        # 'begin' blocks implicitly end when the next control structure begins or source ends.
                        pass

                # Default advance if no jumps/special handling occurred
                token_index += 1

        except StackError as e:
            # If an error occurs, state persists up to the point of the error token.
            raise e
        except ControlError as e:
            # Control errors happen before execution, state is pristine.
            raise e
        finally:
            # Clear the control stack upon completion of run
            control_stack.clear()

    def evaluate(self, source: str) -> List[int]:
        """Runs the source in a new Interpreter and returns the final stack."""
        # Reset state for evaluation
        evaluator = Interpreter(max_steps=self.max_steps)
        try:
            tokens = tokenize(source) # Uses the imported tokenizer
            evaluator.run(tokens)
            return evaluator.stack
        except Exception as e:
            # Re-raise specific errors, or wrap generic ones if needed
            if isinstance(e, StackError): 
                raise e
            # If tokenizer fails or another unexpected error occurs during evaluation,
            # it should be treated as a fatal setup error.
            raise StackError(f"Evaluation setup failed: {e}")

# =============================================================================
# REPL AND MAIN IMPLEMENTATION
# =============================================================================

def repl(infile: Union[str, io.TextIOBase], outfile: Union[str, io.TextIOBase], interp: Interpreter = None) -> int:
    """Interactive shell interface that runs each line of infile as a separate source.
    Maintains state between lines.
    """
    if interp is None:
        # Create a new interpreter instance for the session
        interp = Interpreter()

    print("--- STACK REPL STARTED ---\n")

    try:
        # Read line by line from infile
        if isinstance(infile, str):
            lines = infile.splitlines()
            infile_reader = io.StringIO(infile)
        else:
            infile_reader = infile

        for line in infile_reader:
            line = line.rstrip('\n')
            if not line.strip():
                # Skip empty lines
                print("ok")
                continue

            print(f"Executing: {line}")
            output_values = []
            try:
                # Run the line as a source. We must use the interpreter's run method directly
                # if we want to maintain state correctly across lines.
                tokens = tokenize(line) # Assume tokenize works on single line source
                interp.run(tokens)

                # Success output format: values separated by spaces, then 'ok'
                output_values = [str(v) for v in interp.output]
                print(f"{output_values[0]} {output_values[1]} ... ok" if len(output_values) > 1 else f"{output_values[0]} ok" if output_values else "ok")

            except StackError as e:
                # Failure output format: error: CLASSNAME: WORD
                class_name = type(e).__name__
                word = e.word if e.word is not None else "<unknown>"
                print(f"error: {class_name}: {word}")
            except NotImplementedError as e:
                # Handle the stub tokenizer error gracefully during testing
                print(f"error: TokenizationError: {e}")
            except Exception as e:
                 # Catch other potential interpreter/runtime issues
                print(f"error: RuntimeError: {type(e).__name__}")

        return 0

    finally:
        print("\n--- STACK REPL FINISHED ---")

def main(argv: List[str] = None) -> int:
    """Main entry point for stack/interp.py.
    Runs repl on stdin/stdout if no arguments, or runs a file if one argument is provided.
    """
    if argv is None:
        argv = sys.argv[1:]

    if not argv:
        # Run repl on stdin and stdout
        return repl(sys.stdin, sys.stdout)

    elif len(argv) == 1:
        file_path = argv[0]

        try:
            with open(file_path, 'r') as infile:
                source_code = infile.read()

                # Use a fresh interpreter for file execution
                interp = Interpreter()

                tokens = tokenize(source_code)

                try:
                    interp.run(tokens)

                    # Success: print values on one line
                    if interp.output:
                        print(' '.join(map(str, interp.output)))
                    else:
                        print()
                    return 0

                except StackError as e:
                    # Failure: write output produced so far, then error to stderr
                    if interp.output:
                        print(' '.join(map(str, interp.output)))
                    else:
                        print()

                    # Report detailed error to stderr
                    class_name = type(e).__name__
                    word = e.word if e.word is not None else "<unknown>"
                    line = e.line if e.line is not None else "<unknown>"
                    col = e.col if e.col is not None else "<unknown>"
                    sys.stderr.write(f"error: {class_name}: {word} at line {line}, column {col}\n")
                    return 1

        except FileNotFoundError:
            # File reading error
            sys.stderr.write("error: File not found.\n")
            return 2
        except Exception as e:
            # General read/other I/O error
            sys.stderr.write(f"error: Could not read file: {e}\n")
            return 2

    else:
        # Too many arguments
        sys.stderr.write("Usage: stack.interp [filepath]\n")
        return 1
