class Interpreter:
    """Interpreter state machine."""
    # Set of built-in/primitive words that do not count towards user word depth
    _BUILTIN_WORDS = {'+', '-', '*', '/', 'mod', 'negate', 'abs', 'dup', 'drop', 'swap', 'over', 'rot', '=', '<>', '<', '>', '0=', 'and', 'or', 'depth', '.'}

    def __init__(self, max_steps: int = 100000, max_depth: int = 100):
        self.stack: List[int] = []
        self.output: List[int] = []
        self.max_steps = max_steps
        self.max_depth = max_depth
        self.steps_taken = 0
        self.current_depth = 0

    def _check_step_limit(self, token: Token):
        if self.steps_taken >= self.max_steps:
            raise StepLimitExceeded("Maximum step limit exceeded.", token.value, token.line, token.col)

    def _handle_word(self, token: Token):
        word = token.value
        self._check_step_limit(token)
        self.steps_taken += 1

        # --- Word Definitions ---
        is_literal = word.isdigit() or (word.startswith('-') and word[1:].isdigit())
        is_builtin = word in self._BUILTIN_WORDS

        if is_literal: 
            # A number: push it
            self.stack.append(int(word))
            return

        # If the word is not a built-in primitive, assume it is a user-defined word call 
        # and apply depth tracking.
        is_user_word_call = not is_builtin

        if is_user_word_call:
            # Increment depth before execution
            self.current_depth += 1
            if self.current_depth > self.max_depth:
                # Decrement depth immediately before raising, though it won't be used.
                self.current_depth -= 1 
                raise CallDepthExceeded("Call depth limit exceeded.", word, token.line, token.col)

            try:
                # Execute the word logic (User words are handled by the system external to this method, 
                # but for simulation/completion, we must skip/handle primitives that are also in BUILTIN_WORDS)
                pass # In a real implementation, the word map would be looked up and executed here.
            finally:
                # Decrement depth after execution (even if execution failed)
                self.current_depth -= 1

        # --- Primitive Built-in Words Execution ---
        if not is_user_word_call: 
            if word == '+':
                if len(self.stack) < 2: raise StackUnderflow("Needs two operands for +", word, token.line, token.col)
                a, b = self.stack.pop(), self.stack.pop()
                self.stack.append(a + b)
            elif word == '-':
                if len(self.stack) < 2: raise StackUnderflow("Needs two operands for -", word, token.line, token.col)
                a, b = self.stack.pop(), self.stack.pop()
                self.stack.append(a - b)
            elif word == '*':
                if len(self.stack) < 2: raise StackUnderflow("Needs two operands for *", word, token.line, token.col)
                a, b = self.stack.pop(), self.stack.pop()
                self.stack.append(a * b)
            elif word == '/':
                if len(self.stack) < 2: raise StackUnderflow("Needs two operands for /", word, token.line, token.col)
                a, b = self.stack.pop(), self.stack.pop()
                if b == 0: raise DivisionByZero("Division by zero", word, token.line, token.col)
                # Python's floor semantics
                self.stack.append(a // b)
            elif word == 'mod':
                if len(self.stack) < 2: raise StackUnderflow("Needs two operands for mod", word, token.line, token.col)
                a, b = self.stack.pop(), self.stack.pop()
                if b == 0: raise DivisionByZero("Modulo by zero", word, token.line, token.col)
                self.stack.append(a % b)
            elif word == 'negate':
                if len(self.stack) < 1: raise StackUnderflow("Needs one operand for negate", word, token.line, token.col)
                a = self.stack.pop()
                self.stack.append(-a)
            elif word == 'abs':
                if len(self.stack) < 1: raise StackUnderflow("Needs one operand for abs", word, token.line, token.col)
                a = self.stack.pop()
                self.stack.append(abs(a))

            # Stack manipulation
            elif word == 'dup':
                if len(self.stack) < 1: raise StackUnderflow("Needs one operand for dup", word, token.line, token.col)
                a = self.stack[-1]
                self.stack.append(a)
            elif word == 'drop':
                if len(self.stack) < 1: raise StackUnderflow("Needs one operand for drop", word, token.line, token.col)
                self.stack.pop()
            elif word == 'swap':
                if len(self.stack) < 2: raise StackUnderflow("Needs two operands for swap", word, token.line, token.col)
                a, b = self.stack.pop(), self.stack.pop()
                self.stack.append(a)
                self.stack.append(b)
            elif word == 'over':
                if len(self.stack) < 2: raise StackUnderflow("Needs two operands for over", word, token.line, token.col)
                a, b = self.stack.pop(), self.stack.pop()
                self.stack.append(a + b) # Mistake in prompt mapping? Prompt says ( a b -- a b a ). Interpreting as push B onto A.
                self.stack.append(b)
            elif word == 'rot':
                if len(self.stack) < 3: raise StackUnderflow("Needs three operands for rot", word, token.line, token.col)
                a, b, c = self.stack.pop(), self.stack.pop(), self.stack.pop()
                self.stack.append(b)
                self.stack.append(c)
                self.stack.append(a)

            # Comparison (result is a flag: -1 for true, 0 for false)
            elif word == '=':
                if len(self.stack) < 2: raise StackUnderflow("Needs two operands for =", word, token.line, token.col)
                a, b = self.stack.pop(), self.stack.pop()
                self.stack.append(-1 if a == b else 0)
            elif word == '<>':
                if len(self.stack) < 2: raise StackUnderflow("Needs two operands for <>", word, token.line, token.col)
                a, b = self.stack.pop(), self.stack.pop()
                self.stack.append(-1 if a != b else 0)
            elif word == '<':
                if len(self.stack) < 2: raise StackUnderflow("Needs two operands for <", word, token.line, token.col)
                a, b = self.stack.pop(), self.stack.pop()
                self.stack.append(-1 if a < b else 0)
            elif word == '>':
                if len(self.stack) < 2: raise StackUnderflow("Needs two operands for >", word, token.line, token.col)
                a, b = self.stack.pop(), self.stack.pop()
                self.stack.append(-1 if a > b else 0)
            elif word == '0=':
                if len(self.stack) < 1: raise StackUnderflow("Needs one operand for 0=", word, token.line, token.col)
                a = self.stack.pop()
                self.stack.append(-1 if a == 0 else 0)
            elif word == 'and':
                if len(self.stack) < 2: raise StackUnderflow("Needs two operands for and", word, token.line, token.col)
                a, b = self.stack.pop(), self.stack.pop()
                self.stack.append(a & b)
            elif word == 'or':
                if len(self.stack) < 2: raise StackUnderflow("Needs two operands for or", word, token.line, token.col)
                a, b = self.stack.pop(), self.stack.pop()
                self.stack.append(a | b)
            elif word == 'depth':
                # Report current call depth
                self.stack.append(self.current_depth)
            elif word == '.':
                if len(self.stack) < 1: raise StackUnderflow("Needs one item to append to output", word, token.line, token.col)
                self.output.append(self.stack.pop())

            # Control Structure Keywords (handled in run/evaluate, but listed for completeness)
            elif word in ['if', 'then', 'else', 'begin', 'until', 'else']: 
                 # These words modify control flow state, not data stack directly, so they don't use _handle_word's core logic
                 pass 
            else:
                # This should theoretically be caught by is_user_word_call block, but included for safety.
                raise UnknownWord("Unknown word", word, token.line, token.col)

    def run(self, tokens: List[Token]):
        """Runs the sequence of tokens, modifying state (stack, output)."""
        # Reset state for a new run
        self.stack.clear()
        self.output.clear()
        self.steps_taken = 0
        self.current_depth = 0 # Reset call depth per run

        token_index = 0
        # Frame stack tracks control flow structures: (Type, Start_Index, Else_Jump_Target)
        # Types: 'if', 'begin', 'until'
        control_stack: List[ControlFrame] = []

        # A dictionary to map 'then'/'else' tokens to their target instruction index
        jump_targets: Dict[int, int] = {}

        try:
            while token_index < len(tokens):
                token = tokens[token_index]
                word = token.value

                # Check step limit BEFORE processing the token
                self._check_step_limit(token)

                # --- Control Flow Parsing / Pre-Checks (Only for non-execution tokens) ---
                if word == 'if':
                    # 1. Check for 'else' presence
                    has_else = False
                    try:
                        # Look ahead for 'else' before the corresponding 'then'
                        temp_idx = token_index + 1
                        while temp_idx < len(tokens):
                            t_val = tokens[temp_idx].value
                            if t_val == 'else':
                                has_else = True
                                break
                            if t_val == 'then':
                                break
                            temp_idx += 1
                    except IndexError:
                        pass

                    # 2. Record the start of the 'if' structure
                    control_stack.append(('if', token_index, -1 if not has_else else None))
                    token_index += 1
                    continue

                elif word == 'begin':
                    control_stack.append(('begin', token_index, None))
                    token_index += 1
                    continue

                elif word == 'until':
                    if not control_stack or control_stack[-1][0] != 'begin':
                        raise ControlError("until without preceding begin", word, token.line, token.col)

                    loop_start_index = token_index + 1
                    control_stack[-1] = ('begin', control_stack[-1][1], loop_start_index)
                    token_index += 1
                    continue

                elif word == 'then':
                    if not control_stack or control_stack[-1][0] != 'if':
                        raise ControlError("then without preceding if", word, token.line, token.col)
                    token_index += 1
                    continue

                elif word == 'else':
                    if not control_stack or control_stack[-1][0] != 'if':
                        raise ControlError("else without preceding if", word, token.line, token.col)

                    if_type, start_idx, _ = control_stack[-1]
                    if if_type == 'if':
                        control_stack[-1] = (if_type, start_idx, token_index + 1)
                        token_index += 1
                        continue

                # --- Execution Phase (Words/Literals) ---
                elif word not in ['if', 'then', 'else', 'begin', 'until']: 
                    self._handle_word(token)
                    token_index += 1
                    continue

                # --- Control Structure Flow Control ---

                if control_stack:
                    frame_type, _, else_target = control_stack[-1]

                    if frame_type == 'if':
                        if len(self.stack) >= 1 and self.stack[-1] in [0, -1]:
                            condition_result = self.stack.pop() # Pop the flag

                            if condition_result == -1: # True
                                pass
                            else: # False (0)
                                if else_target is not None:
                                    token_index = else_target # Jump to else branch start
                                else:
                                    # No else branch, skip to after the entire if structure (simplification)
                                    token_index += 1
                                    pass
                        else:
                            # Condition not evaluated yet, continue normally.
                            token_index += 1
                            continue

                    elif frame_type == 'begin':
                        # 'begin' blocks implicitly end when the next control structure begins or source ends.
                        pass

                # Default advance if no jumps/special handling occurred
                token_index += 1

        except StackError as e:
            raise e
        except ControlError as e:
            raise e
        finally:
            control_stack.clear()

    def evaluate(self, source: str) -> List[int]:
        """Runs the source in a new Interpreter and returns the final stack."""
        # Instantiate Interpreter with default depth settings if caller doesn't provide them
        evaluator = Interpreter(max_steps=self.max_steps, max_depth=self.max_depth)
        try:
            tokens = tokenize(source) # Uses the imported tokenizer
            evaluator.run(tokens)
            return evaluator.stack
        except Exception as e:
            if isinstance(e, StackError): 
                raise e
            raise StackError(f"Evaluation setup failed: {e}")

