                        raise ControlError("then without preceding if", word, token.line, token.col)
                    token_index += 1
                    continue

                elif word == 'else':
                    if not control_stack or control_stack[-1][0] != 'if':
                        raise ControlError("else without preceding if", word, token.line, token.col)

                    if if_type, start_idx, _ = control_stack[-1]:
                        # Set the jump target for the false branch
                        control_stack[-1] = (if_type, start_idx, token_index + 1)
                        token_index += 1
                        continue

                # --- Execution Phase (Words/Literals) ---
                elif word not in ['if', 'then', 'else', 'begin', 'until']:
                    # Execute standard word or literal
                    try:
                        self._handle_word(token)
                    except StackError as e:
                        # Propagate stack errors immediately
                        raise e
                    token_index += 1
                    continue

                # --- Control Flow Evaluation/Branching (Highly Simplified) ---
                if control_stack:
                    frame_type, _, else_target = control_stack[-1]

                    if frame_type == 'if' and len(self.stack) >= 1 and self.stack[-1] in [0, -1]:
                        condition_result = self.stack.pop() 

                        if condition_result == -1: # True
                            pass # Continue normally
                        else: # False (0)
                            if else_target is not None:
                                token_index = else_target # Jump to else branch
                                continue
                            else:
                                # No else branch, assume flow continues after the structure.
                                # Needs structure end token/index to jump over 'then' block.
                                pass

                token_index += 1

        finally:
            control_stack.clear()

        return self.stack, tokens[:token_index]

    def evaluate(self, source: str) -> Tuple[List[int], List[Token]]:
        """Runs the source in a new Interpreter and returns the final stack and consumed tokens."""
        evaluator = Interpreter(max_steps=self.max_steps, max_depth=self.max_depth)
        try:
            tokens = tokenize(source) # Assume tokenizer handles definitions
            # Load definitions first
            tokens = evaluator.load_definitions(tokens)
