            if not isinstance(entry.oid, str) or not entry.oid.isalnum(): # Basic sanity check for oid
                 raise ValueError(f"Invalid oid in TreeEntry: {entry.oid}")

        # Store the sorted tuple to guarantee immutability and consistency
        object.__setattr__(self, 'entries', tuple(sorted_entries))

    @classmethod
    def from_entries(cls, entries: Iterable[TreeEntry]):
