        """Checks if an oid is stored."""
        return oid in self._objects

    def resolve(self, prefix: str) -> str:
        """Returns the one stored oid that starts with prefix."""
        if not (4 <= len(prefix) <= 40 and all(c in '0123456789abcdef' for c in prefix)):
            raise ValueError("Prefix must be 4 to 40 lowercase hex characters.")

        matching_oids = [oid for oid in self._objects.keys() if oid.startswith(prefix)]

        if not matching_oids:
            raise ObjectNotFound(f"No object found starting with prefix {prefix}.")

        if len(matching_oids) > 1:
            raise AmbiguousPrefix(f"Multiple objects found starting with prefix {prefix}: {matching_oids}")

