class ObjectStore:
    """In-memory store for content-addressed objects."""
    def __init__(self):
        # Stores {oid: object} for objects
        self._objects: Dict[str, Any] = {}
        # Stores {oid: raw_data} for raw serializations (though usually we store objects)
        self._raw_data: Dict[str, bytes] = {}

    def put(self, obj: Any) -> str:
        """Stores an object and returns its oid."""
        oid = object_id(obj)
        self._objects[oid] = obj
        return oid

    def put_raw(self, raw: bytes) -> str:
        """Stores a raw serialization after validating it, and returns its oid."""
        try:
            obj = parse_object(raw)
            oid = object_id(obj)
            self._objects[oid] = obj
            self._raw_data[oid] = raw
            return oid
        except CorruptObject as e:
            raise ValueError(f"Invalid object serialization: {e}") from e

    def get(self, oid: str) -> Any:
        """Returns the object corresponding to the oid."""
        if oid not in self._objects:
            raise ObjectNotFound(f"Object with oid {oid} not found.")
        return self._objects[oid]

    def get_raw(self, oid: str) -> bytes:
        """Returns the raw serialization corresponding to the oid."""
        if oid not in self._raw_data:
            raise ObjectNotFound(f"Raw data for oid {oid} not found.")
        return self._raw_data[oid]

    def __contains__(self, oid: str) -> bool:
        """Checks if an oid is stored."""
        return oid in self._objects

    def resolve(self, prefix: str) -> str:
        """Returns the one stored oid that starts with prefix."""
        if not (4 <= len(prefix) <= 40 and all(c in '0123456789abcdef' for c in prefix)):
            raise ValueError("Prefix must be 4 to 40 lowercase hex characters.")

        matching_oids = [oid for oid in self._objects.keys() if oid.startswith(prefix)]

        if not matching_oids:
            raise ObjectNotFound(f"No object found starting with prefix {prefix}.")

        if len(matching_oids) > 1:
            raise AmbiguousPrefix(f"Multiple objects found starting with prefix {prefix}: {matching_oids}")

        return matching_oids[0]

