        if oid in self._objects:
            return oid # Storing the same object twice is harmless
        self._objects[oid] = obj
        return oid

    def put_raw(self, raw: bytes) -> str:
        """Stores a raw serialization after validating it, and returns its oid."""
        try:
            obj = parse_object(raw)
            oid = object_id(obj)
            self._objects[oid] = obj
            self._raw_data[oid] = raw
            return oid
