            raise TypeError("Object at given oid is not a Tree.")

        read_files: Dict[str, bytes] = {}

        def traverse(entries: list[TreeEntry], current_path: str = ""):
            for entry in entries:
                name = entry.name
                full_path = f"{current_path}/{name}" if current_path else name

                if entry.kind == 'blob':
                    blob = self.get(entry.oid)
                    if not isinstance(blob, Blob):
                        raise CorruptObject(f"OID {entry.oid} referenced by tree entry is not a Blob.")
                    read_files[full_path] = blob.data
                elif entry.kind == 'tree':
                    sub_tree = self.get(entry.oid)
                    if not isinstance(sub_tree, Tree):
                        raise CorruptObject(f"OID {entry.oid} referenced by tree entry is not a Tree.")
                    traverse(sub_tree.entries, full_path)

        traverse(tree.entries)
        return read_files

    def commit(self, tree_oid: str, parents: Tuple[str, ...], *, author: str, timestamp: int, message: str) -> str:
        """Stores a Commit object and returns its oid."""
        # Validation checks
        if not isinstance(timestamp, int) or timestamp < 0:
            raise ValueError("Timestamp must be an integer >= 0.")
        if "\n" in author:
            raise ValueError("Author string must not contain newline characters.")
        if not isinstance(parents, tuple):
            raise ValueError("Parents must be provided as a tuple.")

        # Check if tree is stored and is a Tree
        try:
            tree_obj = self.get(tree_oid)
            if not isinstance(tree_obj, Tree):
                raise ValueError("Tree OID does not point to a Tree object.")
        except ObjectNotFound:
            raise ObjectNotFound(f"Tree OID {tree_oid} not found in store.")

        # Check if parents are stored and are Commits
        for p_oid in parents:
            try:
                parent_obj = self.get(p_oid)
                if not isinstance(parent_obj, Commit):
                    raise ValueError("Parent OID does not point to a Commit object.")
            except ObjectNotFound:
                raise ObjectNotFound(f"Parent OID {p_oid} not found in store.")

        commit_obj = Commit(
            tree=tree_oid, 
            parents=parents, 
            author=author, 
            timestamp=timestamp, 
            message=message
        )
        return self.put(commit_obj)

    def log(self, oid: str, first_parent: bool = False) -> list[str]:
        """Returns commit oids walking history."""
        if oid not in self._objects:
            raise ObjectNotFound(f"Commit with oid {oid} not found.")

        current_oid = oid
        history: Dict[str, Tuple[int, str]] = {}
        ordered_oids: list[str] = []

        # Phase 1: Collect all reachable commits and their timestamps
        queue = [oid]
        visited = {oid}

        while queue:
            current_id = queue.pop(0)
            try:
                commit_obj: Commit = self.get(current_id)
                history[current_id] = (commit_obj.timestamp, commit_obj.oid)

                if first_parent:
                    # Only follow the first parent
                    if commit_obj.parents:
                        p_oid = commit_obj.parents[0]
                        if p_oid not in visited:
                            visited.add(p_oid)
                            queue.append(p_oid)
                else:
                    # Follow all parents
                    for p_oid in commit_obj.parents:
                        if p_oid not in visited:
                            visited.add(p_oid)
                            queue.append(p_oid)
            except ObjectNotFound:
                # Should not happen if we start with a valid oid, but robust.
                pass

        # Phase 2: Sort and return
        # Default: ordered by timestamp, newest first, then oid ascending for ties.
        # first_parent=True: only contains the direct lineage, which is already implicitly ordered by how we traversed it if we process the list sequentially, but we need to guarantee order based on timestamp if multiple parents existed, though first_parent=True limits this.

        if first_parent:
            # If first_parent is true, the traversal already follows a single line. We just need to ensure we process them in timestamp order, which is easiest if we reconstruct the path explicitly, but since the queue method might mix up the order slightly if multiple branches were considered before filtering, we rely on the stored history.
            # For first_parent=True, we trace the path explicitly to guarantee order.
            path = []
            curr = oid
            while curr is not None and curr in history:
                path.append(curr)
