            return path

        else: # Default mode (all ancestors)
            # Sort by timestamp (descending: newest first), then by oid (ascending)
            sorted_items = sorted(
                history.items(), 
                key=lambda item: (-item[1][0], item[0]) # (-timestamp, oid)
            )
            return [item[0] for item in sorted_items]

