# --- Money Parsing and Formatting ---

def parse_amount(text: str) -> int:
    """
    Accepts a string representation of an amount (digits optionally followed by '.' and one or two digits) 
    and returns the amount in cents (int).
    Raises ValueError for invalid input.
    """
    try:
        amount_decimal = decimal.Decimal(text)

        # Validation for format 'digits' or 'digits.dd' (up to two decimals)
        # We check if the string representation matches the expected pattern after conversion.
        # This is a simplified check; robust format validation usually requires regex.
        if '.' in text:
            parts = text.split('.')
            if len(parts) != 2 or not parts[0].isdigit() or not parts[1].isdigit() or len(parts[1]) > 2:
                 raise ValueError(f"Invalid decimal format: '{text}'")
        elif not text.isdigit():
            raise ValueError(f"Invalid integer format: '{text}'")

        # Convert to cents: multiply by 100 and round to nearest integer
        cents = int(round(amount_decimal * 100))
        return cents
    except decimal.InvalidOperation:
        raise ValueError(f"Invalid amount format: '{text}'")
    except ValueError as e:
        # Re-raise custom format errors
        raise ValueError(f"Invalid amount format: '{text}' - {e}")

def format_amount(cents: int) -> str:
    """
    Returns the amount in cents as a string with exactly two decimals, 
    using '-' for negative amounts.
    """
    return f"{cents / 100:.2f}"

# --- Splitters ---

@dataclass(frozen=True)
class Equal:
    """Shared equally among listed members or all group members if members is None."""
    members: Optional[List[str]] = None

    def __post_init__(self):
        if self.members is not None and len(set(self.members)) != len(self.members):
            raise ValueError("Equal split members list must not contain duplicates.")

@dataclass(frozen=True)
class Exact:
    """Shares defined explicitly per member."""
    shares: Dict[str, int]

    def __post_init__(self):
        if not all(share >= 0 for share in self.shares.values()):
            raise ValueError("All exact shares must be non-negative.")

@dataclass(frozen=True)
class Percent:
    """Shares defined as percentages per member."""
    shares: Dict[str, Union[int, str, decimal.Decimal]]

    def __post_init__(self):
        total_percentage = 0
        for percentage in self.shares.values():
            if not isinstance(percentage, (int, decimal.Decimal)):
                try:
                    percentage = decimal.Decimal(str(percentage))
                except decimal.InvalidOperation:
                    raise ValueError("Percent shares must be convertible to numbers.")

            if percentage < 0:
                raise ValueError("All percentage shares must be non-negative.")

            # Ensure we are summing Decimals for accurate comparison
            total_percentage += decimal.Decimal(str(percentage))

        # Check if the sum is exactly 100% (using high precision comparison)
        if abs(total_percentage - decimal.Decimal('100.0')) > decimal.Decimal('0.00001'):
            raise ValueError(f"Percentage shares must sum exactly to 100%. Current sum: {total_percentage:.2f}")

