        # Convert to cents (multiply by 100 and round to nearest integer)
        cents = int(round(amount_decimal * 100))

        # Basic sanity check: ensure the original string was not excessively long or complex if it parsed
        if not (len(text) <= 10) and not ('.' in text and len(text.split('.')[1]) <= 2):
             raise ValueError(f"Amount string '{text}' seems improperly formatted.")

        return cents
    except decimal.InvalidOperation:
        raise ValueError(f"Invalid amount format: '{text}'. Must be digits[.dd].")

def format_amount(cents: int) -> str:
    """
    Returns the amount in cents as a string with exactly two decimals, 
    using '-' for negative amounts.
    """
